            state_dir,
            generation_flag,
            generation,
            owner_flag,
            owner_process_id,
            digest_flag,
            digest,
        ]
            if command == "supervise-managed"
                && state_flag == "--state-dir"
                && generation_flag == "--generation"
                && owner_flag == "--owner-process-id"
                && digest_flag == "--runtime-sha256" =>
