#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn resident_hmac_matches_cross_language_vectors() {
        let token = [7u8; AUTH_TOKEN_BYTES];
        let nonce = [9u8; AUTH_NONCE_BYTES];
        let server = hmac_sha256(&token, SERVER_PROOF_LABEL, &nonce);
        let client = hmac_sha256(&token, CLIENT_PROOF_LABEL, &nonce);
        assert_eq!(
            server,
            [
                0xb8, 0x19, 0x89, 0x8f, 0x11, 0x87, 0x8c, 0x1c, 0x14, 0x84, 0x23, 0xd0, 0x36, 0x1a,
                0x9d, 0xe2, 0x0d, 0x9e, 0xca, 0x3b, 0xb8, 0x6c, 0xe1, 0x21, 0x4c, 0xee, 0x95, 0x7f,
                0x95, 0xbb, 0x06, 0xc4,
            ]
        );
        assert_eq!(
            client,
            [
                0xfe, 0xf8, 0x3d, 0x9f, 0xf5, 0x98, 0x89, 0x22, 0xef, 0x5c, 0x4c, 0x7b, 0x54, 0xd9,
                0xc6, 0x66, 0xab, 0xf4, 0x2f, 0xdf, 0xa8, 0x39, 0x44, 0x8b, 0x57, 0x9f, 0x65, 0x07,
                0x41, 0xd0, 0x6d, 0x97,
            ]
        );
        assert_ne!(server, client);
        assert!(constant_time_eq(&server, &server));
        assert!(!constant_time_eq(&server, &client));
    }

    #[test]
    fn strict_json_rejects_duplicate_keys_and_trailing_values() {
        assert!(strict_json_value(br#"{"a":1,"a":2}"#).is_err());
        assert!(strict_json_value(br#"{"a":1} {}"#).is_err());
    }

    #[test]
    fn strict_json_rejects_deep_and_wide_values() {
        let deep = format!(
            "{}0{}",
            "[".repeat(strict_json::TEST_MAX_JSON_DEPTH + 2),
            "]".repeat(strict_json::TEST_MAX_JSON_DEPTH + 2)
        );
        assert!(strict_json_value(deep.as_bytes()).is_err());
        let wide = format!(
            "[{}]",
            std::iter::repeat_n("0", strict_json::TEST_MAX_JSON_COLLECTION_ITEMS + 1)
                .collect::<Vec<_>>()
                .join(",")
        );
        assert!(strict_json_value(wide.as_bytes()).is_err());
    }

    #[test]
    fn overload_response_is_constant_and_retryable() {
        assert_eq!(
            resident_protocol::error_response("native_overloaded", true),
            b"{\"error\":\"native_overloaded\",\"retryable\":true}".to_vec()
        );
    }

    #[test]
    fn resident_hmac_changes_with_nonce() {
        let token = [3u8; AUTH_TOKEN_BYTES];
        let mut first_nonce = [1u8; AUTH_NONCE_BYTES];
        let second_nonce = [2u8; AUTH_NONCE_BYTES];
        let first = hmac_sha256(&token, SERVER_PROOF_LABEL, &first_nonce);
        let second = hmac_sha256(&token, SERVER_PROOF_LABEL, &second_nonce);
        assert_ne!(first, second);
        first_nonce[0] ^= 1;
        assert_ne!(first, hmac_sha256(&token, SERVER_PROOF_LABEL, &first_nonce));
    }
}

#!/usr/bin/env python3
"""Build one platform-specific HOL Guard wheel from the verified pure wheel.

The native runtime is injected into ``codex_plugin_scanner/_native``. The
source wheel is never modified in place, and this builder refuses any project
other than ``hol-guard``. It rewrites only wheel metadata required by the
platform artifact plus RECORD hashes.
"""

from __future__ import annotations

import argparse
import base64
import csv
import hashlib
import io
import json
import os
import re
import stat
import subprocess
import unicodedata
import zipfile
from dataclasses import dataclass
from email.parser import BytesParser
from pathlib import Path, PurePosixPath
from typing import BinaryIO

_MAX_RUNTIME_BYTES = 128 * 1024 * 1024
_MAX_SOURCE_WHEEL_BYTES = 256 * 1024 * 1024
_MAX_SOURCE_ENTRY_BYTES = 64 * 1024 * 1024
_MAX_SOURCE_UNCOMPRESSED_BYTES = 512 * 1024 * 1024
_MAX_SOURCE_ENTRIES = 16_384
_MAX_CAPABILITIES_BYTES = 64 * 1024
_PLATFORM_TAG_RE = re.compile(r"^[A-Za-z0-9_.]+$")
_SHA40_RE = re.compile(r"^[0-9a-f]{40}$")
_SHA64_RE = re.compile(r"^[0-9a-f]{64}$")
_NATIVE_DIR = "codex_plugin_scanner/_native"
_RUNTIME_MANIFEST_PATH = f"{_NATIVE_DIR}/runtime-manifest.json"
_DETERMINISTIC_TIMESTAMP = (1980, 1, 1, 0, 0, 0)


class NativeWheelError(ValueError):
    """Raised when a source artifact cannot safely become a native wheel."""


@dataclass(frozen=True, slots=True)
class SourceWheel:
    path: Path
    dist_info: str
    metadata_path: str
    wheel_path: str
    record_path: str
    entries: dict[str, bytes]
    modes: dict[str, int]


@dataclass(frozen=True, slots=True)
class RuntimeCapabilities:
    protocol_version: int
    runtime_version: str
    rule_digest: str
    build_sha: str


def _wheel_version_for_filename(version: str) -> str:
    return version.replace("-", "_")


def _safe_archive_path(name: str) -> bool:
    if (
        not name
        or "\\" in name
        or "\x00" in name
        or any(ord(character) < 0x20 for character in name)
    ):
        return False
    path = PurePosixPath(name)
    if path.is_absolute() or ".." in path.parts or any(part in {"", "."} for part in path.parts):
        return False
    # Wheel member names are canonical POSIX paths. Reject repeated separators,
    # dot segments, trailing separators, and other spellings that normalize to
    # a different installed path.
    return str(path) == name


def _canonical_archive_key(name: str) -> str:
    """Return a conservative collision key for case/Unicode-normalizing hosts."""
    return unicodedata.normalize("NFC", name).casefold()


def _entry_mode(info: zipfile.ZipInfo) -> int:
    raw = info.external_attr >> 16
    if raw and stat.S_ISLNK(raw):
        raise NativeWheelError(f"source wheel contains a symlink entry: {info.filename}")
    mode = stat.S_IMODE(raw) if raw else 0
    return mode or 0o644


def _open_regular_file(path: Path, *, max_bytes: int, label: str) -> BinaryIO:
    """Open one immutable-by-identity regular file without following POSIX symlinks."""
    lexical = path.expanduser()
    try:
        before = lexical.lstat()
    except OSError as exc:
        raise NativeWheelError(f"{label} must be a regular non-symlink file") from exc
    if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
        raise NativeWheelError(f"{label} must be a regular non-symlink file")
    if before.st_size <= 0 or before.st_size > max_bytes:
        raise NativeWheelError(f"{label} size is outside the accepted release bounds")

    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(lexical, flags)
    except OSError as exc:
        raise NativeWheelError(f"{label} could not be opened safely") from exc
    try:
        opened = os.fstat(fd)
        if not stat.S_ISREG(opened.st_mode) or opened.st_size != before.st_size:
            raise NativeWheelError(f"{label} changed while being opened")
        before_identity = (getattr(before, "st_dev", None), getattr(before, "st_ino", None))
        opened_identity = (getattr(opened, "st_dev", None), getattr(opened, "st_ino", None))
        identities_available = all(
            value not in {None, 0}
            for value in (*before_identity, *opened_identity)
        )
        if identities_available and before_identity != opened_identity:
            raise NativeWheelError(f"{label} changed while being opened")
        return os.fdopen(fd, "rb")
    except Exception:
        os.close(fd)
        raise


def _validate_source_archive_bounds(infos: list[zipfile.ZipInfo]) -> None:
    files = [info for info in infos if not info.is_dir()]
    if len(files) > _MAX_SOURCE_ENTRIES:
        raise NativeWheelError("source wheel contains too many entries")
    total_uncompressed = 0
    for info in files:
        if info.flag_bits & 0x1:
            raise NativeWheelError(f"source wheel contains an encrypted entry: {info.filename}")
        if info.file_size < 0 or info.file_size > _MAX_SOURCE_ENTRY_BYTES:
            raise NativeWheelError(f"source wheel entry is too large: {info.filename}")
        total_uncompressed += info.file_size
        if total_uncompressed > _MAX_SOURCE_UNCOMPRESSED_BYTES:
            raise NativeWheelError("source wheel uncompressed size exceeds the accepted release bound")


def _read_zip_entry_bounded(archive: zipfile.ZipFile, info: zipfile.ZipInfo) -> bytes:
    content = bytearray()
    try:
        with archive.open(info, "r") as handle:
            while True:
                chunk = handle.read(min(64 * 1024, _MAX_SOURCE_ENTRY_BYTES + 1 - len(content)))
                if not chunk:
                    break
                content.extend(chunk)
                if len(content) > _MAX_SOURCE_ENTRY_BYTES or len(content) > info.file_size:
                    raise NativeWheelError(f"source wheel entry expanded past its declared size: {info.filename}")
    except (OSError, RuntimeError, zipfile.BadZipFile) as exc:
        raise NativeWheelError(f"source wheel entry could not be read safely: {info.filename}") from exc
    if len(content) != info.file_size:
        raise NativeWheelError(f"source wheel entry size changed while reading: {info.filename}")
    return bytes(content)


def _load_source_wheel(path: Path, *, version: str) -> SourceWheel:
    expected_name = f"hol_guard-{_wheel_version_for_filename(version)}-py3-none-any.whl"
    if path.name != expected_name:
        raise NativeWheelError(f"expected pure hol-guard wheel {expected_name}, got {path.name}")

    entries: dict[str, bytes] = {}
    modes: dict[str, int] = {}
    with (
        _open_regular_file(path, max_bytes=_MAX_SOURCE_WHEEL_BYTES, label="source wheel") as source_file,
        zipfile.ZipFile(source_file, "r") as archive,
    ):
        infos = archive.infolist()
        _validate_source_archive_bounds(infos)
        names = [info.filename for info in infos if not info.is_dir()]
        if len(names) != len(set(names)):
            raise NativeWheelError("source wheel contains duplicate entries")
        canonical_names: set[str] = set()
        for info in infos:
            if info.is_dir():
                continue
            if not _safe_archive_path(info.filename):
                raise NativeWheelError(f"source wheel contains an unsafe path: {info.filename}")
            collision_key = _canonical_archive_key(info.filename)
            if collision_key in canonical_names:
                raise NativeWheelError(f"source wheel contains a canonical path collision: {info.filename}")
            canonical_names.add(collision_key)
            entries[info.filename] = _read_zip_entry_bounded(archive, info)
            modes[info.filename] = _entry_mode(info)

    wheel_paths = [name for name in entries if name.endswith(".dist-info/WHEEL")]
    metadata_paths = [name for name in entries if name.endswith(".dist-info/METADATA")]
    record_paths = [name for name in entries if name.endswith(".dist-info/RECORD")]
    if len(wheel_paths) != 1 or len(metadata_paths) != 1 or len(record_paths) != 1:
        raise NativeWheelError("source wheel must contain exactly one WHEEL, METADATA, and RECORD")

    wheel_path = wheel_paths[0]
    metadata_path = metadata_paths[0]
    record_path = record_paths[0]
    dist_info = wheel_path.rsplit("/", 1)[0]
    if metadata_path.rsplit("/", 1)[0] != dist_info or record_path.rsplit("/", 1)[0] != dist_info:
        raise NativeWheelError("source wheel dist-info metadata is inconsistent")

    metadata = BytesParser().parsebytes(entries[metadata_path])
    if metadata.get("Name") != "hol-guard" or metadata.get("Version") != version:
        raise NativeWheelError("source wheel project identity or version does not match")

    wheel_text = entries[wheel_path].decode("utf-8")
    tags = [
        line.removeprefix("Tag:").strip()
        for line in wheel_text.splitlines()
        if line.startswith("Tag:")
    ]
    if tags != ["py3-none-any"]:
        raise NativeWheelError("source wheel must be the canonical py3-none-any artifact")
    if f"{_NATIVE_DIR}/hol-guard-runtime" in entries or f"{_NATIVE_DIR}/hol-guard-runtime.exe" in entries:
        raise NativeWheelError("source wheel already contains a native runtime")
    if _RUNTIME_MANIFEST_PATH in entries:
        raise NativeWheelError("source wheel already contains a native runtime manifest")

    return SourceWheel(
        path=path,
        dist_info=dist_info,
        metadata_path=metadata_path,
        wheel_path=wheel_path,
        record_path=record_path,
        entries=entries,
        modes=modes,
    )


def _load_runtime(path: Path) -> bytes:
    with _open_regular_file(path, max_bytes=_MAX_RUNTIME_BYTES, label="runtime") as handle:
        metadata = os.fstat(handle.fileno())
        if os.name != "nt":
            mode = stat.S_IMODE(metadata.st_mode)
            if mode & 0o022:
                raise NativeWheelError("runtime is group/world writable")
            if not mode & stat.S_IXUSR:
                raise NativeWheelError("runtime is not owner-executable")
        runtime = handle.read(_MAX_RUNTIME_BYTES + 1)
        after = os.fstat(handle.fileno())
        if len(runtime) > _MAX_RUNTIME_BYTES:
            raise NativeWheelError("runtime size is outside the accepted release bounds")
        if (metadata.st_size, metadata.st_mtime_ns) != (after.st_size, after.st_mtime_ns):
            raise NativeWheelError("runtime changed while being read")
        if len(runtime) != metadata.st_size:
            raise NativeWheelError("runtime could not be read completely")
        return runtime


def _runtime_capabilities(path: Path) -> RuntimeCapabilities:
    environment = {
        key: value
        for key, value in os.environ.items()
        if key.upper()
        in {
            "COMSPEC",
            "HOME",
            "LANG",
            "PATHEXT",
            "SYSTEMROOT",
            "TEMP",
            "TMP",
            "TMPDIR",
            "USERPROFILE",
            "WINDIR",
        }
        or key.upper().startswith("LC_")
    }
    try:
        completed = subprocess.run(
            (str(path.resolve(strict=True)), "capabilities", "--json"),
            stdin=subprocess.DEVNULL,
            capture_output=True,
            check=False,
            timeout=5.0,
            env=environment,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise NativeWheelError("runtime capabilities probe failed") from exc
    if completed.returncode != 0 or len(completed.stdout) > _MAX_CAPABILITIES_BYTES:
        raise NativeWheelError("runtime capabilities probe failed")
    try:
        payload = json.loads(completed.stdout.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise NativeWheelError("runtime capabilities response is invalid") from exc
    if not isinstance(payload, dict):
        raise NativeWheelError("runtime capabilities response is invalid")
    protocol_version = payload.get("protocol_version")
    runtime_version = payload.get("runtime_version")
    rule_digest = payload.get("rule_digest")
    build_sha = payload.get("build_sha")
    if (
        not isinstance(protocol_version, int)
        or not isinstance(runtime_version, str)
        or not isinstance(rule_digest, str)
        or not isinstance(build_sha, str)
    ):
        raise NativeWheelError("runtime capabilities response is invalid")
    return RuntimeCapabilities(
        protocol_version=protocol_version,
        runtime_version=runtime_version,
        rule_digest=rule_digest,
        build_sha=build_sha,
    )


def _verify_runtime_provenance(
    path: Path,
    *,
    version: str,
    source_sha: str,
    rule_digest: str,
) -> bytes:
    before = _load_runtime(path)
    capabilities = _runtime_capabilities(path)
    after = _load_runtime(path)
    if not hashlib.sha256(before).digest() == hashlib.sha256(after).digest():
        raise NativeWheelError("runtime changed during capabilities verification")
    if capabilities.protocol_version != 1:
        raise NativeWheelError("runtime protocol version does not match native wheel contract")
    if capabilities.runtime_version != version:
        raise NativeWheelError("runtime package version does not match native wheel version")
    if capabilities.rule_digest != rule_digest:
        raise NativeWheelError("runtime rule digest does not match requested manifest digest")
    if capabilities.build_sha != source_sha:
        raise NativeWheelError("runtime build SHA does not match requested source SHA")
    return before


def _rewrite_wheel_metadata(raw: bytes, *, platform_tag: str) -> bytes:
    lines = raw.decode("utf-8").splitlines()
    rewritten = [
        line
        for line in lines
        if not line.startswith("Root-Is-Purelib:") and not line.startswith("Tag:")
    ]
    rewritten.extend(["Root-Is-Purelib: false", f"Tag: py3-none-{platform_tag}"])
    return ("\n".join(rewritten).rstrip("\n") + "\n").encode("utf-8")


def _record_hash(content: bytes) -> str:
    digest = hashlib.sha256(content).digest()
    encoded = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
    return f"sha256={encoded}"


def _record_content(entries: dict[str, bytes], *, record_path: str) -> bytes:
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    for name in sorted(entries):
        if name == record_path:
            continue
        content = entries[name]
        writer.writerow([name, _record_hash(content), str(len(content))])
    writer.writerow([record_path, "", ""])
    return output.getvalue().encode("utf-8")


def _zip_info(name: str, *, mode: int) -> zipfile.ZipInfo:
    info = zipfile.ZipInfo(name, date_time=_DETERMINISTIC_TIMESTAMP)
    info.compress_type = zipfile.ZIP_DEFLATED
    info.create_system = 3
    info.external_attr = (stat.S_IFREG | mode) << 16
    return info


def _prepare_output_dir(output_dir: Path) -> Path:
    output_dir.mkdir(parents=True, exist_ok=True)
    metadata = output_dir.lstat()
    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISDIR(metadata.st_mode):
        raise NativeWheelError("output directory must be a regular non-symlink directory")
    return output_dir


def _write_output_wheel_exclusive(
    output_path: Path,
    entries: dict[str, bytes],
    modes: dict[str, int],
) -> None:
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0)
    try:
        fd = os.open(output_path, flags, 0o600)
    except FileExistsError as exc:
        raise NativeWheelError(f"refusing to overwrite existing native wheel: {output_path}") from exc
    with os.fdopen(fd, "w+b") as output_file:
        with zipfile.ZipFile(
            output_file,
            "w",
            compression=zipfile.ZIP_DEFLATED,
            compresslevel=9,
        ) as archive:
            for name in sorted(entries):
                if not _safe_archive_path(name):
                    raise NativeWheelError(f"refusing unsafe output path: {name}")
                archive.writestr(_zip_info(name, mode=modes.get(name, 0o644)), entries[name])
        output_file.flush()
        os.fsync(output_file.fileno())


def build_native_wheel(
    *,
    source_wheel: Path,
    runtime: Path,
    output_dir: Path,
    version: str,
    platform_tag: str,
    target: str,
    source_sha: str,
    rule_digest: str,
) -> Path:
    """Return a new native HOL Guard wheel without changing the source wheel."""
    if not version.strip():
        raise NativeWheelError("package version is required")
    if not _PLATFORM_TAG_RE.fullmatch(platform_tag):
        raise NativeWheelError("invalid wheel platform tag")
    if not target or any(character in target for character in "\\/\x00"):
        raise NativeWheelError("invalid runtime target")
    if not _SHA40_RE.fullmatch(source_sha):
        raise NativeWheelError("source SHA must be a lowercase 40-character Git SHA")
    if not _SHA64_RE.fullmatch(rule_digest):
        raise NativeWheelError("rule digest must be a lowercase SHA-256 hex digest")

    source = _load_source_wheel(source_wheel, version=version)
    runtime_bytes = _verify_runtime_provenance(
        runtime,
        version=version,
        source_sha=source_sha,
        rule_digest=rule_digest,
    )
    runtime_name = "hol-guard-runtime.exe" if platform_tag.startswith("win") else "hol-guard-runtime"
    runtime_path = f"{_NATIVE_DIR}/{runtime_name}"

    entries = dict(source.entries)
    modes = dict(source.modes)
    entries[source.wheel_path] = _rewrite_wheel_metadata(
        entries[source.wheel_path],
        platform_tag=platform_tag,
    )
    runtime_sha256 = hashlib.sha256(runtime_bytes).hexdigest()
    manifest = {
        "schema": "hol-guard-native-runtime.v1",
        "protocol_version": 1,
        "package_version": version,
        "target": target,
        "platform_tag": platform_tag,
        "source_sha": source_sha,
        "rule_digest": rule_digest,
        "runtime_sha256": runtime_sha256,
        "runtime_size": len(runtime_bytes),
    }
    entries[runtime_path] = runtime_bytes
    entries[_RUNTIME_MANIFEST_PATH] = (
        json.dumps(manifest, sort_keys=True, separators=(",", ":")) + "\n"
    ).encode()
    modes[runtime_path] = 0o755
    modes[_RUNTIME_MANIFEST_PATH] = 0o644
    modes[source.wheel_path] = 0o644
    entries[source.record_path] = _record_content(entries, record_path=source.record_path)
    modes[source.record_path] = 0o644

    safe_output_dir = _prepare_output_dir(output_dir)
    output_path = safe_output_dir / (
        f"hol_guard-{_wheel_version_for_filename(version)}-py3-none-{platform_tag}.whl"
    )
    _write_output_wheel_exclusive(output_path, entries, modes)
    return output_path


def main() -> int:
    parser = argparse.ArgumentParser(description="Inject the native runtime into a verified hol-guard wheel")
    parser.add_argument("--wheel", type=Path, required=True)
    parser.add_argument("--runtime", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--version", required=True)
    parser.add_argument("--platform-tag", required=True)
    parser.add_argument("--target", required=True)
    parser.add_argument("--source-sha", required=True)
    parser.add_argument("--rule-digest", required=True)
    args = parser.parse_args()
    output = build_native_wheel(
        source_wheel=args.wheel,
        runtime=args.runtime,
        output_dir=args.output_dir,
        version=args.version,
        platform_tag=args.platform_tag,
        target=args.target,
        source_sha=args.source_sha,
        rule_digest=args.rule_digest,
    )
    print(output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Observe owned probe exits without releasing their process-group identity."""

from __future__ import annotations

import ctypes
import os
import signal
import sys
from dataclasses import dataclass
from functools import lru_cache
from typing import Any


@dataclass(frozen=True)
class ProbeExit:
    si_pid: int
    si_code: int
    si_status: int


class _DarwinSiginfo(ctypes.Structure):
    # Darwin's public LP64 siginfo_t from <sys/signal.h>. Python 3.12 omits
    # os.waitid on macOS, although the operating system implements WNOWAIT.
    # https://github.com/python/cpython/issues/113536
    _fields_ = [
        ("si_signo", ctypes.c_int),
        ("si_errno", ctypes.c_int),
        ("si_code", ctypes.c_int),
        ("si_pid", ctypes.c_int),
        ("si_uid", ctypes.c_uint),
        ("si_status", ctypes.c_int),
        ("si_addr", ctypes.c_void_p),
        ("si_value", ctypes.c_void_p),
        ("si_band", ctypes.c_long),
        ("reserved", ctypes.c_ulong * 7),
    ]


@lru_cache(maxsize=1)
def _darwin_waitid_function() -> Any:
    if sys.platform != "darwin" or ctypes.sizeof(ctypes.c_void_p) != 8 or ctypes.sizeof(_DarwinSiginfo) != 104:
        raise RuntimeError("qualification_interpreter_waitid_platform_unsupported")
    function = ctypes.CDLL("/usr/lib/libSystem.B.dylib", use_errno=True).waitid
    function.argtypes = [ctypes.c_int, ctypes.c_uint, ctypes.POINTER(_DarwinSiginfo), ctypes.c_int]
    function.restype = ctypes.c_int
    return function


def _darwin_waitid(pid: int) -> ProbeExit | None:
    status = _DarwinSiginfo()
    function = _darwin_waitid_function()
    if function(os.P_PID, pid, ctypes.byref(status), os.WEXITED | os.WNOHANG | os.WNOWAIT) != 0:
        error = ctypes.get_errno()
        raise OSError(error, os.strerror(error))
    if status.si_pid == 0:
        return None
    if status.si_pid != pid or status.si_signo != signal.SIGCHLD:
        raise RuntimeError("qualification_interpreter_waitid_identity_mismatch")
    return ProbeExit(status.si_pid, status.si_code, status.si_status)


def observe_probe_exit(pid: int) -> ProbeExit | None:
    """Inspect one still-owned Popen child; never poll, reap, or signal it."""
    if type(pid) is not int or not 0 < pid < 2**31:
        raise RuntimeError("qualification_interpreter_waitid_pid_invalid")
    if sys.platform == "darwin" and not hasattr(os, "waitid"):
        return _darwin_waitid(pid)
    status = os.waitid(os.P_PID, pid, os.WEXITED | os.WNOHANG | os.WNOWAIT)
    if status is None:
        return None
    if status.si_pid != pid:
        raise RuntimeError("qualification_interpreter_waitid_identity_mismatch")
    return ProbeExit(status.si_pid, status.si_code, status.si_status)

"""Fixed, boundary-specific acceptance; unmeasured program work stays separate."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any

from scripts.native_slo_qualification import paired_ratio_interval

_PRIORITY = tuple(
    f"{harness}.{event}" for harness in ("claude-code", "codex") for event in ("PreToolUse", "PostToolUse")
)


def _ceiling(reports: Sequence[Mapping[str, Any]], route: str, quantile: str, budget: float) -> bool:
    for report in reports:
        values = report.get("measurements", {}).get(route)
        if not isinstance(values, Mapping):
            return False
        interval = values.get(f"{quantile}_ci95_ms")
        upper = interval[-1] if isinstance(interval, list) and len(interval) == 2 else values.get(f"{quantile}_ms")
        if not isinstance(upper, (float, int)) or not 0 <= upper <= budget:
            return False
    return bool(reports)


def resource_comparisons(
    baseline: Sequence[Mapping[str, Any]], candidate: Sequence[Mapping[str, Any]]
) -> dict[str, Any]:
    compared: dict[str, Any] = {}
    for metric in ("cpu_ms_per_attempt", "private_bytes", "rss_bytes"):
        arms: list[list[float]] = []
        complete = True
        for reports in (baseline, candidate):
            values: list[float] = []
            for report in reports:
                resources = report.get("resources", {})
                value = (
                    resources.get(metric) if metric == "cpu_ms_per_attempt" else resources.get("peak", {}).get(metric)
                )
                metric_name = "cpu_seconds" if metric == "cpu_ms_per_attempt" else metric
                if (
                    not resources.get("metric_minimum_met", {}).get(metric_name)
                    or not isinstance(value, (int, float))
                    or value <= 0
                ):
                    complete = False
                else:
                    values.append(float(value))
                if (
                    metric == "cpu_ms_per_attempt"
                    and resources.get("short_exited_descendants_cpu_complete") is not True
                ):
                    complete = False
            arms.append(values)
        compared[metric] = {"qualified": complete}
        if complete:
            compared[metric]["comparison"] = paired_ratio_interval(*arms)
    return compared


def scoped_acceptance(
    baseline: Sequence[Mapping[str, Any]],
    candidate: Sequence[Mapping[str, Any]],
    comparison: Mapping[str, Any],
    sampling: Mapping[str, bool],
) -> dict[str, Any]:
    """Qualify implemented scopes without equating them to the entire Rust PRD.

    Product targets use per-run upper bootstrap bounds. Relative migration
    decisions use paired independent-run intervals and the unchanged PRD gains.
    A missing metric is unqualified, never inferred from another timer.
    """
    independent = sampling.get("independent_runs") is True
    scopes: dict[str, Any] = {}

    def scope(name: str, checks: Mapping[str, bool]) -> None:
        gates = {"independent_runs": independent, **checks}
        scopes[name] = {"qualified": all(gates.values()), "gates": gates}

    scope(
        "native_client_warm",
        {
            "sampling": sampling.get("NATIVE_CLIENT.claude-code.PostToolUse") is True,
            "p95_20ms": _ceiling(candidate, "NATIVE_CLIENT.claude-code.PostToolUse", "p95", 20),
        },
    )
    scope(
        "cold_native_process",
        {
            "sampling": sampling.get("NATIVE_CLIENT.cold_oneshot") is True,
            "p95_150ms": _ceiling(candidate, "NATIVE_CLIENT.cold_oneshot", "p95", 150),
        },
    )
    scope(
        "policy_readiness",
        {
            "sampling": sampling.get("NATIVE_CLIENT.policy_readiness") is True,
            "p95_400ms": _ceiling(candidate, "NATIVE_CLIENT.policy_readiness", "p95", 400),
        },
    )
    for route in _PRIORITY:
        key = "INSTALLED_LAUNCHER." + route
        scope(
            "launcher." + route,
            {
                "sampling": sampling.get(key) is True,
                "p95_50ms": _ceiling(candidate, key, "p95", 50),
                "p99_100ms": _ceiling(candidate, key, "p99", 100),
                "cold_launch_sampling": sampling.get("INSTALLED_LAUNCHER.cold." + route) is True,
                "c16_sampling": sampling.get("INSTALLED_LAUNCHER.c16." + route) is True,
                "c16_p99_200ms": _ceiling(candidate, "INSTALLED_LAUNCHER.c16." + route, "p99", 200),
                "launcher_contracts": all(
                    report.get("launcher", {}).get("contracts_passed") is True for report in candidate
                ),
                "registered_fault_contracts": all(
                    report.get("registered_launcher_contract_corpus", {}).get("implemented_scope_passed") is True
                    for report in [*baseline, *candidate]
                ),
            },
        )
    daemon_keys = [key for key in comparison if key.startswith("DAEMON_INGRESS.") and key != "DAEMON_INGRESS.recovery"]
    scope(
        "daemon_ingress_tail_evidence",
        {
            "sampling": bool(daemon_keys) and all(sampling.get(key) is True for key in daemon_keys),
            "frozen_contracts": all(
                report.get("contract_corpus", {}).get("implemented_scope_passed") is True
                for report in [*baseline, *candidate]
            ),
        },
    )
    scope("recovery_evidence", {"sampling": sampling.get("DAEMON_INGRESS.recovery") is True})
    scope(
        "reference_full_review",
        {
            "full_review": bool(baseline)
            and bool(candidate)
            and all(
                report.get("contract_corpus", {}).get("platform_scope", {}).get("reference_review_qualified") is True
                for report in [*baseline, *candidate]
            )
        },
    )
    resources = resource_comparisons(baseline, candidate)
    for metric, evidence in resources.items():
        scope("daemon_resources." + metric, {"measurement": evidence["qualified"]})
    scope("full_daemon_startup_evidence", {"sampling": sampling.get("DAEMON_PROCESS.startup") is True})
    # New delivery contracts can expose a real defect in the audited baseline.
    # Preserve that result while qualifying the candidate's observed semantic
    # scope separately. Neither side scenario contributes a latency sample.
    side_results: dict[str, Any] = {}
    for name in (
        "registered_surfaces",
        "mixed_contention",
        "priority_approval",
        "priority_input",
        "posture_transitions",
    ):
        observed: dict[str, list[bool]] = {}
        for arm_name, reports in (("baseline", baseline), ("candidate", candidate)):
            outcomes: list[bool] = []
            for report in reports:
                scenarios = report.get("additional_scenarios")
                scenario = scenarios.get(name) if isinstance(scenarios, Mapping) else None
                outcomes.append(isinstance(scenario, Mapping) and scenario.get("passed") is True)
            observed[arm_name] = outcomes
        side_results[name] = {
            "baseline_passed": bool(observed["baseline"]) and all(observed["baseline"]),
            "candidate_passed": bool(observed["candidate"]) and all(observed["candidate"]),
            "headline_timing_eligible": False,
            "coverage": "observed_scenarios_only",
        }
        scope(
            "candidate_observed_semantics." + name,
            {"candidate_contracts": side_results[name]["candidate_passed"]},
        )
    latency = [comparison.get("INSTALLED_LAUNCHER." + route, {}).get("p95", {}) for route in _PRIORITY]
    latency_no_regression = all(item.get("ci95_high", float("inf")) <= 1.05 for item in latency)
    latency_gain = any(item.get("ci95_high", float("inf")) <= 0.70 for item in latency)
    cpu_ratio = resources["cpu_ms_per_attempt"].get("comparison", {}).get("ci95_high", float("inf"))
    gain = independent and ((latency_gain and cpu_ratio <= 1.05) or (latency_no_regression and cpu_ratio <= 0.70))
    return {
        "scope": "observed_platform_implemented_hook_boundaries",
        "scopes": scopes,
        "qualified_scope_count": sum(item["qualified"] for item in scopes.values()),
        "resource_comparisons": resources,
        "additional_scenario_results": side_results,
        "migration_benefit_go": gain,
        "migration_gain_basis": "paired_ci_upper_30pct_gain_and_5pct_other_metric_limit",
        "program_qualification_complete": False,
        "remaining_program_evidence": [
            "all_platforms_combined",
            "native_inner_phase_attribution",
            "nonpriority_full_sampling_and_fault_matrix",
            "browser_approval_continuation",
            "malformed_launcher_input",
            *(
                []
                if scopes["reference_full_review"]["qualified"]
                else ["source_reference_full_content_review", "source_reference_identity_verification"]
            ),
        ],
    }

"""Bounded synthetic ingress helpers for the installed native SLO proof."""

from __future__ import annotations

import hashlib
import json
import os
import subprocess
import sys
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path

from codex_plugin_scanner.guard.daemon.hook_process_capacity import process_tree_rss_bytes
from scripts.native_slo_contract import SAFE_ROUTE_NAMES

_MAX_CASES = 2_048
_SIZE_BYTES = {"1k": 1 * 1024, "250k": 250 * 1024, "1m": 1 * 1024 * 1024, "5m": 5 * 1024 * 1024}
# The daemon reserves 250 ms of an explicit hook hint for transport and uses
# a conservative 750 ms service estimate until it has warm samples. Keep the
# synthetic ingress budget above that admission floor so the SLO measures the
# native decision rather than an intentionally expired scheduler admission.
_SLO_REMAINING_MS = 4_000
_OWNERSHIP_CONTRACT = Path(__file__).resolve().parents[1] / "docs/guard/contracts/hook-data-plane-ownership.v2.json"


@dataclass(frozen=True, slots=True)
class Observation:
    harness: str
    event: str
    size_class: str
    latency_ms: float
    route: str
    allowed: bool
    # True only when the adapter returned an explicit bounded-capacity result;
    # a generic native fail-safe must not be mistaken for accepted overload.
    overloaded: bool = False


@dataclass(frozen=True, slots=True)
class ProcessResources:
    """Current resident resources for one process tree."""

    rss_bytes: int
    threads: int
    file_descriptors: int


def _single_process_rss_bytes(pid: int) -> int:
    if os.name == "nt":
        return 0
    if sys.platform == "darwin":
        try:
            result = subprocess.run(
                ("/bin/ps", "-p", str(pid), "-o", "rss="),
                capture_output=True,
                text=True,
                check=False,
                timeout=1,
            )
            value = result.stdout.strip().split()
            return int(value[0]) * 1024 if value else 0
        except (OSError, ValueError, subprocess.TimeoutExpired):
            return 0
    try:
        for line in Path(f"/proc/{pid}/status").read_text(encoding="utf-8").splitlines():
            if line.startswith("VmRSS:"):
                value = line.split()[1]
                return int(value) * 1024
    except (OSError, ValueError, IndexError):
        return 0
    return 0


def _process_threads(pid: int) -> int:
    if os.name == "nt":
        return 0
    if sys.platform == "darwin":
        try:
            result = subprocess.run(
                ("/bin/ps", "-M", "-p", str(pid)),
                capture_output=True,
                text=True,
                check=False,
                timeout=1,
            )
            lines = result.stdout.splitlines()
            return max(0, len(lines) - 1)
        except (OSError, subprocess.TimeoutExpired):
            return 0
    try:
        for line in Path(f"/proc/{pid}/status").read_text(encoding="utf-8").splitlines():
            if line.startswith("Threads:"):
                return int(line.split()[1])
    except (OSError, ValueError, IndexError):
        return 0
    return 0


def _process_file_descriptors(pid: int) -> int:
    if os.name == "nt":
        return 0
    if sys.platform == "darwin":
        try:
            result = subprocess.run(
                ("/usr/sbin/lsof", "-p", str(pid), "-Fn"),
                capture_output=True,
                text=True,
                check=False,
                timeout=1,
            )
            return sum(line.startswith("n") for line in result.stdout.splitlines()) if result.returncode == 0 else 0
        except (OSError, subprocess.TimeoutExpired):
            return 0
    try:
        return len(list(Path(f"/proc/{pid}/fd").iterdir()))
    except OSError:
        return 0


def process_resources(pid: int | None = None) -> ProcessResources | None:
    """Measure current RSS (including descendants), threads, and descriptors."""

    resolved_pid = os.getpid() if pid is None else pid
    if resolved_pid <= 0:
        return None
    tree_rss_bytes = process_tree_rss_bytes((resolved_pid,))
    if tree_rss_bytes is None or tree_rss_bytes <= 0:
        # Linux soak evidence must account for every daemon worker.  A root
        # process reading is not an equivalent measurement, so report the
        # resource as unavailable when process-tree enumeration is missing.
        # Other supported POSIX platforms retain their existing root fallback.
        if sys.platform.startswith("linux"):
            return None
        rss_bytes = _single_process_rss_bytes(resolved_pid)
    else:
        rss_bytes = tree_rss_bytes
    threads = _process_threads(resolved_pid)
    file_descriptors = _process_file_descriptors(resolved_pid)
    if rss_bytes <= 0:
        return None
    return ProcessResources(rss_bytes, threads, file_descriptors)


def route_matrix() -> tuple[tuple[str, str], ...]:
    payload = json.loads(_OWNERSHIP_CONTRACT.read_text(encoding="utf-8"))
    routes = payload.get("harness_routes") if isinstance(payload, dict) else None
    if not isinstance(routes, dict):
        raise RuntimeError("native_installed_slo_failed: harness route contract missing")
    selected: list[tuple[str, str]] = []
    for harness, route in sorted(routes.items()):
        if not isinstance(harness, str) or not isinstance(route, dict):
            continue
        for event, key in (("PreToolUse", "pre_tool_use"), ("PostToolUse", "post_tool_use")):
            route_name = route.get(key)
            if isinstance(route_name, str) and route_name.startswith("installed_"):
                selected.append((harness, event))
    if not selected:
        raise RuntimeError("native_installed_slo_failed: installed route corpus is empty")
    return tuple(selected[:_MAX_CASES])


def payload(event: str, size_class: str = "1k") -> dict[str, object]:
    if event == "PreToolUse":
        return {
            "hook_event_name": event,
            "tool_name": "Bash",
            "tool_input": {"command": "printf guard"},
            "guard_remaining_ms": _SLO_REMAINING_MS,
        }
    target = _SIZE_BYTES[size_class]
    text = "const guard_value = 1;\n" * max(1, target // len("const guard_value = 1;\n"))
    return {
        "hook_event_name": event,
        "tool_name": "Read",
        "tool_response": [{"type": "text", "text": text}],
        "guard_remaining_ms": _SLO_REMAINING_MS,
    }


def source_payloads(workspace: Path) -> dict[str, Mapping[str, object]]:
    """Create bounded local source fixtures for the large content classes."""

    unit = "const guard_value = 1;\n"
    payloads: dict[str, Mapping[str, object]] = {}
    for size_class, target in (("250k", 250 * 1024), ("1m", 1 * 1024 * 1024), ("5m", 5 * 1024 * 1024)):
        content = (unit * ((target + len(unit) - 1) // len(unit))).encode("utf-8")[:target]
        path = workspace / f"native-slo-{size_class}.rs"
        path.write_bytes(content)
        payloads[size_class] = {
            "hook_event_name": "PostToolUse",
            "tool_name": "Read",
            "tool_input": {"file_path": str(path)},
            "guard_remaining_ms": _SLO_REMAINING_MS,
            "guard_source_ref": {
                "version": 1,
                "path": str(path),
                "output_sha256": hashlib.sha256(content).hexdigest(),
                "output_chars": len(content.decode("utf-8")),
                "tool_input_path": str(path),
            },
        }
    return payloads


def process_rss_bytes(pid: int | None = None) -> int:
    """Return current process-tree RSS in bytes, never historical max RSS."""

    resources = process_resources(pid)
    return resources.rss_bytes if resources is not None else 0


def route_counts(metrics: Mapping[str, object]) -> Counter[str]:
    raw = metrics.get("routes")
    if not isinstance(raw, Mapping):
        return Counter()
    return Counter({str(key): int(value) for key, value in raw.items() if isinstance(value, int)})


def route_delta(before: Counter[str], after: Counter[str]) -> str:
    changed = [route for route in SAFE_ROUTE_NAMES if after[route] > before[route]]
    return changed[0] if len(changed) == 1 else "native_fail_safe"


def is_allowed(event: str, response: Mapping[str, object]) -> bool:
    if response.get("decision") == "allow":
        return response.get("model_output_action", "allow_original") != "block"
    if event == "PreToolUse":
        specific = response.get("hookSpecificOutput")
        return isinstance(specific, Mapping) and specific.get("permissionDecision") == "allow"
    specific = response.get("hookSpecificOutput")
    return isinstance(specific, Mapping) and response.get("policy_action", "allow") in {"allow", "warn"}


__all__ = [
    "Observation",
    "ProcessResources",
    "is_allowed",
    "payload",
    "process_resources",
    "process_rss_bytes",
    "route_counts",
    "route_delta",
    "route_matrix",
    "source_payloads",
]

"""Bind benchmark interpreters to the exact installed wheel contents."""

from __future__ import annotations

import hashlib
import importlib.metadata
import zipfile
from collections.abc import Callable, Iterable
from contextlib import AbstractContextManager
from pathlib import Path
from typing import BinaryIO

_PREFIX = "codex_plugin_scanner/"
_MAX_FILES = 20_000
_MAX_BYTES = 256 * 1024 * 1024


def _digest(names: Iterable[str], open_file: Callable[[str], AbstractContextManager[BinaryIO]]) -> str:
    selected = sorted(
        name
        for name in names
        if name.startswith(_PREFIX) and not name.endswith(("/", ".pyc")) and "/__pycache__/" not in name
    )
    if not selected or len(selected) > _MAX_FILES or len(selected) != len(set(selected)):
        raise ValueError("artifact package inventory invalid")
    total = 0
    result = hashlib.sha256()
    for name in selected:
        if ".." in Path(name).parts:
            raise ValueError("artifact package member invalid")
        digest = hashlib.sha256()
        with open_file(name) as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                total += len(chunk)
                if total > _MAX_BYTES:
                    raise ValueError("artifact package content exceeds bound")
                digest.update(chunk)
        result.update(name.encode("utf-8") + b"\0" + digest.digest())
    return result.hexdigest()


def installed_package_digest(distribution: importlib.metadata.Distribution) -> str:
    return _digest(
        (str(entry).replace("\\", "/") for entry in distribution.files or ()),
        lambda name: Path(distribution.locate_file(name)).open("rb"),
    )


def wheel_package_digest(wheel: Path) -> str:
    with zipfile.ZipFile(wheel) as archive:
        return _digest(archive.namelist(), lambda name: archive.open(name))


def assert_installed_import_origin(distribution: importlib.metadata.Distribution) -> None:
    """Reject imports from another checkout even when wheel metadata is present."""
    import sys

    import codex_plugin_scanner

    root = Path(distribution.locate_file("codex_plugin_scanner")).resolve()
    expected = (root / "__init__.py").resolve()
    actual = Path(codex_plugin_scanner.__file__).resolve()
    if actual != expected or not actual.is_relative_to(root):
        raise RuntimeError("qualification imported code outside its installed wheel")
    for name, module in tuple(sys.modules.items()):
        if name.startswith("codex_plugin_scanner."):
            location = getattr(module, "__file__", None)
            if isinstance(location, str) and not Path(location).resolve().is_relative_to(root):
                raise RuntimeError("qualification mixed installed and checkout modules")

"""Generated production-key authority in a disposable qualification store.

The concrete bootstrap/read/lock APIs are shared by pinned baseline 2e672d2
and the candidate. This is fixture provisioning, not interactive enrollment.
"""

from __future__ import annotations

from codex_plugin_scanner.guard.runtime.command_extensions import BUILT_IN_COMMAND_EXTENSION_REGISTRY
from codex_plugin_scanner.guard.runtime.extension_control_authority import (
    AuthorityHealth,
    ExtensionControlAuthorityView,
)
from codex_plugin_scanner.guard.store import GuardStore
from codex_plugin_scanner.guard.store_base import EncryptedFileSecretStore


def verify_empty_command_authority(store: GuardStore) -> dict[str, str]:
    view = store.read_extension_control_authority(catalog_digest=BUILT_IN_COMMAND_EXTENSION_REGISTRY.catalog_digest)
    return _verified_empty_view(view)


def _verified_empty_view(view: ExtensionControlAuthorityView) -> dict[str, str]:
    if view.health is not AuthorityHealth.PROTECTED or view.revision != 0 or view.layers:
        raise RuntimeError("qualification command authority is not verified empty protected state")
    return {
        "provisioning": "isolated_ci_generated_key_empty_authority",
        "enrollment_flow": "not_exercised",
        "verified_health": view.health.value,
    }


def prepare_empty_command_authority(store: GuardStore) -> dict[str, str]:
    store._extension_control_authority_secret_store = EncryptedFileSecretStore(store.guard_home)
    catalog = BUILT_IN_COMMAND_EXTENSION_REGISTRY.catalog_digest
    with store._extension_control_authority_lock():
        # The pinned baseline lock is not reentrant. Both releases expose the
        # concrete locked reader, so keep the entire bootstrap interval under
        # one real lease without calling the public lock-taking reader again.
        current = store._read_extension_control_authority_locked(catalog)
        if current.health is not AuthorityHealth.UNENROLLED:
            raise RuntimeError("qualification command authority must be freshly unenrolled")
        store._bootstrap_extension_control_authority(catalog, key=None)
        return _verified_empty_view(store._read_extension_control_authority_locked(catalog))

"""Separate fixed request identity from untimed platform-specific source evidence."""

from __future__ import annotations

import hashlib
import json
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import cast

_SCOPE = "fixed_requests_and_oracle_implementation_v2"
_BASELINE = "2e672d2d950c6ec471005ddba46e49bba16dc23b"
_FIXED_MATRIX_FIELDS = (
    "required_platforms",
    "observed_platform",
    "required_sizes",
    "required_cases",
    "concurrency",
    "daemon_routes",
    "launcher_routes",
)
_PROFILES = frozenset({"unix_source_v1", "windows_refusal_v1", "windows_handles_v1"})


def _object(value: object) -> Mapping[str, object]:
    if not isinstance(value, Mapping) or any(type(key) is not str for key in value):
        raise RuntimeError("paired corpus identity object is invalid")
    return cast(Mapping[str, object], value)


def _digest(value: object) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def _is_digest(value: object) -> bool:
    return type(value) is str and len(value) == 64 and all(char in "0123456789abcdef" for char in value)


def _profile(matrix: Mapping[str, object]) -> str:
    supported = matrix.get("reference_review_supported")
    if type(supported) is not bool:
        raise RuntimeError("source oracle support was not declared")
    platform = matrix.get("observed_platform")
    if platform == "windows-x64":
        return "windows_handles_v1" if supported else "windows_refusal_v1"
    if platform in {"linux-x64", "macos-x64", "macos-arm64"} and supported:
        return "unix_source_v1"
    raise RuntimeError("source oracle platform is unsupported")


def corpus_identity(definition: Mapping[str, object]) -> dict[str, str]:
    """Keep both oracles reviewable while comparing the same timed requests.

    The definition still binds the manifest, oracle implementation, validated
    case IDs and every fixed timing payload. Only observed coverage/scope fields
    leave its matrix projection; they remain in the separate evidence digest.
    Source references occur in untimed contract preflights, not these timers.
    """
    matrix = _object(definition.get("matrix"))
    profile = _profile(matrix)
    shared = {
        **definition,
        "identity_scope": _SCOPE,
        "identity_implementation_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "matrix": {key: matrix[key] for key in _FIXED_MATRIX_FIELDS},
    }
    evidence = {**definition, "source_reference_oracle_profile": profile}
    return {
        "corpus_digest": _digest(shared),
        "corpus_definition_scope": _SCOPE,
        "contract_evidence_digest": _digest(evidence),
        "source_reference_oracle_profile": profile,
    }


def paired_corpus_identity(
    baseline: Sequence[Mapping[str, object]], candidate: Sequence[Mapping[str, object]]
) -> dict[str, object]:
    """Reject changed requests, unstable arm evidence or undeclared oracle differences."""
    combined = [*baseline, *candidate]
    if not baseline or not candidate:
        raise RuntimeError("paired corpus identity requires both arms")
    digests = {report.get("corpus_digest") for report in combined}
    if len(digests) != 1 or not all(type(value) is str and value for value in digests):
        raise RuntimeError("paired artifacts used different corpus definitions")
    scopes = {report.get("corpus_definition_scope") for report in combined}
    if scopes == {None}:
        # Historical reports used the full-matrix digest. Preserve their exact
        # equality requirement; they cannot opt into the new oracle split.
        if any(
            "source_reference_oracle_profile" in report or "contract_evidence_digest" in report for report in combined
        ):
            raise RuntimeError("new corpus evidence omitted its identity scope")
        return {"corpus_definition_scope": "legacy_full_matrix_v1"}
    if scopes != {_SCOPE}:
        raise RuntimeError("paired corpus definition scopes differ")
    if not all(_is_digest(value) for value in digests):
        raise RuntimeError("paired corpus request digest is invalid")
    profiles: dict[str, str] = {}
    evidence_digests: dict[str, str] = {}
    source_results: dict[str, bool] = {}
    for arm, reports in (("baseline", baseline), ("candidate", candidate)):
        observed = {report.get("source_reference_oracle_profile") for report in reports}
        evidence = {report.get("contract_evidence_digest") for report in reports}
        if len(observed) != 1 or not all(type(value) is str and value in _PROFILES for value in observed):
            raise RuntimeError("source oracle profile changed within a paired arm")
        if len(evidence) != 1 or not all(_is_digest(value) for value in evidence):
            raise RuntimeError("contract evidence changed within a paired arm")
        profiles[arm] = cast(str, next(iter(observed)))
        evidence_digests[arm] = cast(str, next(iter(evidence)))
        source_results[arm] = all(
            _object(_object(report.get("contract_corpus")).get("platform_scope")).get(
                "reference_review_qualified"
            )
            is True
            for report in reports
        )
    if profiles["baseline"] == profiles["candidate"]:
        if evidence_digests["baseline"] != evidence_digests["candidate"]:
            raise RuntimeError("paired contract evidence differs without a source oracle transition")
    else:
        if profiles != {"baseline": "windows_refusal_v1", "candidate": "windows_handles_v1"}:
            raise RuntimeError("paired source oracle profiles are not a supported comparison")
        for report in baseline:
            scope = _object(_object(report.get("contract_corpus")).get("platform_scope"))
            if (
                _object(report.get("runtime")).get("build_sha") != _BASELINE
                or scope.get("reference_review_supported") is not False
                or scope.get("reference_review_qualified") is not False
                or scope.get("platform_denial_contract_passed") is not True
            ):
                raise RuntimeError("original Windows source refusal was not proven")
        if not source_results["candidate"]:
            raise RuntimeError("candidate Windows full source contract was not proven")
    return {
        "corpus_definition_scope": _SCOPE,
        "source_reference_oracle_profiles": profiles,
        "contract_evidence_digests": evidence_digests,
        "source_reference_feature_evidence": {
            "baseline_full_review": source_results["baseline"],
            "candidate_full_review": source_results["candidate"],
            "headline_timing_eligible": False,
            "source_performance_comparison_available": False,
        },
    }

"""Observe existing native-edge return values inside a private fixture.

The wrappers call each original operation exactly once. They never inspect the
runtime again, decode a response again, refresh health, retry, or change a
deadline. Only bounded facts about values already computed by production cross
the fixture control pipe; request bytes and response bodies are never retained.
"""

from __future__ import annotations

import hashlib
import threading
from collections.abc import Callable, Iterator
from contextlib import ExitStack, contextmanager
from contextvars import ContextVar
from typing import Any
from unittest.mock import patch

from codex_plugin_scanner.guard.native_approval_errors import (
    NATIVE_APPROVAL_ERROR_CODES,
    NATIVE_RESIDENT_LIFECYCLE_ERROR_CODES,
)

_TRACE: ContextVar[dict[str, object] | None] = ContextVar("qualification_native_edge_stages", default=None)
_LOCK = threading.RLock()
_users = 0
_patches: ExitStack | None = None
_CODES = (
    NATIVE_APPROVAL_ERROR_CODES
    | NATIVE_RESIDENT_LIFECYCLE_ERROR_CODES
    | {
        "native_hook_edge_unavailable",
        "native_hook_edge_invalid_response",
        "ready",
        "native_ready",
    }
)
_MAX_CALLS = 4


def _code(value: object) -> dict[str, object]:
    if value is None:
        return {"state": "absent"}
    if type(value) is not str:
        return {"state": "invalid_type"}
    known = len(value) <= 128 and value in _CODES
    result: dict[str, object] = {
        "state": "known" if known else "unlisted",
        "digest": hashlib.sha256(value[:128].encode("utf-8", errors="replace")).hexdigest(),
        "digest_complete": len(value) <= 128,
    }
    if known:
        result["value"] = value
    return result


def _status(value: Any, _args: tuple[Any, ...], _kwargs: dict[str, Any]) -> dict[str, object]:
    capabilities = value.capabilities
    features = capabilities.features if capabilities is not None else ()
    return {
        "mode": value.mode if value.mode in {"auto", "force", "off", "shadow"} else "unclassified",
        "available": value.available is True,
        "compatible": value.compatible is True,
        "identity_present": value.identity is not None,
        "capabilities_present": capabilities is not None,
        "hook_envelope_feature": "hook-envelope-v2" in features,
        "resident_client_feature": "native-resident-client-v1" in features,
        "pre_tool_feature": "pre-tool-generic-authority-v1" in features,
        **{"reason_" + key: item for key, item in _code(value.reason).items()},
    }


def _bytes(value: object, _args: tuple[Any, ...], _kwargs: dict[str, Any]) -> dict[str, object]:
    return {
        "returned_bytes": type(value) is bytes,
        "returned_none": value is None,
        "byte_count": min(len(value), 6 * 1024 * 1024 + 1) if type(value) is bytes else None,
    }


def _decode(value: object, args: tuple[Any, ...], _kwargs: dict[str, Any]) -> dict[str, object]:
    payload = args[0] if args else None
    result: dict[str, object] = {"accepted": type(value) is dict, "input_object": type(payload) is dict}
    if type(payload) is dict:
        schema = payload.get("schema")
        result["edge_schema"] = schema == "guard-hook-edge-result.v2"
        result["error_present"] = "error" in payload
        result["receipt_present"] = type(payload.get("receipt")) is dict
        result.update(("error_" + key, item) for key, item in _code(payload.get("error")).items())
    return result


def _receipt(value: object, _args: tuple[Any, ...], _kwargs: dict[str, Any]) -> dict[str, object]:
    return {"matched": value is True}


def _failure(_value: object, _args: tuple[Any, ...], kwargs: dict[str, Any]) -> dict[str, object]:
    return {"reason_" + key: item for key, item in _code(kwargs.get("reason")).items()}


def _wrapper(
    original: Callable[..., Any], name: str, summarize: Callable[..., dict[str, object]]
) -> Callable[..., Any]:
    def observed(*args: Any, **kwargs: Any) -> Any:
        # Production exceptions propagate unchanged. There is no diagnostic
        # operation before the actual call or on its exception path.
        value = original(*args, **kwargs)
        trace = _TRACE.get()
        if trace is not None:
            try:
                previous = trace.get(name)
                calls = previous.get("calls", 0) if type(previous) is dict else 0
                if type(calls) is int and calls < _MAX_CALLS:
                    trace[name] = {"calls": calls + 1, **summarize(value, args, kwargs)}
                else:
                    trace["stage_count_limit_reached"] = True
            except Exception:
                trace["collection_failed"] = True
        return value

    return observed


@contextmanager
def capture_native_edge_stages() -> Iterator[None]:
    """Install once per fixture lifetime; concurrent workers keep own traces."""
    global _users, _patches
    from codex_plugin_scanner.guard import native_hook_edge

    with _LOCK:
        if _users == 0:
            stack = ExitStack()
            try:
                for name, label, summarize in (
                    ("native_runtime_status", "runtime_status", _status),
                    ("_encode_hook_envelope", "envelope", _bytes),
                    ("native_resident_client_request", "client", _bytes),
                    ("_decode_edge", "decoder", _decode),
                    ("receipt_matches_edge", "receipt", _receipt),
                    ("native_record_resident_failure", "resident_failure", _failure),
                ):
                    original = getattr(native_hook_edge, name)
                    stack.enter_context(patch.object(native_hook_edge, name, _wrapper(original, label, summarize)))
            except BaseException:
                stack.close()
                raise
            _patches = stack
        _users += 1
    try:
        yield
    finally:
        with _LOCK:
            _users -= 1
            if _users == 0:
                assert _patches is not None
                _patches.close()
                _patches = None


@contextmanager
def collect_native_edge_stages() -> Iterator[dict[str, object]]:
    """Associate existing stage returns with this worker operation only."""
    trace: dict[str, object] = {"wrappers_installed": _users > 0}
    token = _TRACE.set(trace)
    try:
        yield trace
    finally:
        _TRACE.reset(token)

"""Bounded failure identifiers for CI, without child stderr or response bodies."""

from __future__ import annotations

import hashlib
import os
import re
import stat
import sys
from collections.abc import Mapping
from pathlib import Path

from scripts.native_slo_contract import assert_privacy_safe

_CODEX_FILE_ROLES = frozenset(
    {
        "interpreter",
        "config_target",
        "bridge",
        "bridge_resume",
        "bridge_runtime",
        "fallback_entrypoint",
        "daemon_entrypoint",
        "daemon_manager",
        "launch_runtime",
        "runtime_trust",
        "windows_job",
    }
)
_CODEX_FILE_FAILURE_CODES = frozenset(
    f"codex_hook_{role}_{suffix}"
    for role in _CODEX_FILE_ROLES
    for suffix in ("missing", "not_regular", "owner_untrusted", "permissions_unsafe", "not_executable")
)
_CONFIG_CAUSE_TYPES = (
    OSError,
    PermissionError,
    FileNotFoundError,
    NotADirectoryError,
    IsADirectoryError,
    FileExistsError,
    BlockingIOError,
    TimeoutError,
    InterruptedError,
    BrokenPipeError,
    ConnectionError,
    ConnectionAbortedError,
    ConnectionRefusedError,
    ConnectionResetError,
    RuntimeError,
    ValueError,
    TypeError,
    AttributeError,
    ImportError,
    ModuleNotFoundError,
    NotImplementedError,
)


def _interpreter_failure_metadata() -> dict[str, object]:
    """Read the current invocation after rejection; never repair or re-attest it."""
    try:
        invocation = Path(sys.executable).absolute()
        invocation_metadata = invocation.lstat()
        metadata = invocation.resolve(strict=True).lstat()
    except (OSError, RuntimeError):
        return {"interpreter_metadata_available": False}
    uid = os.getuid() if hasattr(os, "getuid") else None
    gid = os.getgid() if hasattr(os, "getgid") else None
    return {
        "interpreter_metadata_available": True,
        "interpreter_metadata_phase": "after_integrity_rejection",
        "interpreter_invocation_symlink": stat.S_ISLNK(invocation_metadata.st_mode),
        "interpreter_regular": stat.S_ISREG(metadata.st_mode),
        "interpreter_mode": stat.S_IMODE(metadata.st_mode),
        "interpreter_owner_current": uid is not None and metadata.st_uid == uid,
        "interpreter_owner_root": metadata.st_uid == 0,
        "interpreter_group_current": gid is not None and metadata.st_gid == gid,
        "interpreter_group_root": metadata.st_gid == 0,
        "interpreter_group_writable": bool(metadata.st_mode & stat.S_IWGRP),
        "interpreter_world_writable": bool(metadata.st_mode & stat.S_IWOTH),
    }


class FixtureFailureError(RuntimeError):
    """Keep bounded child evidence intact across the private control pipe."""

    def __init__(self, detail: Mapping[str, object], *, message: str | None = None) -> None:
        self.detail = assert_privacy_safe(dict(detail))
        # A local wrapper may preserve an existing exception's caller-facing
        # message. Exporters use only the sanitized detail, never this text.
        super().__init__(message or "qualification_fixture." + str(self.detail.get("reason", "unclassified_failure")))


def _location(error: Exception) -> dict[str, object]:
    """Record a shipped code location, never exception text or frame locals."""
    result: dict[str, object] = {}
    traceback = error.__traceback__
    while traceback is not None:
        frame = traceback.tb_frame
        module = str(frame.f_globals.get("__name__", ""))
        if module.startswith(("scripts.", "codex_plugin_scanner.")) or (
            module == "__main__" and Path(frame.f_code.co_filename).name == "native_slo_daemon_fixture.py"
        ):
            unit = Path(frame.f_code.co_filename).stem
            routine = frame.f_code.co_name
            identifier = (unit + "." + routine).replace("secret", "sensitive").replace("token", "credential")
            if re.fullmatch(r"[A-Za-z0-9_.]{1,96}", identifier):
                result = {"origin": identifier, "line": traceback.tb_lineno}
        traceback = traceback.tb_next
    if isinstance(error, OSError) and isinstance(error.errno, int):
        result["errno"] = error.errno
    return result


def _configuration_failure_metadata(error: Exception) -> dict[str, object]:
    """Retain explicit bounded causes after rejection, without reading files or error text."""
    from codex_plugin_scanner.guard.config_source_io import GuardConfigSourceError

    if type(error) is not GuardConfigSourceError:
        return {}
    result: dict[str, object] = {"config_diagnostic_available": True, "config_cause_count": 0}
    seen = {id(error)}
    cause = error.__cause__
    for index in range(1, 4):
        if cause is None:
            break
        if id(cause) in seen:
            result["config_cause_cycle"] = True
            break
        seen.add(id(cause))
        prefix = f"config_cause_{index}_"
        cause_type = type(cause)
        result["config_cause_count"] = index
        if not any(cause_type is allowed for allowed in _CONFIG_CAUSE_TYPES):
            result[prefix + "category"] = "unclassified"
            result["config_cause_unavailable"] = True
            break
        result[prefix + "category"] = cause_type.__name__
        if isinstance(cause, Exception):
            for name, value in _location(cause).items():
                if name != "errno" or (type(value) is int and 0 <= value <= 0xFFFFFFFF):
                    result[prefix + name] = value
        if isinstance(cause, OSError):
            winerror = getattr(cause, "winerror", None)
            if type(winerror) is int and 0 <= winerror <= 0xFFFFFFFF:
                result[prefix + "winerror"] = winerror
        cause = cause.__cause__
    else:
        if cause is not None:
            result["config_cause_truncated"] = True
    return result


def failure_evidence(error: Exception) -> dict[str, object]:
    if isinstance(error, FixtureFailureError):
        return {**error.detail, "reason": "qualification_fixture." + str(error.detail["reason"])[:64]}
    message = str(error)
    evidence: dict[str, object] = {
        "schema": "hol-guard.native-qualification-failure.v1",
        "category": type(error).__name__,
        "reason": "unclassified_failure",
        "diagnostic_digest": hashlib.sha256(message.encode("utf-8", errors="replace")).hexdigest(),
        **_location(error),
    }
    try:
        evidence.update(_configuration_failure_metadata(error))
    except Exception:
        # Optional failure evidence must not replace the original failure.
        evidence["config_diagnostic_available"] = False
    from codex_plugin_scanner.guard.codex_hook_file_integrity import CodexHookIntegrityError

    if isinstance(error, CodexHookIntegrityError) and error.reason in _CODEX_FILE_FAILURE_CODES:
        evidence["reason"] = error.reason
        if error.reason == "codex_hook_interpreter_permissions_unsafe":
            evidence.update(_interpreter_failure_metadata())
    if message.startswith(("native_qualification_mismatch:", "native_qualification_setup_unproven:")):
        pieces = message.split(":", 2)
        if (
            len(pieces) == 3
            and re.fullmatch(r"[A-Za-z0-9_./-]{1,96}", pieces[1])
            and re.fullmatch(r"[A-Za-z0-9_.:-]{1,96}", pieces[2])
        ):
            evidence.update(reason=pieces[0], case=pieces[1].replace("/", "."), field=pieces[2])
    elif message.startswith(
        (
            "qualification",
            "priority_launcher_",
            "installed_ollama_",
            "native_installed_slo_failed:",
            "daemon fixture",
            "expiry fixture",
            "resident did not explicitly reject",
        )
    ) and re.fullmatch(r"[A-Za-z0-9 _:.=-]{1,96}", message):
        evidence["reason"] = message.replace(" ", "_").replace("secret", "sensitive")
    return assert_privacy_safe(evidence)

"""Frozen malformed stdin contracts through all four installed priority argv.

Use an otherwise idle DaemonFixture(runtime, setup="normal"). Unknown empty
inputs reach native review; a real controlled block releases browser waiters.
No availability continuation or launcher-only rejection counts as native allow.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import time
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import cast

from codex_plugin_scanner.guard.codex_hook_launch_runtime import run_isolated_hook_process
from scripts.native_probe_receipts import wait_for_route_corpus
from scripts.native_slo_adapter import route_counts
from scripts.native_slo_contract import assert_privacy_safe, clear_proof_environment
from scripts.native_slo_daemon_fixture import DaemonFixture, witnessed_route
from scripts.native_slo_priority_launchers import (
    LauncherSession,
    RegisteredLauncher,
    install_priority_launchers,
    registered_launcher,
)
from scripts.native_slo_registered_surfaces_evidence import SurfaceAttempt, SurfaceEvidence

INPUT_LIMIT = 1_000_000
_PROCESS_SECONDS = 10.0
_OUTPUT_LIMIT = 2 * 1024 * 1024
_KINDS = ("invalid_ascii_json", "nonobject_json", "empty", "oversize")
_ROUTES = frozenset((h, e) for h in ("codex", "claude-code") for e in ("PreToolUse", "PostToolUse"))
_UNKNOWN_REASON = "HOL Guard requires review because this PreToolUse action is not yet supported for automatic allow."
_SIZE_REASON = "HOL Guard blocked this action because hook input exceeded the safe size limit."
_CODEX_UNAVAILABLE_REASON = (
    "HOL Guard could not authenticate the local daemon. Run `hol-guard daemon repair`, then retry."
)
_CLAUDE_INVALID_REASON = (
    'HOL Guard could not reach the local daemon (daemon returned HTTP 400: {"error": "invalid_request_body"}; '
    "fallback exited 2) and continued this action without native review."
)


@dataclass(frozen=True, slots=True)
class InputCase:
    harness: str
    registration_event: str
    kind: str
    stdin: str

    @property
    def case_id(self) -> str:
        return f"input/{self.harness}/{self.registration_event}/{self.kind}"

    @property
    def requires_review(self) -> bool:
        return self.kind in {"empty", "nonobject_json"}

    @property
    def expected_route(self) -> str:
        return "native_resident" if self.requires_review else "engine_bypassed"

    @property
    def delivery(self) -> str:
        if self.requires_review:
            return "review_ask" if self.harness == "claude-code" else "review_deny"
        return "launcher_limit_block" if self.kind == "oversize" else "availability_continuation"


def input_cases(launcher: RegisteredLauncher) -> tuple[InputCase, ...]:
    """Inputs are fixed independently of the production parser/renderers."""
    if (launcher.harness, launcher.event) not in _ROUTES:
        raise ValueError("priority_launcher_input_route_unsupported")
    prefix = '{"hook_event_name":"' + launcher.event + '","tool_name":'
    raw = {
        "invalid_ascii_json": prefix,
        "nonobject_json": "[]",
        "empty": "",
        # Truncate inside the padding. Claude recovers the event from its prefix;
        # Codex's pre-parse size branch always emits a PreToolUse denial.
        "oversize": prefix + '"' + "x" * (INPUT_LIMIT - len(prefix)),
    }
    return tuple(InputCase(launcher.harness, launcher.event, kind, raw[kind]) for kind in _KINDS)


def _exact(actual: Mapping[str, object], wanted: Mapping[str, object]) -> None:
    # JSON equality is type strict for booleans/numbers, unlike Python dict ==.
    if json.dumps(actual, sort_keys=True, allow_nan=False) != json.dumps(wanted, sort_keys=True, allow_nan=False):
        raise RuntimeError("priority_launcher_input_stdout_contract")


def _permission(decision: str, reason: str, *, continuation: bool = False) -> dict[str, object]:
    result: dict[str, object] = {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decision,
            "permissionDecisionReason": reason,
        }
    }
    if continuation:
        result["continue"] = True
    return result


def _review_stdout(case: InputCase, response: Mapping[str, object], approval: Mapping[str, object], port: int) -> None:
    request_id = approval.get("request_id")
    if not isinstance(request_id, str) or re.fullmatch(r"[a-f0-9]{32}", request_id) is None:
        raise RuntimeError("priority_launcher_input_review_identity")
    url = f"http://127.0.0.1:{port}/requests/{request_id}"
    specific = response.get("hookSpecificOutput")
    reason = specific.get("permissionDecisionReason") if isinstance(specific, Mapping) else None
    prefix = _UNKNOWN_REASON + " Open HOL Guard to approve or keep this blocked: "
    pattern = re.escape(prefix + url) + r"(?:#guard-token=[A-Za-z0-9_~%+.\-]+)?\."
    if not isinstance(reason, str) or re.fullmatch(pattern, reason) is None:
        raise RuntimeError("priority_launcher_input_review_reason")
    expected = _permission("ask" if case.harness == "claude-code" else "deny", reason)
    if case.harness == "claude-code":
        expected.update(
            policy_action="review",
            reason_code="native_pre_tool_unknown_review",
            reason=reason,
            approval_url=url,
            approval_request_id=request_id,
            primary_approval_request_id=request_id,
            primary_approval_url=url,
            guardApprovalRequestId=request_id,
            guardApprovalUrl=url,
            approval_requests=[{"request_id": request_id, "approval_url": url}],
            prompted=True,
            approval_center_url=f"http://127.0.0.1:{port}",
        )
    _exact(response, expected)


def validate_input_delivery(
    case: InputCase,
    response: Mapping[str, object],
    *,
    approval: Mapping[str, object] | None = None,
    port: int = 0,
) -> None:
    """Freeze complete JSON shape/content; only exact local review IDs vary."""
    if case.requires_review:
        if approval is None or type(port) is not int or not 1 <= port <= 65535:
            raise RuntimeError("priority_launcher_input_review_evidence_missing")
        _review_stdout(case, response, approval, port)
    elif case.kind == "oversize":
        if case.harness == "codex":
            expected = _permission("deny", _CODEX_UNAVAILABLE_REASON)
        elif case.registration_event == "PostToolUse":
            expected = {
                "decision": "block",
                "reason": _SIZE_REASON,
                "hookSpecificOutput": {"hookEventName": "PostToolUse"},
            }
        else:
            expected = {**_permission("deny", _SIZE_REASON), "systemMessage": _SIZE_REASON}
        _exact(response, expected)
    elif case.kind == "invalid_ascii_json":
        reason = _CLAUDE_INVALID_REASON if case.harness == "claude-code" else _CODEX_UNAVAILABLE_REASON
        expected = (
            {}
            if case.harness == "claude-code" and case.registration_event == "PostToolUse"
            else _permission("allow", reason, continuation=True)
        )
        _exact(response, expected)
    else:
        raise ValueError("priority_launcher_input_case_unsupported")


def _block_resolution(session: DaemonFixture, operation_id: str) -> Mapping[str, object]:
    deadline = time.monotonic() + 1.0
    while True:
        result = session.control("launcher_approval_result", operation_id=operation_id)
        if result.get("state") != "waiting":
            break
        if time.monotonic() >= deadline:
            raise TimeoutError("priority_launcher_input_resolution_deadline")
        time.sleep(0.01)
    if (
        result.get("state") != "resolved"
        or result.get("resolution") != "block"
        or result.get("approval_durable") is not True
        or result.get("authority") != "ordinary_local_review"
        or result.get("matching") != "exact_identity_and_new_row"
    ):
        raise RuntimeError("priority_launcher_input_resolution_unproven")
    # We require a real resolved block, not an allow-consumption or successful
    # suspended-resume claim. Legacy and candidate continuation capabilities differ.
    return result


def _validate_witness(case: InputCase, evidence: Mapping[str, object], route: str) -> None:
    setup = evidence.get("setup")
    if (
        not isinstance(setup, Mapping)
        or any(
            setup.get(field) is not True
            for field in ("isolated_store", "effective_policy_allow", "policy_ack_current", "python_oracle_disabled")
        )
        or setup.get("fault_scope") != "none"
    ):
        raise RuntimeError("priority_launcher_input_setup_unproven")
    if route != case.expected_route:
        raise RuntimeError("priority_launcher_input_route_mismatch")
    native = evidence.get("native_result")
    if not case.requires_review:
        if native is not None:
            raise RuntimeError("priority_launcher_input_unexpected_native_work")
        return
    wanted = {
        "authority": "rust",
        "decision": "deny",
        "policy_action": "review",
        "minimum_action": "review",
        "reason_code": "native_pre_tool_unknown_review",
        "reason": _UNKNOWN_REASON,
        "explicitly_benign": False,
    }
    if not isinstance(native, Mapping) or any(
        type(native.get(k)) is not type(v) or native.get(k) != v for k, v in wanted.items()
    ):
        raise RuntimeError("priority_launcher_input_native_review_unproven")
    action = native.get("action")
    if not isinstance(action, Mapping) or any(
        action.get(k) != v
        for k, v in {"harness": case.harness, "event": "PreToolUse", "action_type": "unknown"}.items()
    ):
        raise RuntimeError("priority_launcher_input_native_action_mismatch")


def _run_case(
    session: DaemonFixture, launcher: RegisteredLauncher, case: InputCase, attempt: SurfaceAttempt
) -> dict[str, object]:
    attempt.stage = "registration"
    if registered_launcher(launcher.config_path, launcher.harness, launcher.event) != launcher:
        raise RuntimeError("priority_launcher_input_registration_changed")
    environment = dict(os.environ)
    clear_proof_environment(environment)
    configured = dict(launcher.environment)
    if clear_proof_environment(configured):
        raise RuntimeError("priority_launcher_input_registration_override")
    environment.update(configured)
    environment["HOME"] = environment["USERPROFILE"] = str(session.root)
    if launcher.harness == "codex":
        environment["CODEX_HOME"] = str(session.root / ".codex")
    attempt.stage = "setup"
    session.control("case_before")
    metrics = session.daemon._server.hook_worker.metrics
    before = route_counts(metrics.snapshot())
    operation_id: str | None = None
    if case.requires_review:
        begun = session.control(
            "launcher_approval_begin", harness=case.harness, payload={}, resolution="block", timeout_seconds=8
        )
        begun_id = begun.get("operation_id")
        if begun.get("state") != "waiting" or not isinstance(begun_id, str):
            raise RuntimeError("priority_launcher_input_resolution_setup")
        operation_id = begun_id
    attempt.stage = "process"
    started = time.perf_counter()
    result = run_isolated_hook_process(
        launcher.argv,
        input_text=case.stdin,
        cwd=session.workspace,
        environment=environment,
        timeout_seconds=_PROCESS_SECONDS,
        output_limit=_OUTPUT_LIMIT,
    )
    elapsed_ms = (time.perf_counter() - started) * 1000
    attempt.attempted_exit = result.returncode
    if result.returncode != 0 or result.timed_out or result.containment_failed or result.output_limit_exceeded:
        raise RuntimeError("priority_launcher_input_process_contract")
    attempt.stage = "readback_after"
    if registered_launcher(launcher.config_path, launcher.harness, launcher.event) != launcher:
        raise RuntimeError("priority_launcher_input_registration_changed")
    attempt.stage = "route"
    snapshot = (
        wait_for_route_corpus(metrics, expected=sum(before.values()) + 1)
        if case.requires_review
        else metrics.snapshot()
    )
    after = route_counts(snapshot)
    route = witnessed_route(before, after)
    attempt.route = route
    attempt.stage = "witness"
    evidence = session.control("case_result")
    try:
        _validate_witness(case, evidence, route)
    except Exception as error:
        from scripts.native_slo_surface_failure import enrich_surface_failure

        enriched = enrich_surface_failure(
            error,
            case_id=case.case_id,
            registration_digest=launcher.registration_sha256,
            stage=attempt.stage,
            expected_route=case.expected_route,
            observed_route=route,
            routes_before=before,
            routes_after=after,
            evidence=evidence,
        )
        if enriched is error:
            raise
        raise enriched from error
    approval = _block_resolution(session, operation_id) if operation_id is not None else None
    attempt.stage = "delivery"
    try:
        response: object = json.loads(result.stdout)
    except (ValueError, UnicodeDecodeError) as error:
        raise RuntimeError("priority_launcher_input_stdout_invalid_json") from error
    if not isinstance(response, Mapping):
        raise RuntimeError("priority_launcher_input_stdout_invalid_object")
    validate_input_delivery(case, cast(Mapping[str, object], response), approval=approval, port=session.daemon.port)
    attempt.stage = "complete"
    return {
        "harness": case.harness,
        "registration_event": case.registration_event,
        "case": case.kind,
        "route": route,
        "delivery": case.delivery,
        "elapsed_ms": elapsed_ms,
        "input_bytes": len(case.stdin.encode("utf-8")),
        "controlled_block": approval is not None,
    }


def run_registered_input_corpus(session: DaemonFixture, *, evidence_file: Path) -> dict[str, object]:
    """Run exactly 16 source-derived contracts; first failure retains evidence."""
    observations: list[dict[str, object]] = []
    with SurfaceEvidence(evidence_file) as journal:
        launchers = install_priority_launchers(cast(LauncherSession, cast(object, session)))
        if len(launchers) != 4 or {(item.harness, item.event) for item in launchers} != _ROUTES:
            raise RuntimeError("priority_launcher_input_registration_incomplete")
        for launcher in launchers:
            for case in input_cases(launcher):
                journal.offer(case.case_id, launcher.registration_sha256)
                attempt = SurfaceAttempt()
                try:
                    observation = _run_case(session, launcher, case, attempt)
                except BaseException:
                    journal.finish("failed", attempt)
                    raise
                journal.finish("completed", attempt)
                observations.append(observation)
    if len(observations) != 16:
        raise RuntimeError("priority_launcher_input_incomplete")
    return assert_privacy_safe(
        {
            "schema": "hol-guard.registered-launcher-input.v1",
            "boundary": "INSTALLED_LAUNCHER",
            "validated_cases": len(observations),
            "configuration": "registered_argv_and_env",
            "case_digest": hashlib.sha256(
                json.dumps([(o["harness"], o["registration_event"], o["case"]) for o in observations]).encode()
            ).hexdigest(),
            "coverage": {
                key: dict(Counter(str(row[key]) for row in observations))
                for key in ("harness", "registration_event", "case", "route", "delivery")
            },
            "observations": observations,
            "stdout_and_exit_checked": True,
            "native_and_delivered_checked_independently": True,
            "implemented_scope_passed": True,
            "qualification_complete": False,
            "latency_claim": "semantic_preflight_no_tail_claim",
            "native_allow_count": 0,
            "limits": {
                "stdin_bytes": INPUT_LIMIT + 1,
                "stdout_bytes": _OUTPUT_LIMIT,
                "process_seconds": _PROCESS_SECONDS,
            },
            "remaining": ["invalid_utf8_raw_bytes", "all_platform_execution", "native_v3_v4_approval_api"],
        }
    )

"""Witness actual local approval resolution and Codex live-hook completion.

The private fixture observes the production completion function; it never
substitutes its result or constructs continuation/approval authority.
"""

from __future__ import annotations

import threading
import time
from collections.abc import Callable, Mapping
from contextlib import ExitStack
from dataclasses import replace
from importlib import import_module
from typing import Any
from unittest.mock import patch

from scripts.native_slo_adapter import route_counts
from scripts.native_slo_contract import assert_privacy_safe
from scripts.native_slo_failure import failure_evidence
from scripts.native_slo_launcher_approval import LauncherApprovalControl
from scripts.native_slo_workloads import ExpectedResponse, QualificationCase


def approved_review_case(case: QualificationCase) -> QualificationCase:
    """Freeze the current launcher delivery; the native expectation stays review."""
    if case.event != "PreToolUse" or case.expected.reason_class != "review":
        raise ValueError("launcher review case is not an initial review")
    if case.harness == "codex":
        expected = ExpectedResponse(
            "implicit_allow",
            "not_applicable",
            "approved_review",
            {"hookSpecificOutput.hookEventName": "PreToolUse"},
        )
    elif case.harness == "claude-code":
        expected = ExpectedResponse(
            "allow",
            "not_applicable",
            "approved_review",
            {
                "continue": True,
                "policy_action": "allow",
                "reason_code": case.expected.reason_code,
                "hookSpecificOutput.hookEventName": "PreToolUse",
                "hookSpecificOutput.permissionDecision": "allow",
                "approval_reuse_status": "accepted",
            },
        )
    else:
        raise ValueError("launcher review harness unsupported")
    return replace(case, expected=expected)


class LauncherReviewFixture:
    """Bounded sibling control state for one private daemon fixture."""

    def __init__(self, session: Any, *, before_resolve: Callable[[str], None] | None = None) -> None:
        self.session = session
        self.controller = LauncherApprovalControl(session, before_resolve=before_resolve)
        self._fault_fixture: Any = None
        self._before: dict[str, dict[str, int]] = {}
        self._native_before: dict[str, int] = {}
        self._completions: list[dict[str, object]] = []
        self._native_evaluations: list[dict[str, object]] = []
        self._overflow = False
        self._witness_lock = threading.Lock()
        self._patch: ExitStack | None = None

    def _runner_routes(self) -> dict[str, int]:
        return dict(route_counts(self.session.daemon._server.hook_process_runner.stats()))

    def _capture_completion(self) -> None:
        if self._patch is not None:
            return
        from codex_plugin_scanner.guard.daemon import server

        def observe_completion(original: Any) -> Any:
            def observed(*args: Any, **kwargs: Any) -> dict[str, object]:
                result = original(*args, **kwargs)
                with self._witness_lock:
                    if len(self._completions) >= 128:
                        self._overflow = True
                    else:
                        self._completions.append(
                            {
                                "request_id": kwargs.get("request_id"),
                                "completed": result.get("completed") is True,
                                "action": result.get("action"),
                                "replayed": result.get("replayed") is True,
                                "error": result.get("error"),
                                "fresh_allow_authorized": kwargs.get("fresh_allow_authorized") is True,
                            }
                        )
                return result

            return observed

        worker = self.session.daemon._server.hook_worker
        original_native = worker._review_raw_hook_native

        def observe_native(**kwargs: Any) -> Any:
            edge = original_native(**kwargs)
            result = edge.get("result") if isinstance(edge, Mapping) else None
            witness: dict[str, object] = (
                {key: result.get(key) for key in ("decision", "policy_action", "minimum_action", "reason_code")}
                if isinstance(result, Mapping)
                else {"available": False}
            )
            with self._witness_lock:
                if len(self._native_evaluations) >= 128:
                    self._overflow = True
                else:
                    self._native_evaluations.append(witness)
            return edge

        with ExitStack() as stack:
            stack.enter_context(patch.object(worker, "_review_raw_hook_native", observe_native))
            stack.enter_context(
                patch.object(
                    server, "complete_codex_live_decision", observe_completion(server.complete_codex_live_decision)
                )
            )
            module_name = "codex_plugin_scanner.guard.daemon.codex_native_live_decision"
            try:
                native_completion = import_module(module_name)
            except ModuleNotFoundError as error:
                if error.name != module_name:
                    raise
            else:
                stack.enter_context(
                    patch.object(
                        native_completion,
                        "complete_codex_live_decision",
                        observe_completion(native_completion.complete_codex_live_decision),
                    )
                )
            self._patch = stack.pop_all()

    def dispatch(self, operation: str, request: Mapping[str, Any]) -> dict[str, object]:
        try:
            if operation in {"launcher_approval_fault_begin", "launcher_approval_fault_result"}:
                if self._fault_fixture is None:
                    from scripts.native_slo_approval_fault_fixture import LauncherApprovalFaultFixture

                    self._fault_fixture = LauncherApprovalFaultFixture(self.session)
                return self._fault_fixture.dispatch(operation, request)
            if operation == "launcher_approval_begin":
                payload = request.get("payload")
                if not isinstance(payload, Mapping):
                    raise ValueError("qualification launcher review payload missing")
                self._capture_completion()
                before = self._runner_routes()
                with self._witness_lock:
                    native_before = len(self._native_evaluations)
                result = self.controller.begin(
                    str(request.get("harness")),
                    payload,
                    resolution=str(request.get("resolution", "allow")),
                    timeout_seconds=request.get("timeout_seconds", 8),
                )
                self._before[str(result["operation_id"])] = before
                self._native_before[str(result["operation_id"])] = native_before
                return result
            if operation != "launcher_approval_result":
                raise ValueError("qualification launcher review operation unsupported")
            operation_id = str(request.get("operation_id"))
            result = self.controller.result(operation_id)
            if result.get("state") == "waiting":
                return result
            before = self._before[operation_id]
            after = self._runner_routes()
            delta = {name: after.get(name, 0) - before.get(name, 0) for name in set(before) | set(after)}
            request_id = result.get("request_id")
            with self._witness_lock:
                if self._overflow or any(value < 0 for value in delta.values()):
                    raise RuntimeError("qualification launcher review witness invalid")
                completions = [dict(item) for item in self._completions if item["request_id"] == request_id]
                native_evaluations = [
                    dict(item) for item in self._native_evaluations[self._native_before[operation_id] :]
                ]
            row = self.session.store.get_approval_request(request_id) if isinstance(request_id, str) else None
            resume = self.session.store.get_request_resume(request_id) if isinstance(request_id, str) else None
            continuation = row.get("continuation_snapshot") if isinstance(row, Mapping) else None
            return assert_privacy_safe(
                {
                    **result,
                    "live_decision": completions,
                    "native_evaluations": native_evaluations,
                    "revalidation_routes": {name: value for name, value in delta.items() if value},
                    "continuation_status": resume.get("status", "absent") if isinstance(resume, Mapping) else "absent",
                    "continuation_capability": continuation.get("capability", "absent")
                    if isinstance(continuation, Mapping)
                    else "absent",
                }
            )
        except Exception as error:
            return {"state": "failed", "failure": failure_evidence(error)}

    def close(self) -> None:
        try:
            try:
                if self._fault_fixture is not None:
                    self._fault_fixture.close()
            finally:
                self.controller.close()
        finally:
            if self._patch is not None:
                self._patch.close()
                self._patch = None


def await_resolution(session: Any, operation_id: str, *, timeout_seconds: float = 1.0) -> Mapping[str, object]:
    deadline = time.monotonic() + timeout_seconds
    while True:
        result = session.control("launcher_approval_result", operation_id=operation_id)
        if result.get("state") != "waiting":
            return result
        if time.monotonic() >= deadline:
            raise TimeoutError("qualification launcher review resolution deadline")
        time.sleep(0.01)


def validate_resolution(result: Mapping[str, object], *, harness: str) -> None:
    if (
        result.get("state") != "resolved"
        or result.get("resolution") != "allow"
        or result.get("approval_durable") is not True
        or result.get("authority") != "ordinary_local_review"
        or result.get("matching") != "exact_identity_and_new_row"
        or result.get("binding_present") is not True
    ):
        raise RuntimeError("qualification launcher review resolution unproven")
    if harness == "claude-code":
        routes = result.get("revalidation_routes")
        if result.get("live_decision") or not isinstance(routes, Mapping) or any(routes.values()):
            raise RuntimeError("qualification Claude review continuation was unexpected")
        return
    completions = result.get("live_decision")
    native_evaluations = result.get("native_evaluations")
    if (
        harness != "codex"
        or not isinstance(completions, list)
        or len(completions) != 1
        or not isinstance(completions[0], Mapping)
        or completions[0].get("completed") is not True
        or completions[0].get("fresh_allow_authorized") is not True
        or completions[0].get("replayed") is not False
        or completions[0].get("action") != "allow"
        or result.get("continuation_status") not in {"resumed", "sent"}
        or result.get("continuation_capability") != "suspended-response"
        or result.get("revalidation_routes") != {}
        or not isinstance(native_evaluations, list)
        or len(native_evaluations) != 2
        or any(
            not isinstance(item, Mapping)
            or item.get("decision") != "deny"
            or item.get("policy_action") != "review"
            or item.get("minimum_action") != "review"
            for item in native_evaluations
        )
    ):
        raise RuntimeError("qualification Codex browser continuation unproven")

"""Explicit installed-arm receipt readback; candidate never falls back."""

from __future__ import annotations

import re
from typing import Any


class InstalledReceiptReader:
    def __init__(self, store: Any, *, profile: str = "candidate") -> None:
        if profile not in {"candidate", "baseline_2e672d2"}:
            raise ValueError("mixed receipt profile unsupported")
        self.store, self.profile = store, profile
        self.getter = getattr(store, "get_native_decision_receipt", None)
        self.legacy = not callable(self.getter)
        if self.legacy and profile != "baseline_2e672d2":
            raise RuntimeError("candidate binding-aware receipt getter unavailable")
        if self.legacy:
            with store._connect() as connection:
                columns = connection.execute("pragma table_info(native_hook_decision_receipts)").fetchmany(65)
            if not columns or len(columns) >= 65 or any(row["name"] == "command_extensions_json" for row in columns):
                raise RuntimeError("installed schema does not match pinned legacy receipt arm")

    def read(self, identity: str) -> dict[str, object] | None:
        if re.fullmatch(r"[0-9a-f]{64}", identity) is None:
            return None
        if not self.legacy:
            assert callable(self.getter)
            result = self.getter(identity)
            return result if isinstance(result, dict) else None
        from codex_plugin_scanner.guard.native_decision_receipt import validate_native_decision_receipt

        with self.store._connect() as connection:
            row = connection.execute(
                "select * from native_hook_decision_receipts where decision_id = ?", (identity,)
            ).fetchone()
        if row is None:
            return None
        receipt = dict(row)
        receipt.pop("recorded_at", None)
        # Reject schema drift rather than stripping a candidate's new binding.
        if "command_extensions_json" in receipt or "command_extensions" in receipt:
            return None
        for field in ("workspace_bound", "source_ref_external_allowed", "observe_mode"):
            if receipt.get(field) not in (0, 1):
                return None
            receipt[field] = bool(receipt[field])
        return validate_native_decision_receipt(receipt)

"""Frozen delivered-response proof for the mixed Codex/Claude HTTP routes."""

from __future__ import annotations

from collections.abc import Mapping


def delivered_decision(event: str, response: Mapping[str, object]) -> str | None:
    """A missing/contradictory permission field is never a proven denial."""
    specific = response.get("hookSpecificOutput")
    if not isinstance(specific, Mapping) or specific.get("hookEventName") != event:
        return None
    action = response.get("policy_action")
    if event == "PreToolUse":
        permission = specific.get("permissionDecision")
        if (
            permission == "allow"
            and action in ("allow", "warn")
            and response.get("continue") is True
            and response.get("decision") in (None, "allow")
            and response.get("model_output_action") in (None, "not_applicable")
        ):
            return "allow"
        if permission == "deny" and action == "block" and response.get("decision") in (None, "deny", "block"):
            return "deny"
    if event == "PostToolUse":
        if (
            action in ("allow", "warn")
            and response.get("decision") is None
            and response.get("model_output_action") is None
            and (response.get("continue") is None or response.get("continue") is True)
        ):
            return "allow"
        if action == "block" and response.get("decision") == "block" and response.get("model_output_action") == "block":
            return "deny"
    return None

"""Retain bounded SLO failure observations without exporting response bodies."""

from __future__ import annotations

import re
from collections.abc import Callable, Iterator, Mapping
from contextlib import contextmanager
from contextvars import ContextVar

from scripts.native_slo_adapter import Observation
from scripts.native_slo_failure import FixtureFailureError, failure_evidence
from scripts.native_slo_semantic_diagnostic import semantic_diagnostic

_RECOVERY_OBSERVATION: ContextVar[dict[str, object] | None] = ContextVar(
    "qualification_recovery_observation", default=None
)


@contextmanager
def capture_recovery_observation() -> Iterator[dict[str, object]]:
    """Capture only this serial recovery call, never a concurrent peer's result."""
    detail: dict[str, object] = {}
    context = _RECOVERY_OBSERVATION.set(detail)
    try:
        yield detail
    finally:
        _RECOVERY_OBSERVATION.reset(context)


def retain_failed_recovery_observation(
    observation: Observation,
    response: Mapping[str, object],
    before: Mapping[str, int],
    after: Mapping[str, int],
) -> None:
    """Record closed evidence only if the active recovery result is unexpected."""
    detail = _RECOVERY_OBSERVATION.get()
    if detail is None or (observation.allowed and observation.route == "native_resident"):
        return
    detail.update(
        routes_before=dict(before),
        routes_after=dict(after),
        observed_semantics=verdict_evidence(response),
    )


def verdict_evidence(response: object = None, native: object = None) -> dict[str, object]:
    """Keep closed action labels; every non-frozen reason is a digest only."""
    result = semantic_diagnostic(response if isinstance(response, Mapping) else {}, native, cases=())
    if not isinstance(response, Mapping):
        result["delivered"] = {"available": False}
    for label in ("delivered", "native"):
        observed = result[label]
        if not isinstance(observed, dict):
            continue
        # The generic privacy sanitizer rejects fields containing 'output'.
        # These finite aliases preserve action evidence without relaxing it.
        for original, alias in (
            ("model_output_action", "model_action"),
            ("model_output_action_digest", "model_action_digest"),
        ):
            if original in observed:
                observed[alias] = observed.pop(original)
    return result


def contextual_failure(error: Exception, **detail: object) -> FixtureFailureError:
    """Enrich an existing failure once, preserving its original local message."""
    observed = dict(error.detail) if isinstance(error, FixtureFailureError) else failure_evidence(error)
    observed.update(detail)
    return FixtureFailureError(observed, message=str(error))


def _recovery_stop_evidence(value: object) -> dict[str, object]:
    """Copy fixed stop fields before cleanup can replace the session record."""

    result: dict[str, object] = {
        "available": False,
        "capture_boundary": "recovery_phase_exception_before_session_cleanup",
    }
    if not isinstance(value, Mapping) or value.get("schema") != "hol-guard.native-resident-stop-diagnostic.v1":
        return result
    statuses = {"not-run", "already-stopped", "contained", "failed", "contained_client_cleanup_failed"}
    if value.get("status") not in statuses:
        return result
    result.update(available=True, operation="resident-stop", status=value["status"])
    states = {"verified", "unknown", "true", "false", "free", "busy", "unverified", "absent", "present", "failed"}
    for field in (
        "acknowledged",
        "authenticated",
        "generation_present",
        "owner_lock",
        "marker_lock",
        "endpoint",
        "serving_shutdown",
        "client_cleanup",
    ):
        observed = value.get(field)
        if type(observed) is str and observed in states:
            result[field] = observed
    error = value.get("error")
    if type(error) is str and re.fullmatch(r"native_resident_stop_[a-z_]{1,64}", error):
        result["error"] = error
    return result


class SloProgress:
    """Keep completed phases/counts when a later phase or cleanup raises."""

    def __init__(self) -> None:
        self.completed: list[str] = []
        self.counts: dict[str, int] = {}

    @contextmanager
    def phase(self, name: str, *, stop_diagnostic: Callable[[], object] | None = None) -> Iterator[None]:
        try:
            yield
        except Exception as error:
            detail = dict(error.detail) if isinstance(error, FixtureFailureError) else {}
            if stop_diagnostic is not None:
                try:
                    detail["recovery_stop"] = _recovery_stop_evidence(stop_diagnostic())
                except Exception:
                    # Optional evidence must keep the original exception and
                    # all existing cleanup behavior, even if capture fails.
                    detail["recovery_stop"] = {"available": False, "capture_failed": True}
            prior_phases = detail.get("completed_phases", [])
            prior_counts = detail.get("completed_sample_counts", {})
            completed = list(self.completed)
            if isinstance(prior_phases, list):
                completed.extend(name for name in prior_phases if isinstance(name, str) and name not in completed)
            counts = dict(self.counts)
            if isinstance(prior_counts, Mapping):
                counts.update(
                    (key, count)
                    for key, count in prior_counts.items()
                    if isinstance(key, str) and isinstance(count, int) and not isinstance(count, bool) and count >= 0
                )
            raise contextual_failure(
                error,
                **({"recovery_stop": detail["recovery_stop"]} if "recovery_stop" in detail else {}),
                failed_phase=detail.get("failed_phase", name),
                completed_phases=completed[:32],
                completed_sample_counts=counts,
            ) from error
        self.completed.append(name)

"""Scoped, aggregate-only probes for actual Python JSON/hash callable work."""

from __future__ import annotations

from collections.abc import Callable
from typing import Any, Protocol


class Recorder(Protocol):
    def call(self, function: Callable[..., Any], name: str, *args: Any, **kwargs: Any) -> Any: ...

    def work(self, name: str, unit: str, count: int) -> None: ...


def byte_size(value: object) -> int | None:
    if isinstance(value, (bytes, bytearray)):
        return len(value)
    if isinstance(value, memoryview):
        return value.nbytes
    return None


class ModuleProbe:
    """Replace one importing module's binding, never the shared library module."""

    def __init__(self, target: Any, overrides: dict[str, Any]) -> None:
        self._target = target
        self._overrides = overrides

    def __getattr__(self, name: str) -> Any:
        return self._overrides[name] if name in self._overrides else getattr(self._target, name)


def json_probe(target: Any, recorder: Recorder, prefix: str) -> ModuleProbe:
    def dumps(*args: Any, **kwargs: Any) -> Any:
        name = f"{prefix}_json_dumps"
        result = recorder.call(target.dumps, name, *args, **kwargs)
        if isinstance(result, str):
            # A JSON string is not UTF-8 bytes. Never re-encode just to count it.
            recorder.work(name, "returned_characters", len(result))
        return result

    def loads(*args: Any, **kwargs: Any) -> Any:
        name = f"{prefix}_json_loads"
        value = args[0] if args else kwargs.get("s")
        size = byte_size(value)
        if size is not None:
            recorder.work(name, "attempted_input_bytes", size)
        elif isinstance(value, str):
            recorder.work(name, "attempted_input_characters", len(value))
        return recorder.call(target.loads, name, *args, **kwargs)

    return ModuleProbe(target, {"dumps": dumps, "loads": loads})


def hashlib_probe(target: Any, recorder: Recorder, prefix: str) -> ModuleProbe:
    def sha256(*args: Any, **kwargs: Any) -> Any:
        name = f"{prefix}_sha256_init"
        value = args[0] if args else kwargs.get("string", b"")
        size = byte_size(value)
        if size is not None:
            recorder.work(name, "attempted_input_bytes", size)
        digest = recorder.call(target.sha256, name, *args, **kwargs)
        if size is not None:
            recorder.work(name, "hashed_bytes", size)
        return HashProbe(digest, recorder, prefix)

    return ModuleProbe(target, {"sha256": sha256})


class HashProbe:
    def __init__(self, target: Any, recorder: Recorder, prefix: str) -> None:
        self._target, self._recorder, self._prefix = target, recorder, prefix

    def __getattr__(self, name: str) -> Any:
        return getattr(self._target, name)

    def update(self, data: Any) -> Any:
        name = f"{self._prefix}_sha256_update"
        size = byte_size(data)
        if size is not None:
            self._recorder.work(name, "attempted_input_bytes", size)
        result = self._recorder.call(self._target.update, name, data)
        if size is not None:
            self._recorder.work(name, "hashed_bytes", size)
        return result

    def digest(self) -> Any:
        return self._recorder.call(self._target.digest, f"{self._prefix}_sha256_finalize")

    def hexdigest(self) -> Any:
        return self._recorder.call(self._target.hexdigest, f"{self._prefix}_sha256_finalize")

    def copy(self) -> HashProbe:
        return HashProbe(self._target.copy(), self._recorder, self._prefix)

"""Bounded work counts at real serializer, pipe, hash and HTTP I/O boundaries."""

from __future__ import annotations

import functools
from contextlib import ExitStack
from typing import Any
from unittest.mock import patch

from scripts.native_slo_phase_calls import ModuleProbe, byte_size, hashlib_probe, json_probe
from scripts.native_slo_phase_waits import frame_writer


class _IOProbe:
    def __init__(self, target: Any, recorder: Any) -> None:
        self._target, self._recorder = target, recorder

    def __getattr__(self, name: str) -> Any:
        return getattr(self._target, name)

    def read1(self, *args: Any, **kwargs: Any) -> Any:
        result = self._recorder.call(self._target.read1, "http_body_read", *args, **kwargs)
        size = byte_size(result)
        if size is not None:
            self._recorder.work("http_body_read", "returned_bytes", size)
        return result

    def write(self, data: Any) -> Any:
        size = byte_size(data)
        if size is not None:
            self._recorder.work("http_response_write", "attempted_bytes", size)
        result = self._recorder.call(self._target.write, "http_response_write", data)
        if type(result) is int and result >= 0:
            self._recorder.work("http_response_write", "written_bytes", result)
        else:
            self._recorder.work("http_response_write", "unknown_written_count", 1)
        return result


def _io_method(function: Any, recorder: Any, attribute: str, phase: str) -> Any:
    @functools.wraps(function)
    def measured(self: Any, *args: Any, **kwargs: Any) -> Any:
        # Handler instances belong to one HTTP request thread. Preserve the
        # exact original stream even when the underlying function raises.
        with patch.object(self, attribute, _IOProbe(getattr(self, attribute), recorder)):
            return recorder.call(function, phase, self, *args, **kwargs)

    return measured


def _encoded_result(function: Any, recorder: Any, phase: str) -> Any:
    @functools.wraps(function)
    def measured(*args: Any, **kwargs: Any) -> Any:
        result = recorder.call(function, phase, *args, **kwargs)
        size = byte_size(result)
        if size is not None:
            recorder.work(phase, "returned_bytes", size)
        return result

    return measured


def install_io_probes(stack: ExitStack, recorder: Any) -> None:
    from codex_plugin_scanner.guard import (
        native_hook_edge,
        native_resident_stream,
        native_runtime,
        native_runtime_identity,
    )
    from codex_plugin_scanner.guard.daemon import runtime_hook_evidence_journal, server

    for owner, prefix in (
        (native_hook_edge, "edge"),
        (server, "daemon"),
        (runtime_hook_evidence_journal, "evidence"),
    ):
        stack.enter_context(patch.object(owner, "json", json_probe(owner.json, recorder, prefix)))
    # Avoid replacing server.hashlib: hmac.new(..., hashlib.sha256) would
    # select a different HMAC implementation if passed a wrapped constructor.
    for owner, prefix in ((native_runtime, "runtime"), (native_runtime_identity, "runtime_manifest")):
        stack.enter_context(patch.object(owner, "hashlib", hashlib_probe(owner.hashlib, recorder, prefix)))

    struct_module = native_resident_stream.struct

    def pack(*args: Any, **kwargs: Any) -> Any:
        result = recorder.call(struct_module.pack, "client_frame_header_pack", *args, **kwargs)
        recorder.work("client_frame_header_pack", "returned_bytes", len(result))
        return result

    def unpack(*args: Any, **kwargs: Any) -> Any:
        # The persistent reader does not inherit a request's ContextVar and
        # may outlive several requests. Keep its count explicitly unassigned.
        return recorder.reader_call(struct_module.unpack, "client_frame_header_unpack", *args, **kwargs)

    stack.enter_context(
        patch.object(native_resident_stream, "struct", ModuleProbe(struct_module, {"pack": pack, "unpack": unpack}))
    )

    process_module = native_resident_stream.subprocess

    def spawn(*args: Any, **kwargs: Any) -> Any:
        return recorder.call(process_module.Popen, "client_process_spawn", *args, **kwargs)

    stack.enter_context(
        patch.object(native_resident_stream, "subprocess", ModuleProbe(process_module, {"Popen": spawn}))
    )
    stack.enter_context(
        patch.object(native_resident_stream, "write_frame", frame_writer(native_resident_stream.write_frame, recorder))
    )
    handler = server._GuardDaemonHandler
    targets = (
        (native_hook_edge, "_encode_hook_envelope", "envelope_encode"),
        (runtime_hook_evidence_journal._NativeDecisionReceiptRecord, "serialized", "receipt_record_serialization"),
    )
    for owner, name, phase in targets:
        stack.enter_context(patch.object(owner, name, _encoded_result(getattr(owner, name), recorder, phase)))
    stack.enter_context(
        patch.object(
            handler,
            "_read_request_body",
            _io_method(handler._read_request_body, recorder, "rfile", "http_body_read_inclusive"),
        )
    )
    stack.enter_context(
        patch.object(
            handler, "_write_json", _io_method(handler._write_json, recorder, "wfile", "response_encode_write")
        )
    )

"""Request-scoped scheduler/pool/stream waits; no fabricated socket timer."""

from __future__ import annotations

import contextvars
import functools
import threading
from contextlib import ExitStack
from dataclasses import dataclass
from queue import Queue
from typing import Any
from unittest.mock import patch

from scripts.native_slo_phase_calls import Recorder, byte_size

_CONDITION = contextvars.ContextVar[tuple[object, str] | None]("phase_condition", default=None)
_QUEUED = contextvars.ContextVar[list[Any] | None]("phase_queued", default=None)


@dataclass
class _StreamScope:
    queue: object | None = None


_STREAM = contextvars.ContextVar[_StreamScope | None]("phase_stream", default=None)


def install_wait_probes(stack: ExitStack, recorder: Any) -> None:
    from codex_plugin_scanner.guard import native_resident_client, native_resident_stream
    from codex_plugin_scanner.guard.daemon.runtime_hook_scheduler import RuntimeHookScheduler

    acquire = RuntimeHookScheduler.acquire
    reserve = RuntimeHookScheduler.reserve_bytes
    enqueue = RuntimeHookScheduler._enqueue
    lease = native_resident_client._PersistentNativeClientPool._lease
    request = native_resident_stream._PersistentNativeClient.request
    snapshot = native_resident_stream._PersistentNativeClient._request_snapshot
    condition_wait = threading.Condition.wait
    queue_get = Queue.get

    @functools.wraps(reserve)
    def measured_reserve(self: Any, *args: Any, **kwargs: Any) -> Any:
        recorder.work("byte_admission", "attempted_payload_bytes", kwargs.get("payload_bytes"))
        result = recorder.call(reserve, "byte_admission", self, *args, **kwargs)
        recorder.work("byte_admission", "reserved" if result[0] is not None else "rejected", 1)
        return result

    @functools.wraps(acquire)
    def measured_acquire(self: Any, *args: Any, **kwargs: Any) -> Any:
        captured: list[Any] = []
        item_token = _QUEUED.set(captured)
        wait_token = _CONDITION.set((self._condition, "scheduler_condition_wait"))
        result = None
        try:
            recorder.work("admission_and_queue", "attempted_payload_bytes", kwargs.get("payload_bytes"))
            result = recorder.call(acquire, "admission_and_queue", self, *args, **kwargs)
            return result
        finally:
            _CONDITION.reset(wait_token)
            _QUEUED.reset(item_token)
            if captured:
                item = captured[0]
                if item.admitted_at is not None:
                    # Real scheduler timestamps, including when a different
                    # request's release dispatches this waiting request.
                    recorder.duration("scheduler_queue_admitted", max(0, item.admitted_at - item.queued_at) * 1000)
                else:
                    # Retain rejected/cancelled work; the end is acquire's
                    # return, NOT a claimed exact dequeue timestamp.
                    recorder.duration(
                        "scheduler_queue_unadmitted_until_return", max(0, self._monotonic() - item.queued_at) * 1000
                    )
                recorder.work("admission_and_queue", "enqueued_attempts", 1)
            else:
                recorder.work("admission_and_queue", "never_enqueued_attempts", 1)
            if result is not None:
                recorder.work("admission_and_queue", "admitted" if result.permit is not None else "rejected", 1)

    @functools.wraps(enqueue)
    def measured_enqueue(self: Any, item: Any) -> Any:
        result = enqueue(self, item)
        captured = _QUEUED.get()
        if captured is not None and not captured:
            captured.append(item)
        return result

    @functools.wraps(lease)
    def measured_lease(self: Any, *args: Any, **kwargs: Any) -> Any:
        token = _CONDITION.set((self._condition, "client_pool_condition_wait"))
        try:
            return recorder.call(lease, "client_pool_lease_inclusive", self, *args, **kwargs)
        finally:
            _CONDITION.reset(token)

    @functools.wraps(condition_wait)
    def measured_wait(self: Any, *args: Any, **kwargs: Any) -> Any:
        scope = _CONDITION.get()
        if scope is None or self is not scope[0]:
            return condition_wait(self, *args, **kwargs)
        return recorder.call(condition_wait, scope[1], self, *args, **kwargs)

    @functools.wraps(request)
    def measured_request(self: Any, payload: bytes, *args: Any, **kwargs: Any) -> Any:
        token = _STREAM.set(_StreamScope())
        try:
            size = byte_size(payload)
            if size is not None:
                recorder.work("client_stream_exchange_inclusive", "attempted_payload_bytes", size)
            result = recorder.call(request, "client_stream_exchange_inclusive", self, payload, *args, **kwargs)
            if isinstance(result, bytes):
                recorder.work("client_stream_exchange_inclusive", "returned_payload_bytes", len(result))
            return result
        finally:
            _STREAM.reset(token)

    @functools.wraps(snapshot)
    def measured_snapshot(self: Any) -> Any:
        result = recorder.call(snapshot, "client_snapshot_start_or_attestation", self)
        scope = _STREAM.get()
        if scope is not None and result is not None:
            scope.queue = result[2]
        return result

    @functools.wraps(queue_get)
    def measured_get(self: Any, *args: Any, **kwargs: Any) -> Any:
        scope = _STREAM.get()
        if scope is None or self is not scope.queue:
            return queue_get(self, *args, **kwargs)
        result = recorder.call(queue_get, "client_response_wait_inclusive", self, *args, **kwargs)
        if isinstance(result, bytes):
            recorder.work("client_response_wait_inclusive", "delivered_payload_bytes", len(result))
        else:
            recorder.work("client_response_wait_inclusive", "stream_failure_sentinels", 1)
        return result

    targets = (
        (RuntimeHookScheduler, "reserve_bytes", measured_reserve),
        (RuntimeHookScheduler, "acquire", measured_acquire),
        (RuntimeHookScheduler, "_enqueue", measured_enqueue),
        (native_resident_client._PersistentNativeClientPool, "_lease", measured_lease),
        (native_resident_stream._PersistentNativeClient, "request", measured_request),
        (native_resident_stream._PersistentNativeClient, "_request_snapshot", measured_snapshot),
        (threading.Condition, "wait", measured_wait),
        (Queue, "get", measured_get),
    )
    for owner, name, wrapped in targets:
        stack.enter_context(patch.object(owner, name, wrapped))


def frame_writer(function: Any, recorder: Recorder) -> Any:
    @functools.wraps(function)
    def measured(stdin: Any, frame: bytes, **kwargs: Any) -> Any:
        recorder.work("client_frame_write", "attempted_frame_bytes", len(frame))
        result = recorder.call(function, "client_frame_write", stdin, frame, **kwargs)
        if result is True:
            recorder.work("client_frame_write", "completed_frame_bytes", len(frame))
        else:
            # False can follow a partial write, not necessarily zero bytes.
            recorder.work("client_frame_write", "partial_or_unwritten_attempts", 1)
        return result

    return measured

"""Real public mutations and bounded physical faults in a disposable daemon."""

from __future__ import annotations

import time
from collections.abc import Callable, Mapping
from pathlib import Path
from typing import Any

from scripts.native_slo_contract import MAX_READINESS_P95_MS
from scripts.native_slo_expiry import _authenticated_readback, _readback_matches, expire_acknowledged_authority
from scripts.native_slo_posture_witness import binding_key

_READINESS_SECONDS = MAX_READINESS_P95_MS / 1000


class PostureControls:
    def __init__(self, session: Any) -> None:
        self.session = session
        self.worker = session.daemon._server.hook_worker
        self.publisher = self.worker.policy_snapshot_publisher
        self.known: set[tuple[object, ...]] = set()
        self.strict_workspace = session.root / "posture-strict-workspace"
        self.mode = "enforce"
        self.progress: dict[str, object] = {}

    def workspace(self, scope: str) -> Path:
        if scope not in {"initial", "strict"}:
            raise ValueError("posture workspace scope invalid")
        return self.strict_workspace if scope == "strict" else self.session.workspace

    def ack(self, *, previous: int = 0, strict: bool = False) -> Mapping[str, Any]:
        """One unchanged 400 ms barrier, then independent authenticated readback."""
        deadline = time.monotonic() + _READINESS_SECONDS
        while True:
            prepared = self.worker.prepare_workspace_policy(
                self.workspace("strict" if strict else "initial"), deadline=deadline
            )
            snapshot = self.publisher.current_snapshot()
            if isinstance(prepared, Mapping) and isinstance(snapshot, Mapping):
                binding, accepted = _authenticated_readback(self.session.store)
                effective = snapshot.get("effective_policy")
                generation = snapshot.get("generation")
                if (
                    _readback_matches(binding, accepted, snapshot)
                    and binding_key(prepared) == binding_key(snapshot)
                    and snapshot.get("mode") == self.mode
                    and type(generation) is int
                    and generation > previous
                    and (
                        not strict or (isinstance(effective, Mapping) and effective.get("sandbox_analysis") == "strict")
                    )
                    and time.monotonic() <= deadline
                ):
                    self.known.add(binding_key(snapshot))
                    return snapshot
            if time.monotonic() >= deadline:
                raise RuntimeError("posture authenticated acknowledgment deadline")
            time.sleep(0.005)

    def _mode_mutation(self, mode: str) -> None:
        from codex_plugin_scanner.guard.config import update_guard_settings

        if mode not in {"enforce", "observe"}:
            raise ValueError("posture mode invalid")
        self.progress["public_mutation_attempted"] = True
        update_guard_settings(
            self.session.guard_home, {"protection_posture": "watch" if mode == "observe" else "protected"}
        )
        self.progress["public_mutation_returned"] = True
        self.mode = mode

    def apply(
        self,
        operation: str,
        before: Mapping[str, Any],
        probe: Callable[[str, str | tuple[object, ...]], None],
    ) -> Mapping[str, Any] | None:
        self.progress = {"operation": operation, "deadline_ms": MAX_READINESS_P95_MS}
        if operation in {"enforce_to_watch", "watch_to_enforce"}:
            if before.get("mode") != ("enforce" if operation == "enforce_to_watch" else "observe"):
                raise RuntimeError("posture transition starting mode mismatch")
            self._mode_mutation("observe" if operation == "enforce_to_watch" else "enforce")
            return self.ack(previous=int(before["generation"]))
        if operation == "watch_restart":
            if self.mode != "observe":
                raise RuntimeError("posture Watch restart requires acknowledged Watch")
            self.progress.update(contained=self.session.stop_resident(), python_process_restarted=False)
            if self.progress["contained"] is not True:
                raise RuntimeError("posture resident containment failed")
            # A resident restart can retain the authenticated generation. Do
            # not demand a fabricated new policy generation for unchanged inputs.
            return self.ack()
        if operation == "first_strict_workspace":
            return self._first_workspace(before, probe)
        if operation == "failed_publication":
            return self._failed_publication(before, probe)
        if operation == "expiry":
            self.progress.update(expire_acknowledged_authority(self.session))
            if not all(
                self.progress.get(key) is True
                for key in (
                    "expired_resident_authority",
                    "short_lived_acknowledged",
                    "starting_authority_authenticated",
                    "authenticated_readback",
                    "policy_preserved",
                    "control_binding_preserved",
                    "policy_prepare_rejected",
                    "refresh_suspended",
                )
            ):
                raise RuntimeError("posture expiry fault proof incomplete")
            probe("initial", "unavailable")
            return None
        raise ValueError("unsupported posture transition")

    def _first_workspace(
        self, before: Mapping[str, Any], probe: Callable[[str, str | tuple[object, ...]], None]
    ) -> Mapping[str, Any]:
        from codex_plugin_scanner.guard.native_policy_snapshot_storage import _v3_generation_lock

        self.strict_workspace.mkdir(mode=0o700)
        config = self.strict_workspace / ".hol-guard.toml"
        with config.open("x", encoding="utf-8") as stream:
            config.chmod(0o600)
            # Workspace mode/posture overrides are deliberately unsupported.
            # Exercise a real permitted stricter overlay and ignored weakening.
            stream.write('sandbox_analysis = "strict"\nmode = "observe"\nprotection_posture = "watch"\n')
        self.progress["workspace_file_created"] = True
        resolved = self.publisher._resolved_workspace(self.strict_workspace)
        with self.publisher._condition:
            first = resolved not in self.publisher._workspace_paths
        self.progress["previously_unregistered"] = first
        if not first:
            raise RuntimeError("posture first workspace already registered")
        # Hold the real publication lock; do not replace readiness, ACK bytes,
        # the generation state, native evaluation, or its clock.
        with _v3_generation_lock(self.session.guard_home, deadline_monotonic=time.monotonic() + _READINESS_SECONDS):
            probe("strict", "unavailable")
            self.progress["first_use_delivered_unavailable"] = True
            self.progress["first_use_withdrew_ack"] = self.publisher.current_snapshot_binding() is None
            probe("initial", "unavailable")
            if self.progress["first_use_withdrew_ack"] is not True:
                raise RuntimeError("posture first workspace reused prior authority")
        result = self.ack(previous=int(before["generation"]), strict=True)
        self.progress["stricter_digest_changed"] = result["policy_digest"] != before["policy_digest"]
        self.progress["workspace_could_not_weaken_mode"] = result["mode"] == "enforce"
        if not all(
            self.progress[key] is True for key in ("stricter_digest_changed", "workspace_could_not_weaken_mode")
        ):
            raise RuntimeError("posture workspace overlay did not publish a stricter binding")
        return result

    def _failed_publication(
        self, before: Mapping[str, Any], probe: Callable[[str, str | tuple[object, ...]], None]
    ) -> Mapping[str, Any]:
        from codex_plugin_scanner.guard.native_policy_snapshot_constants import _PUBLISH_TIMEOUT_SECONDS
        from codex_plugin_scanner.guard.native_policy_snapshot_storage import _v3_generation_lock

        with _v3_generation_lock(self.session.guard_home, deadline_monotonic=time.monotonic() + _READINESS_SECONDS):
            self.progress["publication_lock_held"] = True
            self._mode_mutation("observe")
            self.progress["mutation_withdrew_ack"] = self.publisher.current_snapshot_binding() is None
            # Observation can wait for the existing platform publication budget;
            # no production deadline, retry schedule, or result is changed.
            deadline = time.monotonic() + _PUBLISH_TIMEOUT_SECONDS + _READINESS_SECONDS
            while self.publisher.last_error != "native_policy_snapshot_generation_lock_timeout":
                if time.monotonic() >= deadline:
                    raise RuntimeError("posture actual publication lock failure not observed")
                time.sleep(0.01)
            self.progress["publication_failed_at_generation_lock"] = True
            self.progress["failed_publication_withheld_ack"] = self.publisher.current_snapshot_binding() is None
            probe("initial", "unavailable")
            if not all(
                self.progress[key] is True for key in ("mutation_withdrew_ack", "failed_publication_withheld_ack")
            ):
                raise RuntimeError("posture failed publication retained readiness")
        self.progress["publication_lock_released"] = True
        return self.ack(previous=int(before["generation"]))

"""Measure the four priority hooks using their installed command registrations.

Every sample starts the registered executable, sends stdin, captures stdout,
waits for exit, and checks the harness response. No direct HTTP request replaces
a launcher. The caller owns a prepared, otherwise idle daemon with an explicit
acknowledged allow policy (``DaemonFixture(runtime, policy="normal")``).
"""

from __future__ import annotations

import hashlib
import importlib
import json
import os
import shlex
import sys
import threading
import time
from collections.abc import Mapping
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol, cast

from codex_plugin_scanner.guard.adapters.base import HarnessContext
from codex_plugin_scanner.guard.adapters.claude_code import ClaudeCodeHarnessAdapter
from codex_plugin_scanner.guard.adapters.claude_hook_config import (
    claude_managed_settings_path,
    command_handler_argv,
    is_guard_hook_handler,
)
from codex_plugin_scanner.guard.adapters.codex import CodexHarnessAdapter
from codex_plugin_scanner.guard.codex_hook_launch_runtime import run_isolated_hook_process
from scripts.native_probe_receipts import wait_for_route_corpus
from scripts.native_slo_adapter import Observation, route_counts
from scripts.native_slo_batch import validate_batch_routes
from scripts.native_slo_contract import clear_proof_environment, summarize

_CONFIG_LIMIT = 1_000_000
_TOML = importlib.import_module("tomllib" if sys.version_info >= (3, 11) else "tomli")
_OUTPUT_LIMIT = 2 * 1024 * 1024
_LAUNCH_TIMEOUT_SECONDS = 10.0
_MAX_SAMPLES_PER_SERIES = 100_000
_CONCURRENCY = 16
_PRIORITY_ROUTES = (
    ("claude-code", "PreToolUse"),
    ("claude-code", "PostToolUse"),
    ("codex", "PreToolUse"),
    ("codex", "PostToolUse"),
)


class _Metrics(Protocol):
    def snapshot(self) -> Mapping[str, object]: ...


class _Worker(Protocol):
    metrics: _Metrics


class _Server(Protocol):
    hook_worker: _Worker


class _Daemon(Protocol):
    _server: _Server


class LauncherSession(Protocol):
    """Only control metadata is shared with the load generator."""

    root: Path
    workspace: Path
    guard_home: Path
    daemon: _Daemon


@dataclass(frozen=True, slots=True)
class RegisteredLauncher:
    harness: str
    event: str
    argv: tuple[str, ...]
    environment: tuple[tuple[str, str], ...]
    registration_sha256: str
    config_path: Path


def _read_configuration(path: Path, *, is_toml: bool) -> Mapping[str, object]:
    with path.open("rb") as stream:
        raw = stream.read(_CONFIG_LIMIT + 1)
    if len(raw) > _CONFIG_LIMIT:
        raise RuntimeError("priority_launcher_configuration_limit")
    try:
        parsed: object = _TOML.loads(raw.decode("utf-8")) if is_toml else json.loads(raw)
    except (UnicodeDecodeError, ValueError) as error:
        raise RuntimeError("priority_launcher_configuration_invalid") from error
    if not isinstance(parsed, Mapping):
        raise RuntimeError("priority_launcher_configuration_invalid")
    return cast(Mapping[str, object], parsed)


def registered_launcher(config_path: Path, harness: str, event: str) -> RegisteredLauncher:
    """Read exact generated argv and environment back from the installed file.

    Codex's adapter serializes argv with POSIX ``shlex.join`` on every platform.
    Require a lossless round trip; never execute reconstructed shell operators.
    Claude's installed structured command/args need no tokenization.
    """

    if (harness, event) not in _PRIORITY_ROUTES:
        raise ValueError("priority_launcher_route_unsupported")
    configuration = _read_configuration(config_path, is_toml=harness == "codex")
    if harness == "codex":
        features = configuration.get("features")
        if not isinstance(features, Mapping) or features.get("hooks") is not True:
            raise RuntimeError("priority_launcher_hooks_disabled")
    hooks = configuration.get("hooks")
    groups = hooks.get(event) if isinstance(hooks, Mapping) else None
    if not isinstance(groups, list):
        raise RuntimeError("priority_launcher_registration_missing")
    registrations: list[tuple[tuple[str, ...], tuple[tuple[str, str], ...], Mapping[str, object]]] = []
    for group in groups:
        if not isinstance(group, Mapping) or group.get("enabled", True) is not True:
            raise RuntimeError("priority_launcher_group_invalid")
        handlers = group.get("hooks")
        if not isinstance(handlers, list):
            raise RuntimeError("priority_launcher_group_invalid")
        for raw_handler in handlers:
            if not isinstance(raw_handler, dict) or raw_handler.get("enabled", True) is not True:
                raise RuntimeError("priority_launcher_handler_invalid")
            handler = cast(dict[str, object], raw_handler)
            if handler.get("type") != "command":
                raise RuntimeError("priority_launcher_handler_not_command")
            if harness == "claude-code":
                if not is_guard_hook_handler(handler):
                    raise RuntimeError("priority_launcher_unmanaged_handler")
                argv = command_handler_argv(handler)
            else:
                command = handler.get("command")
                if not isinstance(command, str):
                    raise RuntimeError("priority_launcher_command_invalid")
                try:
                    argv = tuple(shlex.split(command, posix=True))
                except ValueError as error:
                    raise RuntimeError("priority_launcher_command_invalid") from error
                if shlex.join(argv) != command:
                    raise RuntimeError("priority_launcher_command_not_lossless")
                if len(argv) != 4 or argv[1] != "-I" or Path(argv[2]).name != "codex_daemon_hook_bridge.py":
                    raise RuntimeError("priority_launcher_unmanaged_handler")
            if not argv or any(not isinstance(arg, str) or "\x00" in arg for arg in argv):
                raise RuntimeError("priority_launcher_command_invalid")
            configured_env = handler.get("env", {})
            if not isinstance(configured_env, Mapping) or any(
                not isinstance(key, str) or not isinstance(value, str) for key, value in configured_env.items()
            ):
                raise RuntimeError("priority_launcher_environment_invalid")
            environment = tuple(sorted(cast(Mapping[str, str], configured_env).items()))
            registrations.append((argv, environment, {"group": dict(group), "handler": handler}))
    if len(registrations) != 1:
        raise RuntimeError("priority_launcher_registration_missing_or_ambiguous")
    argv, environment, registered = registrations[0]
    digest = hashlib.sha256(json.dumps(registered, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return RegisteredLauncher(harness, event, argv, environment, digest, config_path)


def install_priority_launchers(session: LauncherSession) -> tuple[RegisteredLauncher, ...]:
    """Install once into the fixture home, then independently read both configs."""

    # Both installed arms use this owned workspace even when a frozen payload
    # deliberately omits cwd. Codex only registers it for an explicit override.
    context = HarnessContext(
        home_dir=session.root,
        workspace_dir=session.workspace,
        guard_home=session.guard_home,
        workspace_override_explicit=True,
    )
    claude = ClaudeCodeHarnessAdapter().install(context)
    codex = CodexHarnessAdapter().install(context)
    if claude.get("active") is not True or codex.get("active") is not True:
        raise RuntimeError("priority_launcher_install_incomplete")
    claude_path = claude_managed_settings_path(context)
    codex_path = CodexHarnessAdapter._hook_config_path(context)
    return tuple(
        registered_launcher(claude_path if harness == "claude-code" else codex_path, harness, event)
        for harness, event in _PRIORITY_ROUTES
    )


def launcher_payload(event: str, sample: int, *, case: str = "benign") -> dict[str, object]:
    """Create only synthetic payloads; neither sample command is executed."""

    if case not in {"benign", "block"} or event not in {"PreToolUse", "PostToolUse"}:
        raise ValueError("priority_launcher_case_unsupported")
    result: dict[str, object] = {
        "hook_event_name": event,
        "guard_remaining_ms": 4_000,
        "tool_use_id": f"priority-qualification-{sample}",
    }
    if event == "PreToolUse":
        result.update(tool_name="Bash", tool_input={"command": "pwd" if case == "benign" else "rm -rf /"})
    else:
        prefix = ("gh" + "p_" + "b" * 30 + "\n") if case == "block" else ""
        content = (prefix + "const guard_value = 1;\n" * 49)[:1024]
        result.update(tool_name="Read", tool_response=[{"type": "text", "text": content}])
    return result


def validate_launcher_stdout(launcher: RegisteredLauncher, response: Mapping[str, object], *, case: str) -> None:
    """Frozen delivered contracts, including Codex's metadata filtering."""

    if case not in {"benign", "block"}:
        raise ValueError("priority_launcher_case_unsupported")
    allowed = case == "benign"
    specific = response.get("hookSpecificOutput")
    if not isinstance(specific, Mapping) or specific.get("hookEventName") != launcher.event:
        raise RuntimeError("priority_launcher_event_mismatch")
    if launcher.event == "PreToolUse":
        if specific.get("permissionDecision") != ("allow" if allowed else "deny"):
            raise RuntimeError("priority_launcher_permission_mismatch")
        if allowed and response.get("continue") is not True:
            raise RuntimeError("priority_launcher_continue_mismatch")
        if not allowed and (
            "continue" in response
            or not isinstance(specific.get("permissionDecisionReason"), str)
            or not specific["permissionDecisionReason"]
        ):
            raise RuntimeError("priority_launcher_block_mismatch")
    elif allowed:
        if set(specific) != {"hookEventName"} or "decision" in response or "model_output_action" in response:
            raise RuntimeError("priority_launcher_post_allow_mismatch")
    elif response.get("decision") != "block" or response.get("continue") is not True:
        raise RuntimeError("priority_launcher_post_block_mismatch")
    if launcher.harness == "codex":
        keys = {"hookSpecificOutput"}
        if launcher.event == "PreToolUse" and allowed:
            keys.add("continue")
        if launcher.event == "PostToolUse" and not allowed:
            keys |= {"decision", "reason", "continue", "stopReason"}
        if set(response) != keys:
            raise RuntimeError("priority_launcher_codex_schema_mismatch")
        if not allowed:
            reason = (
                "HOL Guard blocked a destructive command before execution."
                if launcher.event == "PreToolUse"
                else "HOL Guard blocked this output because it contains sensitive content."
            )
            if launcher.event == "PreToolUse":
                if specific.get("permissionDecisionReason") != reason:
                    raise RuntimeError("priority_launcher_pre_reason_mismatch")
            elif (
                response.get("reason") != reason
                or response.get("stopReason") != reason
                or specific.get("additionalContext") != reason
            ):
                raise RuntimeError("priority_launcher_post_reason_mismatch")
    else:
        if response.get("policy_action") != ("allow" if allowed else "block"):
            raise RuntimeError("priority_launcher_policy_mismatch")
        expected_reason = "native_exact_safe_command" if allowed else "native_destructive_command"
        if launcher.event == "PreToolUse" and response.get("reason_code") != expected_reason:
            raise RuntimeError("priority_launcher_reason_mismatch")
        if launcher.event == "PostToolUse":
            if allowed and "reason_code" in response:
                raise RuntimeError("priority_launcher_unexpected_reason")
            if not allowed and (
                response.get("reason_code") != "output_secret_match" or response.get("model_output_action") != "block"
            ):
                raise RuntimeError("priority_launcher_secret_mismatch")


def observe_priority_launcher(
    session: LauncherSession,
    launcher: RegisteredLauncher,
    *,
    sample: int,
    case: str = "benign",
    stop_event: threading.Event | None = None,
) -> Observation:
    """Time real process startup/stdin/transport/stdout/exit; attribute routes later."""

    environment = dict(os.environ)
    clear_proof_environment(environment)
    environment.update(launcher.environment)
    # A fixture-specific child home is the installed harness context. Do not
    # mutate the parent process's HOME/CODEX_HOME or inherit another user's home.
    environment["HOME"] = str(session.root)
    environment["USERPROFILE"] = str(session.root)
    if launcher.harness == "codex":
        environment["CODEX_HOME"] = str(session.root / ".codex")
    encoded = json.dumps(launcher_payload(launcher.event, sample, case=case), separators=(",", ":"))
    started = time.perf_counter()
    completed = run_isolated_hook_process(
        launcher.argv,
        input_text=encoded,
        cwd=session.workspace,
        environment=environment,
        timeout_seconds=_LAUNCH_TIMEOUT_SECONDS,
        output_limit=_OUTPUT_LIMIT,
        stop_event=stop_event,
    )
    elapsed_ms = (time.perf_counter() - started) * 1_000.0
    if (
        completed.returncode != 0
        or completed.timed_out
        or completed.containment_failed
        or completed.output_limit_exceeded
    ):
        raise RuntimeError("priority_launcher_process_contract_failed")
    try:
        response: object = json.loads(completed.stdout)
    except (ValueError, UnicodeDecodeError) as error:
        raise RuntimeError("priority_launcher_stdout_not_json") from error
    if not isinstance(response, Mapping):
        raise RuntimeError("priority_launcher_stdout_not_object")
    try:
        validate_launcher_stdout(launcher, cast(Mapping[str, object], response), case=case)
    except Exception as error:
        from scripts.native_slo_observation_failure import contextual_failure, verdict_evidence

        raise contextual_failure(error, observed_semantics=verdict_evidence(response)) from error
    return Observation(
        launcher.harness,
        launcher.event,
        "1k" if launcher.event == "PostToolUse" else "small",
        elapsed_ms,
        "pending_batch_validation",
        case == "benign",
        False,
    )


def _route_snapshot(session: LauncherSession, *, expected: int | None = None) -> Mapping[str, int]:
    metrics = session.daemon._server.hook_worker.metrics
    snapshot = metrics.snapshot() if expected is None else wait_for_route_corpus(metrics, expected=expected)
    return route_counts(snapshot)


def _require_native_count(before: Mapping[str, int], after: Mapping[str, int], count: int) -> None:
    deltas = {route: after.get(route, 0) - before.get(route, 0) for route in set(before) | set(after)}
    if {route: number for route, number in deltas.items() if number} != {"native_resident": count}:
        raise RuntimeError("priority_launcher_native_route_mismatch")


def _serial_series(session: LauncherSession, launcher: RegisteredLauncher, count: int, *, offset: int) -> list[float]:
    if registered_launcher(launcher.config_path, launcher.harness, launcher.event) != launcher:
        raise RuntimeError("priority_launcher_registration_changed")
    values: list[float] = []
    before = _route_snapshot(session)
    for index in range(count):
        observation = observe_priority_launcher(session, launcher, sample=offset + index)
        values.append(observation.latency_ms)
    after = _route_snapshot(session, expected=sum(before.values()) + count)
    _require_native_count(before, after, count)
    return values


def _concurrent_series(session: LauncherSession, launcher: RegisteredLauncher, count: int) -> list[float]:
    if registered_launcher(launcher.config_path, launcher.harness, launcher.event) != launcher:
        raise RuntimeError("priority_launcher_registration_changed")
    rounded = ((count + _CONCURRENCY - 1) // _CONCURRENCY) * _CONCURRENCY
    values: list[float] = []
    executor = ThreadPoolExecutor(max_workers=_CONCURRENCY, thread_name_prefix="priority-launcher")
    try:
        for offset in range(0, rounded, _CONCURRENCY):
            barrier = threading.Barrier(_CONCURRENCY + 1)
            stop = threading.Event()

            def launch(sample: int, launch_barrier: threading.Barrier, launch_stop: threading.Event) -> Observation:
                launch_barrier.wait(timeout=_LAUNCH_TIMEOUT_SECONDS)
                return observe_priority_launcher(session, launcher, sample=sample, stop_event=launch_stop)

            before = _route_snapshot(session)
            futures = [
                executor.submit(launch, 1_000_000 + offset + slot, barrier, stop) for slot in range(_CONCURRENCY)
            ]
            try:
                barrier.wait(timeout=_LAUNCH_TIMEOUT_SECONDS)
                observations = [future.result() for future in as_completed(futures, timeout=30.0)]
            except BaseException:
                stop.set()
                barrier.abort()
                for future in futures:
                    future.cancel()
                raise
            after = _route_snapshot(session, expected=sum(before.values()) + len(observations))
            attributed, routes = validate_batch_routes(observations, before, after)
            if routes != {"native_resident": _CONCURRENCY}:
                raise RuntimeError("priority_launcher_concurrent_route_mismatch")
            values.extend(observation.latency_ms for observation in attributed)
    except BaseException:
        executor.shutdown(wait=False, cancel_futures=True)
        raise
    else:
        executor.shutdown(wait=True)
    return values


def _sample_count(plan: Mapping[str, int], key: str) -> int:
    value = plan.get(key)
    if type(value) is not int or not 1 <= value <= _MAX_SAMPLES_PER_SERIES:
        raise ValueError("priority_launcher_sample_count_invalid")
    return value


def measure_priority_launchers(
    session: LauncherSession, plan: Mapping[str, int]
) -> tuple[dict[str, object], dict[str, list[float]]]:
    """Measure four actual registrations at c1, c16 and fresh-launcher startup.

    ``cold_per_run=20`` across five qualification blocks gives 100 fresh launcher
    processes per route. The resident remains prepared; these samples do not
    claim cold resident/bootstrap or cold OS file-cache latency.
    """

    priority_count = _sample_count(plan, "priority_per_run")
    cold_count = _sample_count(plan, "cold_per_run")
    launchers = install_priority_launchers(session)
    raw: dict[str, list[float]] = {}
    reports: list[dict[str, object]] = []
    for launcher in launchers:
        # Installation can publish a new config generation. The caller's
        # prepared policy must remain current; a fallback in this preflight
        # fails the route oracle rather than being included in warm samples.
        before = _route_snapshot(session)
        for case in ("benign", "block"):
            observe_priority_launcher(session, launcher, sample=-1, case=case)
        after = _route_snapshot(session, expected=sum(before.values()) + 2)
        _require_native_count(before, after, 2)
        name = f"{launcher.harness}.{launcher.event}"
        cold = _serial_series(session, launcher, cold_count, offset=2_000_000)
        serial = _serial_series(session, launcher, priority_count, offset=0)
        concurrent = _concurrent_series(session, launcher, priority_count)
        if registered_launcher(launcher.config_path, launcher.harness, launcher.event) != launcher:
            raise RuntimeError("priority_launcher_registration_changed")
        raw[f"INSTALLED_LAUNCHER.{name}"] = serial
        raw[f"INSTALLED_LAUNCHER.c16.{name}"] = concurrent
        raw[f"INSTALLED_LAUNCHER.cold.{name}"] = cold
        reports.append(
            {
                "harness": launcher.harness,
                "event": launcher.event,
                "registration_sha256": launcher.registration_sha256,
                "configuration": "registered_argv_and_env",
                "cases_validated": ["benign", "block"],
                "serial": summarize(serial),
                "c16": summarize(concurrent),
                "cold_launcher": summarize(cold),
                "route_attribution": "isolated_batch_counter_conservation",
            }
        )
    return {
        "boundary": "INSTALLED_LAUNCHER",
        "routes": reports,
        "contracts_passed": True,
        "process_startup_included": True,
        "stdout_and_exit_checked": True,
        "cold_state": "fresh_launcher_process_resident_prepared",
        "resident_cold_measured": False,
        "concurrency": [1, _CONCURRENCY],
        "policy_fixture": "explicit_allow_acknowledged",
        "qualification_complete": False,
    }, raw


__all__ = [
    "LauncherSession",
    "RegisteredLauncher",
    "install_priority_launchers",
    "launcher_payload",
    "measure_priority_launchers",
    "observe_priority_launcher",
    "registered_launcher",
    "validate_launcher_stdout",
]

"""Sampling, paired block ordering and confidence intervals for qualification."""

from __future__ import annotations

import math
import random
import statistics
from collections.abc import Mapping, Sequence

from scripts.native_slo_contract import percentile, summarize

QUALIFICATION_RUNS = 5
PRIORITY_SAMPLES = 10_000
OTHER_SAMPLES = 1_000
COLD_SAMPLES = 100
RECOVERY_SAMPLES = 100
RESOURCE_SAMPLES = 30
_BOOTSTRAPS = 2000


def paired_order(run: int) -> tuple[str, str]:
    return ("baseline", "candidate") if run % 2 == 0 else ("candidate", "baseline")


def sampling_plan(*, runs: int, qualification: bool) -> dict[str, int]:
    if runs < (QUALIFICATION_RUNS if qualification else 1) or runs > 20:
        raise ValueError("run count outside sampling contract")
    return {
        "runs": runs,
        "priority_per_run": math.ceil(PRIORITY_SAMPLES / runs) if qualification else 2,
        "other_per_run": math.ceil(OTHER_SAMPLES / runs) if qualification else 2,
        "cold_per_run": math.ceil(COLD_SAMPLES / runs) if qualification else 2,
        "recovery_per_run": math.ceil(RECOVERY_SAMPLES / runs) if qualification else 2,
        "resource_samples_per_run": RESOURCE_SAMPLES if qualification else 2,
    }


def confidence_summary(values: Sequence[float]) -> dict[str, object]:
    """Nearest-rank quantiles with reproducible empirical-bootstrap intervals.

    The kth order statistic of n uniform draws has a Beta(k,n+1-k)
    distribution. Mapping those draws through the empirical CDF is equivalent
    to resampling n observations and taking their nearest-rank quantile, without
    allocating and sorting n observations for every bootstrap replication.
    These intervals describe within-run variation. Independent-run comparisons
    use paired blocks separately, rather than treating all requests as IID.
    """

    result: dict[str, object] = dict(summarize(values))
    if not values:
        return result
    ordered = sorted(values)
    generator = random.Random(0)
    for quantile, label in ((0.95, "p95"), (0.99, "p99")):
        rank = math.ceil(len(ordered) * quantile)
        samples = [
            ordered[min(len(ordered) - 1, int(len(ordered) * generator.betavariate(rank, len(ordered) + 1 - rank)))]
            for _ in range(_BOOTSTRAPS)
        ]
        result[f"{label}_ci95_ms"] = [round(percentile(samples, 0.025), 3), round(percentile(samples, 0.975), 3)]
    result["interval_method"] = "empirical_percentile_bootstrap_nearest_rank_2000"
    return result


def paired_ratio_interval(baseline: Sequence[float], candidate: Sequence[float]) -> dict[str, object]:
    """Bootstrap paired run-level ratios; preserve environmental block pairing."""

    if len(baseline) != len(candidate) or not baseline:
        raise ValueError("comparison requires matched baseline and candidate blocks")
    if any(not math.isfinite(value) or value <= 0 for value in [*baseline, *candidate]):
        raise ValueError("comparison measurements must be positive finite values")
    ratios = [right / left for left, right in zip(baseline, candidate, strict=True)]
    generator = random.Random(0)
    estimates = [statistics.median(generator.choices(ratios, k=len(ratios))) for _ in range(_BOOTSTRAPS)]
    return {
        "runs": len(ratios),
        "median_ratio": round(statistics.median(ratios), 6),
        "ci95_low": round(percentile(estimates, 0.025), 6),
        "ci95_high": round(percentile(estimates, 0.975), 6),
        "interval_method": "paired_run_block_bootstrap_2000",
        "minimum_runs_met": len(ratios) >= QUALIFICATION_RUNS,
    }


def compare_routes(
    baseline: Sequence[Mapping[str, object]], candidate: Sequence[Mapping[str, object]]
) -> dict[str, object]:
    """Compare each identical route boundary independently; never pool harnesses."""

    if len(baseline) != len(candidate) or not baseline:
        raise ValueError("comparison requires matched blocks")
    route_sets = [set(report) for report in [*baseline, *candidate]]
    if any(routes != route_sets[0] for routes in route_sets):
        raise ValueError("baseline and candidate route coverage differs")
    result: dict[str, object] = {}
    for route in sorted(route_sets[0]):
        left = [report[route] for report in baseline]
        right = [report[route] for report in candidate]
        if any(not isinstance(summary, Mapping) for summary in [*left, *right]):
            raise ValueError("invalid route measurements")
        result[route] = {
            "baseline_samples": sum(int(summary["count"]) for summary in left),
            "candidate_samples": sum(int(summary["count"]) for summary in right),
            "p95": paired_ratio_interval(
                [float(summary["p95_ms"]) for summary in left], [float(summary["p95_ms"]) for summary in right]
            ),
            "p99": paired_ratio_interval(
                [float(summary["p99_ms"]) for summary in left], [float(summary["p99_ms"]) for summary in right]
            ),
        }
    return result


def sampling_gates(comparison: Mapping[str, object], *, runs: int) -> dict[str, bool]:
    """Validate observed counts, not just the requested iteration arguments."""
    gates = {"independent_runs": runs >= QUALIFICATION_RUNS}
    for route, measurement in comparison.items():
        if not isinstance(measurement, Mapping):
            raise ValueError("invalid comparison measurement")
        if route in {
            "NATIVE_CLIENT.cold_oneshot",
            "NATIVE_CLIENT.policy_readiness",
            "DAEMON_PROCESS.startup",
        } or route.startswith("INSTALLED_LAUNCHER.cold."):
            minimum = COLD_SAMPLES
        elif route == "DAEMON_INGRESS.recovery":
            minimum = RECOVERY_SAMPLES
        elif route.startswith("INSTALLED_LAUNCHER.") or ".claude-code." in route or ".codex." in route:
            minimum = PRIORITY_SAMPLES
        else:
            minimum = OTHER_SAMPLES
        gates[route] = all(int(measurement.get(f"{arm}_samples", 0)) >= minimum for arm in ("baseline", "candidate"))
    return gates

"""Read actual nonpriority hook registrations before starting their processes.

These readers consume the installed adapter files. They never reconstruct a
Guard CLI invocation or substitute an HTTP request for a registered command.
Only private qualification homes are supported; third-party hook chains are
rejected rather than silently omitted from the execution boundary.
"""

from __future__ import annotations

import hashlib
import importlib
import json
import os
import shlex
import subprocess
import sys
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import cast

from codex_plugin_scanner.guard.adapters.base import HarnessContext
from codex_plugin_scanner.guard.adapters.cline import ClineHarnessAdapter
from codex_plugin_scanner.guard.adapters.cline_state_paths import canonical_cline_state_path, cline_hook_command
from codex_plugin_scanner.guard.adapters.copilot import CopilotHarnessAdapter
from codex_plugin_scanner.guard.adapters.cursor_hooks import cursor_hooks_path, install_cursor_hooks
from codex_plugin_scanner.guard.adapters.grok import GrokHarnessAdapter
from codex_plugin_scanner.guard.adapters.kimi import KimiHarnessAdapter
from codex_plugin_scanner.guard.adapters.zcode import ZCodeHarnessAdapter
from codex_plugin_scanner.guard.config import resolve_guard_home_for_user_home
from codex_plugin_scanner.guard.windows_paths import windows_command_line_to_argv

CONFIG_LIMIT = 1_000_000
SURFACE_EVENTS = {
    "cursor": (
        "beforeShellExecution",
        "beforeMCPExecution",
        "beforeReadFile",
        "beforeWriteFile",
        "afterShellExecution",
        "afterMCPExecution",
    ),
    "copilot": ("preToolUse", "postToolUse"),
    "kimi": ("PreToolUse", "PostToolUse"),
    "grok": ("PreToolUse",),
    "zcode": ("PreToolUse",),
    "cline": ("PreToolUse", "PostToolUse"),
}
_ZCODE_MATCHERS = (
    "Bash",
    "Read",
    "Write",
    "Edit",
    "MultiEdit",
    "Grep",
    "WebFetch",
    "WebSearch",
    "mcp__.*",
    "run_terminal_command",
    "run_command",
    "read_file",
    "write_file",
    "search_replace",
    "multi_edit",
    "grep",
    "web_fetch",
    "web_search",
)
_TOML = importlib.import_module("tomllib" if sys.version_info >= (3, 11) else "tomli")


class SurfaceUnavailableError(RuntimeError):
    """An explicit installed-path limitation, never a successful observation."""


@dataclass(frozen=True, slots=True)
class RegisteredSurface:
    harness: str
    event: str
    scope: str
    argv: tuple[str, ...]
    environment: tuple[tuple[str, str], ...]
    cwd: Path
    config_path: Path
    registration_sha256: str
    matchers: tuple[str, ...] = ()
    artifact_sha256: tuple[tuple[str, str], ...] = ()


def _bytes(path: Path) -> bytes:
    with path.open("rb") as stream:
        raw = stream.read(CONFIG_LIMIT + 1)
    if len(raw) > CONFIG_LIMIT:
        raise RuntimeError("registered_surface_configuration_limit")
    return raw


def _mapping(value: object) -> Mapping[str, object]:
    if not isinstance(value, Mapping) or any(not isinstance(key, str) for key in value):
        raise RuntimeError("registered_surface_configuration_invalid")
    return cast(Mapping[str, object], value)


def _read(path: Path) -> Mapping[str, object]:
    raw = _bytes(path)
    try:
        return _mapping(_TOML.loads(raw.decode("utf-8")) if path.suffix == ".toml" else json.loads(raw))
    except (UnicodeDecodeError, ValueError) as error:
        raise RuntimeError("registered_surface_configuration_invalid") from error


def _entries(value: object) -> list[Mapping[str, object]]:
    if not isinstance(value, list) or not value:
        raise RuntimeError("registered_surface_registration_missing")
    result = [_mapping(item) for item in value]
    if any(item.get("enabled", True) is not True for item in result):
        raise RuntimeError("registered_surface_registration_disabled")
    return result


def _command(value: object, *, windows: bool, zcode: bool = False) -> tuple[str, ...]:
    if not isinstance(value, str) or not value or "\x00" in value:
        raise RuntimeError("registered_surface_command_invalid")
    if zcode:
        marker = " # HOL_GUARD_MANAGED_ZCODE"
        if not value.endswith(marker):
            raise RuntimeError("registered_surface_zcode_marker_missing")
        if windows:
            # list2cmdline does not make '#' a cmd.exe comment. Do not silently
            # strip arguments and pretend that the host ran this registration.
            raise SurfaceUnavailableError("zcode_windows_shell_comment_unqualified")
        value = value[: -len(marker)]
    if windows:
        parsed = windows_command_line_to_argv(value)
        if not parsed:
            raise SurfaceUnavailableError("windows_command_line_parser_unavailable")
        canonical = subprocess.list2cmdline(parsed)
    else:
        try:
            parsed = shlex.split(value, posix=True)
        except ValueError as error:
            raise RuntimeError("registered_surface_command_invalid") from error
        canonical = shlex.join(parsed)
    if not parsed or canonical != value or any("\x00" in argument for argument in parsed):
        raise RuntimeError("registered_surface_command_not_lossless")
    if not Path(parsed[0]).is_absolute():
        raise RuntimeError("registered_surface_executable_not_absolute")
    return tuple(parsed)


def _bridge(argv: tuple[str, ...], harness: str, context: HarnessContext) -> None:
    if len(argv) != 5 or argv[1:3] != ("-I", "-c"):
        raise SurfaceUnavailableError("registered_surface_non_python_bridge_unqualified")
    if "codex_plugin_scanner.guard.adapters.bounded_cli_hook_bridge import main_from_argv" not in argv[3]:
        raise RuntimeError("registered_surface_unmanaged_handler")
    try:
        config = _mapping(json.loads(argv[4]))
    except ValueError as error:
        raise RuntimeError("registered_surface_bridge_invalid") from error
    if config.get("harness") != harness or config.get("guard_home") != str(context.guard_home.resolve()):
        raise RuntimeError("registered_surface_bridge_context_mismatch")


def _environment(handler: Mapping[str, object]) -> tuple[tuple[str, str], ...]:
    value = _mapping(handler.get("env", {}))
    if any(not isinstance(item, str) for item in value.values()):
        raise RuntimeError("registered_surface_environment_invalid")
    return tuple(sorted(cast(Mapping[str, str], value).items()))


def _registered(
    context: HarnessContext,
    harness: str,
    event: str,
    scope: str,
    path: Path,
) -> RegisteredSurface:
    config = _read(path)
    hooks = config.get("hooks")
    matchers: tuple[str, ...] = ()
    if harness == "kimi":
        handlers = [item for item in _entries(hooks) if item.get("event") == event]
    else:
        hooks = _mapping(hooks)
        if harness == "zcode":
            hooks = _mapping(hooks.get("events"))
        groups = _entries(hooks.get(event))
        if harness in {"grok", "zcode"}:
            if harness == "zcode":
                raw_matchers = tuple(group.get("matcher") for group in groups)
                if len(raw_matchers) != len(_ZCODE_MATCHERS) or set(raw_matchers) != set(_ZCODE_MATCHERS):
                    raise RuntimeError("registered_surface_zcode_matchers_mismatch")
                matchers = cast(tuple[str, ...], raw_matchers)
            elif any(group.get("matcher") for group in groups):
                raise RuntimeError("registered_surface_grok_not_catchall")
            handlers = [handler for group in groups for handler in _entries(group.get("hooks"))]
        else:
            handlers = groups
    if len(handlers) != (len(_ZCODE_MATCHERS) if harness == "zcode" else 1):
        raise RuntimeError("registered_surface_registration_ambiguous")
    variants: list[tuple[tuple[str, ...], tuple[tuple[str, str], ...], Path]] = []
    for handler in handlers:
        if harness not in {"cursor", "kimi"} and handler.get("type") != "command":
            raise RuntimeError("registered_surface_handler_not_command")
        if harness == "cursor" and handler.get("failClosed") is not event.startswith("before"):
            raise RuntimeError("registered_surface_cursor_fail_closed_mismatch")
        key = ("powershell" if os.name == "nt" else "bash") if harness == "copilot" else "command"
        argv = _command(handler.get(key), windows=os.name == "nt" and harness != "cursor", zcode=harness == "zcode")
        if harness == "cursor":
            if len(argv) != 4 or Path(argv[1]) != context.home_dir / ".cursor/hooks/hol-guard-cursor-hook.py":
                raise RuntimeError("registered_surface_cursor_script_mismatch")
            if argv[-2:] != ("--cursor-hook-event", event):
                raise RuntimeError("registered_surface_cursor_event_mismatch")
        else:
            _bridge(argv, harness, context)
        cwd_value = handler.get("cwd", str(context.workspace_dir or context.home_dir))
        if not isinstance(cwd_value, str) or not Path(cwd_value).is_absolute():
            raise RuntimeError("registered_surface_cwd_invalid")
        variants.append((argv, _environment(handler), Path(cwd_value)))
    if len(set(variants)) != 1:
        raise RuntimeError("registered_surface_registration_ambiguous")
    argv, environment, cwd = variants[0]
    artifacts = ()
    if harness == "cursor":
        artifacts = (("cursor_worker", hashlib.sha256(_bytes(Path(argv[1]))).hexdigest()),)
    return RegisteredSurface(
        harness,
        event,
        scope,
        argv,
        environment,
        cwd,
        path,
        hashlib.sha256(_bytes(path)).hexdigest(),
        matchers,
        artifacts,
    )


def _cline(context: HarnessContext, event: str) -> RegisteredSurface:
    path = context.guard_home / "managed/cline/native-hooks-state.json"
    state = _read(path)
    active = _read(context.guard_home / "managed/cline/adapter-state.json")
    if active.get("active_transport") != "hooks" or state.get("transport") != "hooks":
        raise RuntimeError("registered_surface_cline_inactive")
    artifacts: list[tuple[str, str]] = []
    slot = None
    for group, digest_group, worker in (("paths", "sha256", False), ("workers", "worker_sha256", True)):
        target = canonical_cline_state_path(
            context,
            event,
            _mapping(state.get(group)).get(event),
            worker=worker,
            saved_root=state.get("root"),
        )
        if target is None:
            raise RuntimeError("registered_surface_cline_path_invalid")
        digest = hashlib.sha256(_bytes(target)).hexdigest()
        if digest != _mapping(state.get(digest_group)).get(event):
            raise RuntimeError("registered_surface_cline_artifact_changed")
        artifacts.append((group, digest))
        if not worker:
            slot = target
    assert slot is not None
    argv = tuple(cline_hook_command(slot))
    if not argv:
        raise SurfaceUnavailableError("cline_trusted_interpreter_unavailable")
    return RegisteredSurface(
        "cline",
        event,
        "global",
        argv,
        (),
        context.workspace_dir or context.home_dir,
        path,
        hashlib.sha256(_bytes(path)).hexdigest(),
        artifact_sha256=tuple(artifacts),
    )


def read_registered_surfaces(context: HarnessContext, harness: str) -> tuple[RegisteredSurface, ...]:
    if harness not in SURFACE_EVENTS:
        raise ValueError("registered_surface_harness_unsupported")
    if harness == "cline":
        return tuple(_cline(context, event) for event in SURFACE_EVENTS[harness])
    if harness == "cursor":
        paths = (("global", cursor_hooks_path(context)),)
    elif harness == "copilot":
        paths = (("global", CopilotHarnessAdapter._config_path(context)),)
        project = CopilotHarnessAdapter._hook_path(context)
        if project is not None:
            paths += (("project", project),)
    elif harness == "kimi":
        paths = (("global", KimiHarnessAdapter()._managed_config_path(context)),)
    elif harness == "grok":
        paths = (("global", GrokHarnessAdapter._hooks_dir(context) / "hol-guard-pretooluse.json"),)
    else:
        paths = (("global", ZCodeHarnessAdapter._config_path(context)),)
    return tuple(
        _registered(context, harness, event, scope, path) for scope, path in paths for event in SURFACE_EVENTS[harness]
    )


def install_registered_surface(context: HarnessContext, harness: str) -> tuple[RegisteredSurface, ...]:
    """Use the shipped installer, then read exact commands from its live files."""
    if harness not in SURFACE_EVENTS:
        raise ValueError("registered_surface_harness_unsupported")
    for name in ("KIMI_CODE_HOME", "GROK_HOME", "ZCODE_HOME", "CLINE_DATA_DIR", "CLINE_DIR"):
        if os.environ.get(name):
            raise SurfaceUnavailableError("registered_surface_ambient_home_override")
    if harness == "cline":
        if context.guard_home != resolve_guard_home_for_user_home(context.home_dir):
            raise SurfaceUnavailableError("cline_requires_default_guard_home")
        ClineHarnessAdapter().install(context, surface="hooks")
    elif harness == "cursor":
        install_cursor_hooks(context)
    else:
        adapters = {
            "copilot": CopilotHarnessAdapter,
            "kimi": KimiHarnessAdapter,
            "grok": GrokHarnessAdapter,
            "zcode": ZCodeHarnessAdapter,
        }
        adapters[harness]().install(context)
    return read_registered_surfaces(context, harness)

"""Bounded process-tree diagnostics, outside the timed response boundary."""

from __future__ import annotations

import os
import sys
import threading
import time
from collections import Counter
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

_MAX_PROCESSES = 4096
_METRICS = ("rss_bytes", "private_bytes", "cpu_seconds", "processes", "threads", "descriptors", "handles")


def _psutil() -> Any:
    try:
        import psutil
    except ImportError as error:
        raise RuntimeError("qualification resources require the pinned psutil development dependency") from error
    return psutil


@dataclass(frozen=True)
class TreeResources:
    rss_bytes: int | None
    private_bytes: int | None
    cpu_seconds: float | None
    processes: int
    threads: int | None
    descriptors: int | None
    handles: int | None = None
    unavailable: dict[str, str] = field(default_factory=dict)
    # Private collector state. Never emit process identifiers into public evidence.
    process_cpu: dict[tuple[int, float], float] = field(default_factory=dict, repr=False)
    cpu_includes_reaped: bool = False


def _stat(pid: int, proc: Path) -> tuple[int, int, int]:
    fields = (proc / str(pid) / "stat").read_text().rsplit(")", 1)[1].split()
    return int(fields[1]), int(fields[19]), sum(int(fields[index]) for index in (11, 12, 13, 14))


def _identity(process: Any) -> tuple[int, float]:
    return process.pid, process.create_time()


def _inventory(root: Any) -> dict[tuple[int, float], Any]:
    children = root.children(recursive=True)
    if len(children) >= _MAX_PROCESSES:
        raise ValueError("process tree exceeded measurement bound")
    return {_identity(process): process for process in (root, *children)}


def sample_process_tree(pid: int | None = None, *, proc: Path = Path("/proc")) -> TreeResources | None:
    """Collect available metrics separately; denied USS is not zero memory.

    PID and creation time are checked before and after enumeration. Linux CPU
    includes live processes and their waited-for children via /proc. Elsewhere
    the sampler retains CPU for observed processes that later exit; very short
    descendants that exit between polls are explicitly outside that coverage.
    """
    psutil = _psutil()
    process_id = os.getpid() if pid is None else pid
    for _ in range(2):
        try:
            root = psutil.Process(process_id)
            before = _inventory(root)
            unavailable: dict[str, str] = {}
            totals: dict[str, int | float] = {name: 0 for name in _METRICS}
            process_cpu: dict[tuple[int, float], float] = {}

            def read(
                metric: str,
                operation: Callable[[], int | float],
                totals: dict[str, int | float] = totals,
                unavailable: dict[str, str] = unavailable,
            ) -> None:
                try:
                    totals[metric] += operation()
                except psutil.AccessDenied:
                    unavailable[metric] = "permission_denied"
                except (AttributeError, NotImplementedError):
                    unavailable[metric] = "platform_unsupported"
                except (OSError, ValueError):
                    unavailable[metric] = "metric_unavailable"

            for identity, process in before.items():
                read("rss_bytes", lambda process=process: process.memory_info().rss)
                read("private_bytes", lambda process=process: process.memory_full_info().uss)
                read("threads", process.num_threads)
                if sys.platform == "win32":
                    read("handles", process.num_handles)
                    unavailable["descriptors"] = "platform_unsupported"
                else:
                    read("descriptors", process.num_fds)
                    unavailable["handles"] = "platform_unsupported"
                try:
                    cpu = process.cpu_times()
                    process_cpu[identity] = cpu.user + cpu.system
                except psutil.AccessDenied:
                    unavailable["cpu_seconds"] = "permission_denied"
            cpu_includes_reaped = False
            if sys.platform.startswith("linux"):
                # utime/stime + cutime/cstime include reaped children without
                # counting live descendants twice. Validate process identities
                # again before accepting this inventory and these counters.
                ticks = sum(_stat(identity[0], proc)[2] for identity in before)
                totals["cpu_seconds"] = ticks / os.sysconf("SC_CLK_TCK")
                cpu_includes_reaped = True
            else:
                totals["cpu_seconds"] = sum(process_cpu.values())
            if set(_inventory(psutil.Process(process_id))) != set(before):
                continue
            return TreeResources(
                rss_bytes=None if "rss_bytes" in unavailable else int(totals["rss_bytes"]),
                private_bytes=None if "private_bytes" in unavailable else int(totals["private_bytes"]),
                cpu_seconds=None if "cpu_seconds" in unavailable else float(totals["cpu_seconds"]),
                processes=len(before),
                threads=None if "threads" in unavailable else int(totals["threads"]),
                descriptors=None if "descriptors" in unavailable else int(totals["descriptors"]),
                handles=None if "handles" in unavailable else int(totals["handles"]),
                unavailable=unavailable,
                process_cpu=process_cpu,
                cpu_includes_reaped=cpu_includes_reaped,
            )
        except (psutil.NoSuchProcess, psutil.AccessDenied, OSError, ValueError, IndexError):
            continue
    return None


class ResourceSampler:
    """Retain bounded aggregates and observed descendant CPU, never process data."""

    def __init__(self, *, interval_seconds: float = 0.1, pid: int | None = None) -> None:
        _psutil()  # A missing dependency is a setup error, not an unsupported OS.
        if not 0.01 <= interval_seconds <= 1.0:
            raise ValueError("resource sample interval out of bounds")
        self.interval = interval_seconds
        self.pid = os.getpid() if pid is None else pid
        self._stop = threading.Event()
        self._thread: threading.Thread | None = None
        self.samples = 0
        self.missing = 0
        self.first: TreeResources | None = None
        self.last: TreeResources | None = None
        self.peaks: dict[str, int | float] = {}
        self.metric_samples: Counter[str] = Counter()
        self.unavailable: dict[str, Counter[str]] = {}
        self._observed_cpu: dict[tuple[int, float], float] = {}
        self._initial_cpu = 0.0
        self.started = 0.0
        self.stopped = 0.0

    def _sample(self) -> None:
        value = sample_process_tree(self.pid)
        if value is None:
            self.missing += 1
            return
        self.samples += 1
        if self.first is None:
            self.first = value
            self._initial_cpu = sum(value.process_cpu.values())
        self.last = value
        for name in _METRICS:
            number = getattr(value, name)
            if number is not None:
                self.metric_samples[name] += 1
                self.peaks[name] = max(self.peaks.get(name, 0), number)
        for name, reason in value.unavailable.items():
            self.unavailable.setdefault(name, Counter())[reason] += 1
        for identity, cpu in value.process_cpu.items():
            if len(self._observed_cpu) >= _MAX_PROCESSES and identity not in self._observed_cpu:
                self.unavailable.setdefault("cpu_seconds", Counter())["process_history_bound"] += 1
                continue
            self._observed_cpu[identity] = max(self._observed_cpu.get(identity, 0.0), cpu)

    def _run(self) -> None:
        while not self._stop.wait(self.interval):
            self._sample()

    def __enter__(self) -> ResourceSampler:
        self.started = time.monotonic()
        self._sample()
        self._thread = threading.Thread(target=self._run, daemon=True, name="native-slo-resources")
        self._thread.start()
        return self

    def __exit__(self, *_args: object) -> None:
        self._stop.set()
        if self._thread is not None:
            self._thread.join(timeout=2.0)
            if self._thread.is_alive():
                raise RuntimeError("resource sampler exceeded shutdown deadline")
        self._sample()
        self.stopped = time.monotonic()

    def report(self, *, attempted: int) -> dict[str, object]:
        elapsed = max(0.0, (self.stopped or time.monotonic()) - self.started)
        cpu = None
        reaped = self.first is not None and self.last is not None and self.last.cpu_includes_reaped
        if self.first is not None and self.last is not None and "cpu_seconds" not in self.unavailable:
            if reaped and self.first.cpu_seconds is not None and self.last.cpu_seconds is not None:
                difference = self.last.cpu_seconds - self.first.cpu_seconds
            else:
                difference = sum(self._observed_cpu.values()) - self._initial_cpu
            if difference >= 0:
                cpu = difference
        required = ("rss_bytes", "private_bytes", "cpu_seconds", "processes", "threads")
        required += ("handles",) if sys.platform == "win32" else ("descriptors",)
        per_metric = {
            name: self.metric_samples[name] >= 30 and name not in self.unavailable and self.missing == 0
            for name in required
        }
        return {
            "scope": "daemon_fixture_process_tree" if self.pid != os.getpid() else "load_generator_process_tree",
            "collector": "psutil_with_linux_proc_cpu" if reaped else "psutil_observed_descendants",
            "samples": self.samples,
            "unavailable_samples": self.missing,
            "metric_samples": dict(self.metric_samples),
            "unavailable_metrics": {name: dict(reasons) for name, reasons in self.unavailable.items()},
            "metric_minimum_met": per_metric,
            "sample_minimum_met": all(per_metric.values()),
            "elapsed_seconds": round(elapsed, 6),
            "baseline": {name: getattr(self.first, name, None) for name in _METRICS if name != "cpu_seconds"},
            "peak": {name: self.peaks.get(name) for name in _METRICS if name != "cpu_seconds"},
            "rss_growth": ((self.peaks.get("rss_bytes", 0) / self.first.rss_bytes) - 1)
            if self.first is not None and self.first.rss_bytes
            else None,
            "cpu_seconds": cpu,
            "cpu_ms_per_attempt": round(cpu * 1000 / attempted, 6) if cpu is not None and attempted > 0 else None,
            "cpu_includes_reaped_descendants": reaped,
            "short_exited_descendants_cpu_complete": reaped,
            "includes_load_generator": self.pid == os.getpid(),
            "fixture_control_overhead_included": self.pid != os.getpid(),
        }

"""Bounded Linux process witnesses for the native diagnostic receiver.

This binds a live, explicitly owned fixture descendant at observation time.
It is diagnostic attribution, not a general concurrent-process attestation.
No command line, path, environment or credential bytes enter exported reports.
"""

from __future__ import annotations

import hashlib
import os
import stat
from dataclasses import dataclass
from pathlib import Path

from scripts.native_slo_rust_phase_schema import ROLES

MAX_PROCESS_DEPTH = 16
MAX_EXECUTABLE_BYTES = 128 * 1024 * 1024


@dataclass(frozen=True)
class ProcessIdentity:
    pid: int
    parent: int
    group: int
    session: int
    start_ticks: int


def _refuse() -> None:
    raise ValueError("native_phase_process_refused")


def _read_at(directory: int, name: str, bound: int) -> bytes:
    descriptor = os.open(name, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW, dir_fd=directory)
    try:
        chunks: list[bytes] = []
        remaining = bound + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        value = b"".join(chunks)
        if len(value) > bound:
            _refuse()
        return value
    finally:
        os.close(descriptor)


def parse_stat(value: bytes, expected_pid: int) -> ProcessIdentity:
    text = value.decode("utf-8")
    head, fields_text = text.rsplit(") ", 1)
    pid = int(head.split(" (", 1)[0])
    fields = fields_text.split()
    if pid != expected_pid or len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        _refuse()
    row = ProcessIdentity(pid, int(fields[1]), int(fields[2]), int(fields[3]), int(fields[19]))
    if row.pid <= 0 or row.parent < 0 or row.group <= 0 or row.session <= 0 or row.start_ticks <= 0:
        _refuse()
    return row


def _same_executable(metadata: os.stat_result) -> tuple[int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


class Executable:
    """Retain the exact caller-supplied binary descriptor and its source digest."""

    def __init__(self, path: Path) -> None:
        self.descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
        try:
            before = os.fstat(self.descriptor)
            if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= MAX_EXECUTABLE_BYTES:
                _refuse()
            digest = hashlib.sha256()
            count = 0
            while True:
                chunk = os.read(self.descriptor, min(65536, MAX_EXECUTABLE_BYTES + 1 - count))
                if not chunk:
                    break
                count += len(chunk)
                digest.update(chunk)
                if count > MAX_EXECUTABLE_BYTES:
                    _refuse()
            self.identity = _same_executable(before)
            if count != before.st_size or _same_executable(os.fstat(self.descriptor)) != self.identity:
                _refuse()
            self.sha256 = digest.hexdigest()
        except BaseException:
            os.close(self.descriptor)
            self.descriptor = -1
            raise

    def current(self) -> bool:
        return self.descriptor >= 0 and _same_executable(os.fstat(self.descriptor)) == self.identity

    def close(self) -> None:
        if self.descriptor >= 0:
            os.close(self.descriptor)
            self.descriptor = -1


def read_process(pid: int, executable: Executable | None = None) -> tuple[ProcessIdentity, str | None]:
    if type(pid) is not int or not 1 <= pid <= 2**31 - 1:
        _refuse()
    directory = os.open(f"/proc/{pid}", os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        before = parse_stat(_read_at(directory, "stat", 4096), pid)
        status = _read_at(directory, "status", 65536).decode("ascii")
        uid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Uid:")]
        gid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Gid:")]
        if (
            len(uid_rows) != 1
            or len(gid_rows) != 1
            or uid_rows[0] != [str(os.geteuid())] * 4
            or gid_rows[0] != [str(os.getegid())] * 4
        ):
            _refuse()
        role = None
        if executable is not None:
            if not executable.current() or _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
                _refuse()
            command = _read_at(directory, "cmdline", 16384)
            parts = command.split(b"\0")
            if len(parts) < 3 or parts[-1] != b"":
                _refuse()
            role = ROLES.get(parts[1].decode("ascii"))
            if role is None:
                _refuse()
        after = parse_stat(_read_at(directory, "stat", 4096), pid)
        if before != after:
            _refuse()
        if executable is not None and _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
            _refuse()
        return before, role
    finally:
        os.close(directory)


class OwnedCohort:
    def __init__(self, fixture_pid: int, executable: Executable) -> None:
        root, _ = read_process(fixture_pid)
        if root.parent != os.getpid() or root.session != root.pid or root.group != root.pid:
            _refuse()
        self.root = root
        self.executable = executable
        self.seen: dict[int, tuple[int, str]] = {}

    def admit(self, pid: int, start_ticks: int, role: str) -> ProcessIdentity:
        sender, actual_role = read_process(pid, self.executable)
        if sender.start_ticks != start_ticks or actual_role != role:
            _refuse()
        if pid in self.seen and self.seen[pid] != (start_ticks, role):
            _refuse()
        if pid not in self.seen and len(self.seen) >= 16:
            _refuse()
        chain = [sender]
        for _ in range(MAX_PROCESS_DEPTH):
            current = chain[-1]
            if current.pid == self.root.pid:
                break
            if current.parent <= 1 or any(row.pid == current.parent for row in chain):
                _refuse()
            parent, _ = read_process(current.parent)
            if parent.start_ticks > current.start_ticks:
                _refuse()
            chain.append(parent)
        if chain[-1] != self.root:
            _refuse()
        # Re-read each exact process generation after walking the ancestry.
        # Any exit, reparenting or reuse makes this observation unavailable.
        for original in reversed(chain):
            current, _ = read_process(original.pid, self.executable if original.pid == sender.pid else None)
            if current != original:
                _refuse()
        self.seen[pid] = (start_ticks, role)
        return sender

"""Run the existing installed phase workload with optional Rust diagnostics.

The native binary must already be the exact installed runtime. This entry
point does not select an ingress, replace a binary, reuse a connection, alter a
deadline or extend native shutdown. All samples are diagnostic and incomplete.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any, cast

_ROOT = Path(__file__).resolve().parents[1]
if str(_ROOT) not in sys.path:
    sys.path.append(str(_ROOT))

from scripts.native_slo_daemon_fixture import DaemonFixture  # noqa: E402
from scripts.native_slo_phase_run import measure_installed_phases  # noqa: E402
from scripts.native_slo_rust_phase_receiver import NativePhaseReceiver, supported  # noqa: E402

_REQUIRED_PHASES = frozenset(
    {
        "client_connect_inclusive",
        "client_authenticate",
        "client_request_write_flush",
        "client_committed_response_read",
        "resident_evaluate_inclusive",
    }
)


def _observed_phases(native: dict[str, Any]) -> set[str]:
    return {
        phase["phase"]
        for process in native["processes"]
        if process["snapshot"] is not None
        for phase in process["snapshot"]["phases"]
        if phase["statistics"] is not None
    }


def measure_native_phases(runtime: Path, count: int, evidence_file: Path) -> dict[str, Any]:
    if type(count) is not int or not 1 <= count <= 100:
        raise ValueError("native_phase_count_outside_original_bound")
    result: dict[str, Any] = {
        "schema": "hol-guard-native-and-python-phase-run.v1",
        "scope": "diagnostic_instrumented_existing_installed_workload",
        "headline_timing_eligible": False,
        "qualification_complete": False,
        "complete_run": False,
        "status": "platform_unsupported",
        "workload_passed": False,
        "workload_failure_observed": False,
        "workload_started": False,
        "existing_fixture_failure_observed": False,
        "native_phase_error_observed": False,
        "original_phase_count_bound": 100,
        "requested_count_per_case": count,
        "original_semantic_workload": None,
        "native": None,
    }
    if not supported():
        return result
    receiver: NativePhaseReceiver | None = None
    try:
        receiver = NativePhaseReceiver(runtime)
    except Exception:
        result["native_phase_error_observed"] = True
    try:
        if receiver is not None:
            try:
                with DaemonFixture(
                    runtime, setup="normal", _native_phase_environment=receiver.environment()
                ) as session:
                    try:
                        receiver.attach(session.pid)
                    except Exception:
                        result["native_phase_error_observed"] = True
                    else:
                        result["workload_started"] = True
                        try:
                            result["original_semantic_workload"] = measure_installed_phases(
                                session, count, evidence_file
                            )
                            result["workload_passed"] = True
                        except Exception:
                            # The existing journal retains original failures;
                            # never export an exception or request value here.
                            result["workload_failure_observed"] = True
            except Exception:
                result["existing_fixture_failure_observed"] = True
    finally:
        if receiver is not None:
            try:
                receiver.close()
                result["native"] = receiver.report()
            except Exception:
                result["native_phase_error_observed"] = True
    native = cast(dict[str, Any] | None, result["native"])
    if result["existing_fixture_failure_observed"]:
        result["status"] = "existing_fixture_failed"
    elif result["workload_failure_observed"]:
        result["status"] = "workload_failed"
    elif not result["workload_started"]:
        result["status"] = "diagnostic_setup_failed"
    elif native is None or result["native_phase_error_observed"]:
        result["status"] = "diagnostic_incomplete"
    elif _REQUIRED_PHASES <= _observed_phases(native) and any(  # noqa: SIM300 - preserve operand evaluation order
        phase["phase"] in {"unix_socket_creation", "loopback_connect_handle"}
        and phase["statistics"] is not None
        and phase["statistics"]["returned_ok"] > 0
        for process in native["processes"]
        if process["snapshot"] is not None
        for phase in process["snapshot"]["phases"]
    ):
        result["status"] = "diagnostic_phases_observed"
    else:
        result["status"] = "diagnostic_incomplete"
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--runtime", type=Path, required=True)
    parser.add_argument("--count", type=int, default=1)
    parser.add_argument("--evidence-file", type=Path, required=True)
    parser.add_argument("--json", type=Path, required=True)
    arguments = parser.parse_args()
    report = measure_native_phases(arguments.runtime.resolve(strict=True), arguments.count, arguments.evidence_file)
    rendered = json.dumps(report, sort_keys=True, indent=2) + "\n"
    if len(rendered.encode("utf-8")) > 1024 * 1024:
        raise ValueError("native_phase_report_exceeded_bound")
    with arguments.json.open("x", encoding="utf-8") as output:
        output.write(rendered)
    print(
        json.dumps(
            {
                "schema": report["schema"],
                "status": report["status"],
                "headline_timing_eligible": False,
                "qualification_complete": False,
            },
            sort_keys=True,
        )
    )
    return 0 if report["status"] == "diagnostic_phases_observed" else 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Bounded verdict diagnostics for a failed synthetic qualification case.

Never copy reasons, response text or arbitrary values out of the private run.
Only closed verdict vocabularies and reason codes frozen in the corpus may be
exported; a digest records every other value without disclosing its content.
"""

from __future__ import annotations

import hashlib
import json
from collections.abc import Mapping, Sequence

from scripts.native_slo_workloads import QualificationCase

_ACTIONS = frozenset({"allow", "deny", "block", "review", "ask", "warn", "allow_original", "replace"})
_FIELDS = ("decision", "minimum_action", "policy_action", "model_output_action", "reason_code", "error")


def semantic_diagnostic(
    response: Mapping[str, object], native: object, cases: Sequence[QualificationCase]
) -> dict[str, object]:
    allowed_codes = {
        value
        for case in cases
        for expected in (case.expected, case.native_expected)
        if expected is not None
        for key, value in expected.fields.items()
        if key in {"reason_code", "error"} and isinstance(value, str)
    }
    result: dict[str, object] = {}
    for label, source in (("delivered", response), ("native", native)):
        if not isinstance(source, Mapping):
            result[label] = {"available": False}
            continue
        observed: dict[str, object] = {"available": True}
        for key in _FIELDS:
            if key not in source:
                continue
            value = source[key]
            allowed = allowed_codes if key in {"reason_code", "error"} else _ACTIONS
            if isinstance(value, str) and value in allowed:
                observed[key] = value
                if key in {"reason_code", "error"}:
                    # Some frozen codes contain sensitive vocabulary and the
                    # generic export sanitizer redacts their string. Retain an
                    # exact identifier without exposing arbitrary error text.
                    encoded = json.dumps(value, separators=(",", ":")).encode("utf-8")
                    observed[key + "_digest"] = hashlib.sha256(encoded).hexdigest()
            else:
                encoded = json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")
                observed[key + "_digest"] = hashlib.sha256(encoded).hexdigest()
        result[label] = observed
    return result

"""Descriptor-pinned extension admission and bounded runtime image identities."""

from __future__ import annotations

import contextlib
import hashlib
import os
import re
import stat
from pathlib import Path
from typing import Any

MAX_IMAGE_BYTES = 64 * 1024 * 1024


def _read_identity(descriptor: int, *, owned: bool) -> dict[str, Any]:
    before = os.fstat(descriptor)
    if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= MAX_IMAGE_BYTES:
        raise ValueError("runtime image must be a bounded regular file")
    if owned and (before.st_uid != os.getuid() or before.st_nlink != 1 or before.st_mode & 0o022):
        raise ValueError("extension must be an exclusively owned, non-writable-by-others image")
    digest = hashlib.sha256()
    count = 0
    while block := os.read(descriptor, 65_536):
        count += len(block)
        if count > MAX_IMAGE_BYTES:
            raise ValueError("runtime image read bound exceeded")
        digest.update(block)
    after = os.fstat(descriptor)
    fields = ("st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns", "st_mode", "st_uid", "st_nlink")
    if count != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields):
        raise ValueError("runtime image changed during descriptor read")
    os.lseek(descriptor, 0, os.SEEK_SET)
    return {
        "sha256": digest.hexdigest(),
        "bytes": count,
        "device": before.st_dev,
        "inode": before.st_ino,
        "mode": stat.S_IMODE(before.st_mode),
        "mtime_ns": before.st_mtime_ns,
        "ctime_ns": before.st_ctime_ns,
    }


def image_identity(path: Path) -> dict[str, Any]:
    descriptor = os.open(path.resolve(strict=True), os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        return _read_identity(descriptor, owned=False)
    finally:
        os.close(descriptor)


@contextlib.contextmanager
def pinned_extension(path: Path, *, expected_sha256: str) -> Any:
    if re.fullmatch("[0-9a-f]{64}", expected_sha256) is None:
        raise ValueError("exact extension SHA256 is required")
    descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        identity = _read_identity(descriptor, owned=True)
        if identity["bytes"] > 8 * 1024 * 1024:
            raise ValueError("extension exceeds the 8 MiB image bound")
        if identity["sha256"] != expected_sha256:
            raise ValueError("extension content does not match the admitted SHA256")
        yield descriptor, identity
        after = _read_identity(descriptor, owned=True)
        if after != identity:
            raise ValueError("extension identity changed during observation")
    finally:
        os.close(descriptor)


def code_mapping(address: str) -> dict[str, Any]:
    """Read only the exact executable mapping containing the reported C callback."""
    if re.fullmatch(r"0x[0-9a-f]{1,16}", address) is None:
        raise ValueError("invalid callback address")
    value = int(address, 16)
    maps = Path("/proc/self/maps").read_bytes()
    if len(maps) > 4 * 1024 * 1024:
        raise ValueError("process mapping metadata exceeds its observation bound")
    matches = []
    for raw in maps.decode("utf-8", errors="strict").splitlines():
        fields = raw.split(maxsplit=5)
        if len(fields) < 5:
            raise ValueError("invalid process mapping metadata")
        start, end = (int(part, 16) for part in fields[0].split("-"))
        if start <= value < end:
            major, minor = (int(part, 16) for part in fields[3].split(":"))
            matches.append(
                {
                    "device": os.makedev(major, minor),
                    "inode": int(fields[4]),
                    "permissions": fields[1],
                    "file_offset": int(fields[2], 16),
                }
            )
    if len(matches) != 1 or "x" not in matches[0]["permissions"] or "w" in matches[0]["permissions"]:
        raise ValueError("callback lacks one non-writable executable file mapping")
    if matches[0]["inode"] == 0:
        raise ValueError("anonymous callback mappings are outside observation admission")
    return matches[0]


def already_mapped(identity: dict[str, Any]) -> bool:
    maps = Path("/proc/self/maps").read_bytes()
    if len(maps) > 4 * 1024 * 1024:
        raise ValueError("process mapping metadata exceeds its observation bound")
    for raw in maps.decode("utf-8", errors="strict").splitlines():
        fields = raw.split(maxsplit=5)
        if len(fields) < 5:
            raise ValueError("invalid process mapping metadata")
        major, minor = (int(part, 16) for part in fields[3].split(":"))
        if os.makedev(major, minor) == identity["device"] and int(fields[4]) == identity["inode"]:
            return True
    return False

"""Frozen, synthetic hook workloads and independent delivered-response oracles.

No runtime response renderer is imported here. These expectations describe the
2e672d2 contract; updating candidate code must not silently update its oracle.
The daemon-adapter boundary is explicit: it does not prove installed CLI stdout,
exit status, or observation-only hooks' ability to withhold model output.
"""

from __future__ import annotations

import hashlib
import json
import platform
from collections import Counter
from collections.abc import Mapping
from dataclasses import dataclass
from dataclasses import replace as replace
from pathlib import Path
from typing import cast

from scripts.native_slo_workload_cases import build_cases as build_cases

_CORPUS_PATH = Path(__file__).resolve().parents[1] / "tests/fixtures/guard-native-qualification/corpus.v1.json"
_MAX_CASES = 2_048
_REMAINING_MS = 4_000
_MISSING = object()
_POLICY_RISK_KEYS = (
    "local_secret_read",
    "credential_exfiltration",
    "data_flow_exfiltration",
    "destructive_shell",
    "encoded_execution",
    "network_egress",
    "prompt_injection",
    "mcp_dangerous_tool",
    "malicious_skill",
    "package_script",
    "persistence",
    "guard_bypass",
    "cloud_advisory",
    "encoded_exfiltration",
    "execution",
    "supply_chain",
    "policy_bypass",
)
_SEMANTIC_FIELDS = (
    "decision",
    "continue",
    "policy_action",
    "model_output_action",
    "reason_code",
    "behavior",
    "interrupt",
    "cancel",
    "permission",
    "hookSpecificOutput.hookEventName",
    "hookSpecificOutput.permissionDecision",
    "observe_mode",
    "observed_policy_action",
    "reviewed_output_sha256",
    "reviewed_excerpt",
)


@dataclass(frozen=True, slots=True)
class ExpectedResponse:
    """Exact semantic projection plus human-readable outcome classification."""

    decision: str
    model_action: str
    reason_class: str
    fields: Mapping[str, object]
    nonempty_fields: tuple[str, ...] = ()
    exact_empty: bool = False

    @property
    def reason_code(self) -> str | None:
        value = self.fields.get("reason_code")
        return value if isinstance(value, str) else None

    @property
    def policy_action(self) -> str | None:
        value = self.fields.get("policy_action")
        return value if isinstance(value, str) else None


@dataclass(frozen=True, slots=True)
class QualificationCase:
    case_id: str
    harness: str
    event: str
    canonical_event: str
    size_class: str
    payload: Mapping[str, object]
    expected: ExpectedResponse
    expected_route: str
    setup: str
    surface: str
    content_bytes: int
    wire_bytes: int
    payload_kind: str
    native_expected: ExpectedResponse | None = None
    boundary: str = "daemon_adapter"
    expected_http_status: int = 200
    validation_scope: str = "full_semantics"

    @property
    def semantic_sample(self) -> bool:
        source_denial = (
            self.payload_kind == "source_file_ref"
            and self.native_expected is not None
            and (self.native_expected.reason_code in {"no_output_to_review", "observe_no_output_to_review"})
        )
        return (
            self.native_expected is not None
            and self.expected_http_status == 200
            and not source_denial
            and self.validation_scope != "platform_source_reference_denial"
        )

    @property
    def installed_enforcement(self) -> bool:
        return self.surface.startswith("installed_") and self.surface != "installed_observation_only"


def corpus_manifest() -> dict[str, object]:
    value = json.loads(_CORPUS_PATH.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or value.get("schema") != "hol-guard.native-qualification-corpus.v1":
        raise ValueError("native_qualification_corpus_invalid")
    return value


def oracle_source_digest() -> str:
    """Bind both frozen expectations and the case builder used by the collector."""
    root = Path(__file__).parent
    sources = {
        name: hashlib.sha256((root / name).read_bytes()).hexdigest()
        for name in ("native_slo_workloads.py", "native_slo_workload_cases.py")
    }
    return hashlib.sha256(json.dumps(sources, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def configuration_text(setup: str) -> str:
    """Explicit synthetic policy to publish before a case, never production defaults.

    Set up a fresh private Guard home before constructing its daemon. The driver
    must inspect the acknowledged effective policy; writing TOML alone is not
    evidence that the native generation has changed.
    """

    if setup not in cast(Mapping[str, object], corpus_manifest()["setup_requirements"]):
        raise ValueError("native_qualification_setup_unknown")
    watch = setup in {"watch", "watch_unavailable"}
    return (
        f'mode = "{"observe" if watch else "enforce"}"\n'
        f'protection_posture = "{"watch" if watch else "protected"}"\n'
        "watch_auto_revert_hours = 0\n"
        'default_action = "allow"\n'
        'subprocess_action = "allow"\n'
        'unknown_publisher_action = "allow"\n'
        'changed_hash_action = "allow"\n'
        'new_network_domain_action = "allow"\n'
        "desktop_notifications = false\n"
        "[risk_actions]\n" + "".join(f'{key} = "allow"\n' for key in _POLICY_RISK_KEYS)
    )


def _pre_expected(
    harness: str, kind: str, reason: str, *, availability: bool = False, recording_only: bool = False
) -> ExpectedResponse:
    action = {"benign": "allow", "watch": "warn", "review": "review", "block": "block"}[kind]
    fields: dict[str, object] = {"policy_action": action, "reason_code": reason}
    direct_response = availability or recording_only
    decision_harness = harness in {"pi", "omp", "grok", "openclaw"} or (direct_response and harness == "hermes")
    simple = harness in {"pi", "omp"} or (direct_response and decision_harness)
    permission = "allow" if kind in {"benign", "watch"} else "deny"
    if kind == "review" and harness not in {"codex", "kimi", "grok", "zcode", "hermes", "pi", "omp"}:
        permission = "ask"
    if decision_harness:
        fields["decision"] = "allow" if kind in {"benign", "watch"} else "deny"
    if not simple:
        fields["hookSpecificOutput.hookEventName"] = "PreToolUse"
        fields["hookSpecificOutput.permissionDecision"] = permission
        if kind in {"benign", "watch"} and harness not in {"grok", "openclaw"}:
            fields["continue"] = True
    if harness in {"pi", "omp"} and kind in {"review", "block"} and not availability:
        fields["model_output_action"] = "block"
    required: tuple[str, ...] = ()
    if kind == "review":
        fields["prompted"] = True
        required = ("approval_request_id", "approval_url", "primary_approval_request_id", "primary_approval_url")
    reason_class = {"benign": "benign", "watch": "observation", "review": "review", "block": "completed_block"}[kind]
    if availability:
        reason_class = "availability_continue" if kind == "watch" else "integrity_block"
    return ExpectedResponse(permission, "not_applicable", reason_class, fields, required)


def _post_expected(harness: str, kind: str, reason: str, digest: str | None = None) -> ExpectedResponse:
    allowed = kind in {"benign", "watch"}
    action = "warn" if kind == "watch" else "allow" if allowed else "block"
    fields: dict[str, object] = {"policy_action": action}
    if harness in {"pi", "omp"}:
        fields.update(
            decision="allow" if allowed else "deny",
            model_output_action="allow_original" if allowed else "block",
            reason_code=reason,
        )
        if allowed and digest is not None:
            fields["reviewed_output_sha256"] = digest
    else:
        fields["hookSpecificOutput.hookEventName"] = "PostToolUse"
        if not allowed:
            fields.update(decision="block", model_output_action="block", reason_code=reason, **{"continue": True})
    return ExpectedResponse(
        "allow" if allowed else "block",
        "allow_original" if allowed else "block",
        "benign" if kind == "benign" else "observation" if kind == "watch" else "completed_block",
        fields,
    )


def _availability_expected(harness: str, event: str, reason: str) -> ExpectedResponse:
    if event == "PreToolUse":
        integrity = reason in {"invalid_hook_payload_reference", "daemon_hook_queue_bytes"}
        result = _pre_expected(harness, "block" if integrity else "watch", reason, availability=True)
        if integrity and harness == "hermes":
            return ExpectedResponse(
                "block", "not_applicable", "integrity_block", {**result.fields, "decision": "block"}
            )
        return result
    if event == "PermissionRequest":
        fields: dict[str, object] = {"reason_code": reason}
        if harness == "copilot":
            fields.update(behavior="deny", interrupt=False)
            return ExpectedResponse("permission_deferred", "not_applicable", "permission_continue", fields)
        fields.update({"continue": True, "hookSpecificOutput.hookEventName": event})
        return ExpectedResponse("continue", "not_applicable", "permission_continue", fields)
    if harness == "grok":
        return ExpectedResponse("observation_only", "not_applicable", "availability_continue", {}, exact_empty=True)
    fields = {"reason_code": reason, "policy_action": "allow"}
    if harness in {"hermes", "openclaw", "pi", "omp"}:
        fields["decision"] = "allow"
    else:
        fields.update({"continue": True, "hookSpecificOutput.hookEventName": event})
    return ExpectedResponse(
        "continue",
        "unreviewed_original" if event == "PostToolUse" else "not_applicable",
        "availability_continue",
        fields,
    )


def _native_pre(kind: str, reason: str) -> ExpectedResponse:
    action = "allow" if kind == "benign" else "review" if kind == "review" else "block"
    return ExpectedResponse(
        "allow" if action == "allow" else "deny",
        "not_applicable",
        kind,
        {
            "decision": "allow" if action == "allow" else "deny",
            "minimum_action": action,
            "policy_action": action,
            "reason_code": reason,
        },
    )


def _native_post(kind: str, reason: str, digest: str) -> ExpectedResponse:
    fields: dict[str, object] = {
        "decision": "allow" if kind == "benign" else "deny",
        "model_output_action": "allow_original" if kind == "benign" else "block",
        "policy_action": "allow" if kind == "benign" else "block",
        "reason_code": reason,
    }
    if kind == "benign":
        fields["reviewed_output_sha256"] = digest
    return ExpectedResponse(str(fields["decision"]), str(fields["model_output_action"]), kind, fields)


def _content(size: int, secret: bool) -> bytes:
    # Deliberately synthetic token; no credential or user source is read.
    prefix = (("gh" + "p_" + "b" * 30 + "\n") if secret else "").encode("ascii")
    unit = b"const guard_value = 1;\n"
    return prefix + (unit * ((size + len(unit) - 1) // len(unit)))[: size - len(prefix)]


def source_reference_supported(*, system: str | None = None, runtime: Path | None = None) -> bool:
    """Keep the original Windows refusal unless the exact artifact supports reads."""
    if (platform.system() if system is None else system) != "Windows":
        return True
    if runtime is None:
        return False
    from scripts.native_slo_source_witness import installed_windows_source_reference_supported

    return installed_windows_source_reference_supported(runtime)


def platform_scope_summary(
    cases: tuple[QualificationCase, ...],
    validated: list[str],
) -> dict[str, object]:
    """Keep proved platform denials separate from completed content review."""
    observed = set(validated)
    source_cases = [case for case in cases if case.payload_kind == "source_file_ref"]
    unsupported = [case for case in cases if case.validation_scope == "platform_source_reference_denial"]
    checked = [case for case in unsupported if case.case_id in observed]
    semantic = [case for case in cases if case.case_id in observed and case.semantic_sample]
    return {
        "reference_review_supported": not unsupported if source_cases else source_reference_supported(),
        "reference_review_qualified": any(case.semantic_sample for case in source_cases)
        and not unsupported
        and all(case.case_id in observed for case in source_cases),
        "platform_denial_declared_cases": len(unsupported),
        "platform_denial_validated_cases": len(checked),
        "platform_denial_contract_passed": bool(unsupported) and len(checked) == len(unsupported),
        "platform_denial_case_digests": sorted(hashlib.sha256(case.case_id.encode()).hexdigest() for case in checked),
        "semantic_validated_cases": len(semantic),
        "semantic_coverage": {
            "size": dict(Counter(case.size_class for case in semantic)),
            "representation": dict(
                Counter(
                    "file_reference" if case.payload_kind == "source_file_ref" else case.payload_kind
                    for case in semantic
                )
            ),
        },
        "missing_scopes": ["source_reference_full_content_review", "source_reference_identity_verification"]
        if unsupported
        else [],
        "platform_denial_timing_eligible": False,
    }


def _at_path(response: Mapping[str, object], path: str) -> object:
    current: object = response
    for name in path.split("."):
        if not isinstance(current, Mapping) or name not in current:
            return _MISSING
        current = current[name]
    return current


def _validate_projection(expected: ExpectedResponse, response: Mapping[str, object], case_id: str) -> None:
    if expected.exact_empty and response:
        raise AssertionError(f"native_qualification_mismatch:{case_id}:expected_empty_object")
    for path in set(_SEMANTIC_FIELDS) | set(expected.fields):
        actual = _at_path(response, path)
        wanted = expected.fields.get(path, _MISSING)
        if wanted is _MISSING:
            if actual is not _MISSING:
                raise AssertionError(f"native_qualification_mismatch:{case_id}:unexpected:{path}")
        elif type(actual) is not type(wanted) or actual != wanted:
            # Never log tool output, source paths, or credentials from a response.
            raise AssertionError(f"native_qualification_mismatch:{case_id}:field:{path}")
    for path in expected.nonempty_fields:
        actual = _at_path(response, path)
        if not isinstance(actual, str) or not actual.strip():
            raise AssertionError(f"native_qualification_mismatch:{case_id}:missing:{path}")


def validate_case(
    case: QualificationCase, response: Mapping[str, object], route: str, *, http_status: int = 200
) -> None:
    """Check one daemon-adapter result; every mismatch fails qualification."""

    if route != case.expected_route:
        raise AssertionError(f"native_qualification_mismatch:{case.case_id}:route")
    if type(http_status) is not int or http_status != case.expected_http_status:
        raise AssertionError(f"native_qualification_mismatch:{case.case_id}:http_status")
    _validate_projection(case.expected, response, case.case_id)


def validate_native_result(case: QualificationCase, response: Mapping[str, object] | None) -> None:
    """Independently check engine results before Watch/availability rendering."""

    if case.native_expected is None:
        if response is not None:
            raise AssertionError(f"native_qualification_mismatch:{case.case_id}:unexpected_native_result")
        return
    if response is None:
        raise AssertionError(f"native_qualification_mismatch:{case.case_id}:missing_native_result")
    _validate_projection(case.native_expected, response, case.case_id)


def installed_response_expectation(case: QualificationCase) -> tuple[ExpectedResponse, int]:
    """Frozen stdout/exit projection for Cursor and Cline installed wrappers.

    Other wrappers need their own observed contract and are deliberately not
    inferred from daemon JSON. This function does not execute a wrapper.
    """

    if not case.surface.startswith("installed_"):
        raise ValueError("native_qualification_not_installed_surface")
    if case.harness == "cursor":
        if case.event in {"afterShellExecution", "afterMCPExecution"}:
            return ExpectedResponse("observation_only", "unreviewed_original", "observation", {}, exact_empty=True), 0
        action = case.expected.policy_action
        permission = "deny" if action == "block" else "ask" if action == "review" else "allow"
        if case.event == "beforeReadFile" and permission == "ask":
            permission = "deny"
        required = ()
        if permission != "allow":
            required = ("user_message",) if case.event == "beforeReadFile" else ("user_message", "agent_message")
        return ExpectedResponse(
            permission, "not_applicable", case.expected.reason_class, {"permission": permission}, required
        ), 2 if permission == "deny" else 0
    if case.harness == "cline":
        blocked = case.expected.policy_action in {"review", "block"}
        pre = case.canonical_event == "PreToolUse"
        fields: dict[str, object] = {"cancel": pre and blocked}
        required = ("contextModification",) if blocked else ()
        if not blocked:
            fields["contextModification"] = ""
        if pre:
            if blocked:
                required += ("errorMessage",)
            else:
                fields["errorMessage"] = ""
        return ExpectedResponse(
            "deny" if pre and blocked else "allow" if pre else "observation_only",
            "not_applicable" if pre else "unreviewed_original",
            case.expected.reason_class,
            fields,
            required,
        ), 0
    raise ValueError("native_qualification_wrapper_oracle_unavailable")


def validate_installed_response(case: QualificationCase, response: Mapping[str, object], exit_code: int) -> None:
    """Validate actual wrapper stdout separately from its daemon response."""

    expected, wanted_exit = installed_response_expectation(case)
    if type(exit_code) is not int or exit_code != wanted_exit:
        raise AssertionError(f"native_qualification_mismatch:{case.case_id}:installed_exit")
    _validate_projection(expected, response, case.case_id)


def validate_setup(case: QualificationCase, evidence: Mapping[str, object]) -> None:
    """Require separately witnessed setup; a label alone is not a fault proof."""

    requirements = cast(dict[str, list[str]], corpus_manifest()["setup_requirements"])[case.setup]
    for requirement in requirements:
        if evidence.get(requirement) is not True:
            raise AssertionError(f"native_qualification_setup_unproven:{case.case_id}:{requirement}")


__all__ = [
    "ExpectedResponse",
    "QualificationCase",
    "build_cases",
    "configuration_text",
    "corpus_manifest",
    "installed_response_expectation",
    "oracle_source_digest",
    "platform_scope_summary",
    "source_reference_supported",
    "validate_case",
    "validate_installed_response",
    "validate_native_result",
    "validate_setup",
]

#!/usr/bin/env python3
"""Keep repository version files aligned."""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass
from pathlib import Path

from packaging.version import InvalidVersion, Version

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python 3.10 fallback
    import tomli as tomllib

PYPROJECT_RELATIVE_PATH = Path("pyproject.toml")
MODULE_RELATIVE_PATH = Path("src/codex_plugin_scanner/version.py")
LOCKFILE_RELATIVE_PATH = Path("uv.lock")
TOML_TABLE_HEADER_PATTERN = re.compile(r"^\[[A-Za-z0-9_.-]+\]$")
PYPROJECT_VERSION_LINE_PATTERN = re.compile(
    r'^(?P<prefix>\s*version\s*=\s*["\'])(?P<version>[^"\']+)(?P<suffix>["\'](?:\s+#.*)?\s*)$'
)
MODULE_VERSION_LINE_PATTERN = re.compile(
    r'^(?P<prefix>\s*__version__\s*=\s*["\'])(?P<version>[^"\']+)(?P<suffix>["\'](?:\s+#.*)?\s*)$',
    re.MULTILINE,
)


@dataclass(frozen=True)
class RepoVersionState:
    pyproject: str
    module: str
    lockfile: str


def _default_repo_root() -> Path:
    return Path(__file__).resolve().parents[1]


def _validate_version_token(version: str) -> str:
    try:
        Version(version)
    except InvalidVersion as exc:
        raise ValueError(f"Unsupported version format: {version}") from exc
    return version


def _read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def _read_pyproject_version(path: Path) -> str:
    project = tomllib.loads(_read_text(path)).get("project")
    if not isinstance(project, dict):
        raise ValueError(f"Could not find [project] table in {path}")
    version = project.get("version")
    if not isinstance(version, str):
        raise ValueError(f"Could not find [project].version in {path}")
    return version


def _extract_version(path: Path, pattern: re.Pattern[str], label: str) -> str:
    match = pattern.search(_read_text(path))
    if match is None:
        raise ValueError(f"Could not find {label} version in {path}")
    return match.group("version")


def read_repo_version_state(repo_root: Path) -> RepoVersionState:
    return RepoVersionState(
        pyproject=_read_pyproject_version(repo_root / PYPROJECT_RELATIVE_PATH),
        module=_extract_version(
            repo_root / MODULE_RELATIVE_PATH,
            MODULE_VERSION_LINE_PATTERN,
            "module",
        ),
        lockfile=_read_lockfile_version(repo_root / LOCKFILE_RELATIVE_PATH),
    )


def assert_repo_version(repo_root: Path, expected_version: str | None = None) -> str:
    if expected_version is not None:
        _validate_version_token(expected_version)
    state = read_repo_version_state(repo_root)
    if state.pyproject != state.module or state.pyproject != state.lockfile:
        raise ValueError(
            "Repository version mismatch: "
            f"{PYPROJECT_RELATIVE_PATH} has {state.pyproject}, "
            f"{MODULE_RELATIVE_PATH} has {state.module}, "
            f"{LOCKFILE_RELATIVE_PATH} has {state.lockfile}"
        )
    if expected_version is not None and state.pyproject != expected_version:
        raise ValueError(f"Repository version mismatch: expected {expected_version}, found {state.pyproject}")
    return state.pyproject


def _replace_matching_line(line: str, pattern: re.Pattern[str], version: str) -> str:
    line_body = line.rstrip("\r\n")
    line_ending = line[len(line_body) :]
    match = pattern.match(line_body)
    if match is None:
        return line
    return f"{match.group('prefix')}{version}{match.group('suffix')}{line_ending}"


def _replace_project_version(path: Path, version: str) -> tuple[str, bool]:
    text = _read_text(path)
    lines = text.splitlines(keepends=True)
    in_project_table = False
    project_version_index: int | None = None

    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped == "[project]":
            in_project_table = True
            continue
        if in_project_table and TOML_TABLE_HEADER_PATTERN.fullmatch(stripped):
            break
        if not in_project_table:
            continue
        if PYPROJECT_VERSION_LINE_PATTERN.match(line.rstrip("\r\n")) is not None:
            lines[index] = _replace_matching_line(line, PYPROJECT_VERSION_LINE_PATTERN, version)
            project_version_index = index
            break

    if project_version_index is None:
        raise ValueError(f"Could not update [project].version in {path}")

    updated_text = "".join(lines)
    return updated_text, updated_text != text


def _replace_module_version(path: Path, version: str) -> tuple[str, bool]:
    text = _read_text(path)
    lines = text.splitlines(keepends=True)
    module_version_index: int | None = None

    for index, line in enumerate(lines):
        if MODULE_VERSION_LINE_PATTERN.match(line.rstrip("\r\n")) is not None:
            lines[index] = _replace_matching_line(line, MODULE_VERSION_LINE_PATTERN, version)
            module_version_index = index
            break

    if module_version_index is None:
        raise ValueError(f"Could not update module version line in {path}")

    updated_text = "".join(lines)
    return updated_text, updated_text != text


def _find_lockfile_version_index(lines: list[str], path: Path) -> int:
    in_package_block = False
    package_name_matches = False
    editable_source_matches = False
    version_index: int | None = None

    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped == "[[package]]":
            if in_package_block and package_name_matches and editable_source_matches and version_index is not None:
                return version_index
            in_package_block = True
            package_name_matches = False
            editable_source_matches = False
            version_index = None
            continue
        if not in_package_block:
            continue
        if stripped.startswith("name = "):
            package_name_matches = stripped == 'name = "hol-guard"'
            continue
        if stripped.startswith("version = ") and version_index is None:
            version_index = index
            continue
        if stripped.startswith("source = "):
            editable_source_matches = stripped == 'source = { editable = "." }'

    if in_package_block and package_name_matches and editable_source_matches and version_index is not None:
        return version_index
    raise ValueError(f"Could not find editable hol-guard package version in {path}")


def _read_lockfile_version(path: Path) -> str:
    lines = _read_text(path).splitlines(keepends=True)
    version_index = _find_lockfile_version_index(lines, path)
    version_line = lines[version_index].rstrip("\r\n")
    match = PYPROJECT_VERSION_LINE_PATTERN.match(version_line)
    if match is None:
        raise ValueError(f"Could not parse lockfile version in {path}")
    return match.group("version")


def _replace_lockfile_version(path: Path, version: str) -> tuple[str, bool]:
    lines = _read_text(path).splitlines(keepends=True)
    version_index = _find_lockfile_version_index(lines, path)
    replaced_line = _replace_matching_line(lines[version_index], PYPROJECT_VERSION_LINE_PATTERN, version)
    if replaced_line == lines[version_index]:
        return "".join(lines), False
    lines[version_index] = replaced_line
    return "".join(lines), True


def sync_repo_version(repo_root: Path, version: str) -> bool:
    normalized_version = _validate_version_token(version)
    pyproject_path = repo_root / PYPROJECT_RELATIVE_PATH
    module_path = repo_root / MODULE_RELATIVE_PATH
    lockfile_path = repo_root / LOCKFILE_RELATIVE_PATH

    pyproject_text, pyproject_changed = _replace_project_version(pyproject_path, normalized_version)
    module_text, module_changed = _replace_module_version(module_path, normalized_version)
    lockfile_text, lockfile_changed = _replace_lockfile_version(lockfile_path, normalized_version)

    if pyproject_changed:
        pyproject_path.write_text(pyproject_text, encoding="utf-8")
    if module_changed:
        module_path.write_text(module_text, encoding="utf-8")
    if lockfile_changed:
        lockfile_path.write_text(lockfile_text, encoding="utf-8")

    assert_repo_version(repo_root, normalized_version)
    return pyproject_changed or module_changed or lockfile_changed


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument(
        "--check",
        action="store_true",
        help="Validate that repository version files match and print the current version.",
    )
    mode.add_argument(
        "--version",
        help="Sync both repository version files to the supplied semantic version.",
    )
    parser.add_argument(
        "--repo-root",
        type=Path,
        default=_default_repo_root(),
        help="Repository root to inspect. Defaults to the current hol-guard checkout.",
    )
    return parser


def main() -> int:
    parser = _build_parser()
    args = parser.parse_args()
    repo_root = args.repo_root.resolve()
    try:
        if args.version is not None:
            sync_repo_version(repo_root, args.version)
            print(_validate_version_token(args.version))
            return 0
        current_version = assert_repo_version(repo_root)
        print(current_version)
        return 0
    except ValueError as error:
        print(f"Error: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Linux executable digest reuse bound to an already attested live child.

This module never authorizes a process launch. A new child always needs fresh
full-byte admission, even when another child pins the same executable. Linux
rejects writes to a running executable (ETXTBSY); a live process, its start
marker, image inode, and a local filesystem establish the retained image proof.
Path/stat information alone is only an invalidation hint and is never a proof.
Other platforms and filesystem types retain full validation.
"""

from __future__ import annotations

import errno
import hashlib
import os
import stat
import subprocess
import sys
import threading
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Literal

if TYPE_CHECKING:
    from .native_runtime import NativeRuntimeIdentity, NativeRuntimeStatus

_LOCAL_EXECUTABLE_FILESYSTEMS = frozenset({"ext2", "ext3", "ext4", "xfs", "btrfs", "tmpfs"})
_MAX_MOUNTINFO_BYTES = 1024 * 1024
_MAX_MANIFEST_BYTES = 16 * 1024
_MAX_ATTESTATIONS = 256
_LOCK = threading.Lock()
_digest_reuse_suspended = False


@dataclass(frozen=True)
class NativeProcessAttestation:
    """An exact child/image proof, consumed only by that existing child."""

    process: subprocess.Popen[bytes]
    identity: NativeRuntimeIdentity
    image_metadata: tuple[int, ...]
    process_start_marker: str
    package_version: str
    manifest_binding: tuple[tuple[int, ...], bytes]


_ATTESTATIONS: dict[int, NativeProcessAttestation] = {}
# These entries grant no trust. They prevent another child on the same path
# from enabling digest reuse while an uninspectable client is still live.
_FULL_VALIDATION_CLIENTS: dict[int, tuple[subprocess.Popen[bytes], Path]] = {}


@dataclass(frozen=True)
class NativeProcessAttestationResult:
    status: Literal["verified", "unsupported", "invalid"]
    attestation: NativeProcessAttestation | None = None


@dataclass(frozen=True)
class NativeProcessImageInspection:
    status: Literal["verified", "unsupported", "invalid"]
    path_metadata: tuple[int, ...] | None = None
    process_start_marker: str | None = None


def _metadata_binding(metadata: os.stat_result) -> tuple[int, ...]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_uid,
        metadata.st_gid,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


def runtime_pool_generation_hint(executable: Path) -> tuple[tuple[int, ...] | None, ...]:
    """Retire a pool when its files change; this hint grants no authority."""

    result: list[tuple[int, ...] | None] = []
    for path in (executable, executable.with_name("runtime-manifest.json")):
        try:
            result.append(_metadata_binding(path.lstat()))
        except OSError:
            result.append(None)
    return tuple(result)


def _manifest_binding(executable: Path) -> tuple[tuple[int, ...], bytes] | None:
    path = executable.with_name("runtime-manifest.json")
    try:
        before = path.lstat()
        if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= _MAX_MANIFEST_BYTES:
            return None
        with path.open("rb") as stream:
            content = stream.read(_MAX_MANIFEST_BYTES + 1)
        after = path.lstat()
        if len(content) > _MAX_MANIFEST_BYTES or _metadata_binding(before) != _metadata_binding(after):
            return None
        return _metadata_binding(after), hashlib.sha256(content).digest()
    except (OSError, RuntimeError, ValueError):
        return None


def _inspect_process_image(process: subprocess.Popen[bytes], executable: Path) -> NativeProcessImageInspection:
    """Separate an unavailable kernel interface from observed bad identity.

    Only errors from /proc inspection can be unsupported. Missing/unsafe
    installation metadata and affirmative process/image mismatches are invalid.
    """

    try:
        if process.poll() is not None:
            return NativeProcessImageInspection("invalid")
        lexical = executable.lstat()
        if (
            not stat.S_ISREG(lexical.st_mode)
            or stat.S_IMODE(lexical.st_mode) & 0o022
            or lexical.st_uid not in {0, os.getuid()}
        ):
            return NativeProcessImageInspection("invalid")
        metadata = _metadata_binding(lexical)
    except (OSError, RuntimeError, ValueError):
        return NativeProcessImageInspection("invalid")
    start_marker: str | None = None
    try:
        proc = Path("/proc") / str(process.pid)
        process_stat = (proc / "stat").read_text(encoding="ascii")
        prefix, suffix = process_stat.rsplit(")", 1)
        fields = suffix.split()
        if (
            prefix.split("(", 1)[0].strip() != str(process.pid)
            or len(fields) < 20
            or fields[0] in {"Z", "X", "x"}
            or fields[1] != str(os.getpid())
            or not fields[19].isdigit()
        ):
            return NativeProcessImageInspection("invalid")
        start_marker = fields[19]
        image = (proc / "exe").stat()
        if not stat.S_ISREG(image.st_mode) or metadata != _metadata_binding(image) or process.poll() is not None:
            return NativeProcessImageInspection("invalid")
        return NativeProcessImageInspection("verified", metadata, start_marker)
    except OSError as error:
        unsupported_errors = {errno.EACCES, errno.EPERM, errno.ENOENT, errno.ENOSYS, errno.ENOTSUP}
        if error.errno in unsupported_errors and process.poll() is None:
            return NativeProcessImageInspection("unsupported", metadata, start_marker)
        return NativeProcessImageInspection("invalid")
    except (RuntimeError, ValueError):
        return NativeProcessImageInspection("invalid")


def _process_image(process: subprocess.Popen[bytes], executable: Path) -> tuple[tuple[int, ...], str] | None:
    inspected = _inspect_process_image(process, executable)
    if inspected.status != "verified" or inspected.path_metadata is None or inspected.process_start_marker is None:
        return None
    return inspected.path_metadata, inspected.process_start_marker


def _prune_finished_clients_locked() -> None:
    for key, item in tuple(_ATTESTATIONS.items()):
        if item.process.poll() is not None:
            _ = _ATTESTATIONS.pop(key, None)
    for key, (process, _) in tuple(_FULL_VALIDATION_CLIENTS.items()):
        if process.poll() is not None:
            _ = _FULL_VALIDATION_CLIENTS.pop(key, None)


def _has_full_validation_client_locked(executable: Path) -> bool:
    for key, (process, path) in tuple(_FULL_VALIDATION_CLIENTS.items()):
        if path != executable:
            continue
        if process.poll() is None:
            return True
        _ = _FULL_VALIDATION_CLIENTS.pop(key, None)
    return False


def _registry_slot_available_locked(process: subprocess.Popen[bytes]) -> bool:
    """Capacity failure disables reuse, never ordinary full admission.

    An untracked live client cannot permit indirect reuse. A process-lifetime
    latch provides that guarantee without an unbounded overflow registry.
    """

    global _digest_reuse_suspended
    _prune_finished_clients_locked()
    if _digest_reuse_suspended:
        return False
    if id(process) in _ATTESTATIONS or id(process) in _FULL_VALIDATION_CLIENTS:
        return True
    if len(_ATTESTATIONS) + len(_FULL_VALIDATION_CLIENTS) >= _MAX_ATTESTATIONS:
        _digest_reuse_suspended = True
        return False
    return True


def _local_executable_filesystem(process: subprocess.Popen[bytes]) -> bool:
    """Use the opened image's mount ID, not a guessed path-prefix mount."""

    try:
        with (Path("/proc") / str(process.pid) / "exe").open("rb") as image:
            descriptor_info = (Path("/proc/self/fdinfo") / str(image.fileno())).read_text(encoding="ascii")
            mount_id = next(
                (line.split(":", 1)[1].strip() for line in descriptor_info.splitlines() if line.startswith("mnt_id:")),
                None,
            )
            if mount_id is None:
                return False
            with Path("/proc/self/mountinfo").open("rb") as mounts:
                content = mounts.read(_MAX_MOUNTINFO_BYTES + 1)
            if len(content) > _MAX_MOUNTINFO_BYTES:
                return False
            for line in content.decode("utf-8", errors="strict").splitlines():
                if line.split(" ", 1)[0] != mount_id:
                    continue
                _, separator, filesystem = line.partition(" - ")
                return bool(separator) and filesystem.split(" ", 1)[0] in _LOCAL_EXECUTABLE_FILESYSTEMS
    except (OSError, RuntimeError, ValueError):
        return False
    return False


def attest_native_process(
    process: subprocess.Popen[bytes],
    expected: NativeRuntimeStatus,
    *,
    verify: Callable[[], NativeRuntimeStatus],
    package_version: Callable[[], str | None],
) -> NativeProcessAttestationResult:
    """Hash again while the actual child pins the executable, then register it.

    Unsupported local proof retains full validation. A failed identity proof is
    distinct: the caller must close that child before writing any hook frame.
    """

    if sys.platform != "linux" or expected.identity is None or expected.capabilities is None:
        return NativeProcessAttestationResult("unsupported")
    if not expected.available or not expected.compatible:
        return NativeProcessAttestationResult("invalid")
    executable = expected.identity.path
    before = _inspect_process_image(process, executable)
    if before.status == "invalid":
        return NativeProcessAttestationResult("invalid")
    reusable_filesystem = before.status == "verified" and _local_executable_filesystem(process)
    manifest = _manifest_binding(executable)
    verified = verify()
    after = _inspect_process_image(process, executable)
    version = package_version()
    if (
        after.status == "invalid"
        or before.path_metadata != after.path_metadata
        or (
            before.process_start_marker is not None
            and after.process_start_marker is not None
            and before.process_start_marker != after.process_start_marker
        )
        or manifest is None
        or manifest != _manifest_binding(executable)
        or verified != expected
        or version != expected.capabilities.runtime_version
        or process.poll() is not None
    ):
        return NativeProcessAttestationResult("invalid")
    if not reusable_filesystem or after.status != "verified":
        # A full pre-launch and post-launch validation remains authoritative
        # when the kernel cannot expose image/start proof. Never cache that
        # ambiguity, including indirectly through another child on this path.
        with _LOCK:
            if not _registry_slot_available_locked(process):
                return NativeProcessAttestationResult("unsupported")
            _ = _ATTESTATIONS.pop(id(process), None)
            _FULL_VALIDATION_CLIENTS[id(process)] = (process, executable)
        return NativeProcessAttestationResult("unsupported")
    assert version is not None
    assert before.path_metadata is not None and before.process_start_marker is not None
    attestation = NativeProcessAttestation(
        process, expected.identity, before.path_metadata, before.process_start_marker, version, manifest
    )
    with _LOCK:
        if not _registry_slot_available_locked(process):
            return NativeProcessAttestationResult("unsupported")
        _ = _FULL_VALIDATION_CLIENTS.pop(id(process), None)
        _ATTESTATIONS[id(process)] = attestation
    return NativeProcessAttestationResult("verified", attestation)


def attestation_is_current(attestation: NativeProcessAttestation, *, package_version: str | None) -> bool:
    with _LOCK:
        registered = _ATTESTATIONS.get(id(attestation.process)) is attestation
    if not (
        registered
        and package_version == attestation.package_version
        and _process_image(attestation.process, attestation.identity.path)
        == (attestation.image_metadata, attestation.process_start_marker)
        and _manifest_binding(attestation.identity.path) == attestation.manifest_binding
    ):
        return False
    # File probes may run concurrently with retirement. This final registry
    # check is the success linearization point; no IO runs under the lock.
    with _LOCK:
        return _ATTESTATIONS.get(id(attestation.process)) is attestation


def live_native_identity(
    executable: Path, *, package_version: Callable[[], str | None]
) -> NativeRuntimeIdentity | None:
    if sys.platform != "linux":
        return None
    with _LOCK:
        if _digest_reuse_suspended or _has_full_validation_client_locked(executable):
            return None
        candidates = tuple(item for item in _ATTESTATIONS.values() if item.identity.path == executable)
    if not candidates:
        return None
    version = package_version()
    for candidate in candidates:
        if attestation_is_current(candidate, package_version=version):
            # A non-reusable client may register while file probes run.
            with _LOCK:
                if (
                    _ATTESTATIONS.get(id(candidate.process)) is candidate
                    and not _digest_reuse_suspended
                    and not _has_full_validation_client_locked(executable)
                ):
                    return candidate.identity
            return None
        with _LOCK:
            # A concurrent full-validation registration for this process must
            # keep its path blocker even when an older attestation is stale.
            if _ATTESTATIONS.get(id(candidate.process)) is candidate:
                _ = _ATTESTATIONS.pop(id(candidate.process), None)
    return None


def retire_native_process(process: subprocess.Popen[bytes]) -> None:
    with _LOCK:
        _ = _ATTESTATIONS.pop(id(process), None)
        _ = _FULL_VALIDATION_CLIENTS.pop(id(process), None)


def retire_native_path(executable: Path) -> None:
    with _LOCK:
        for key in tuple(key for key, item in _ATTESTATIONS.items() if item.identity.path == executable):
            _ATTESTATIONS.pop(key, None)

